import{a as e}from"./jsx-runtime-Bzw2jH9X.js";var t=e({default:()=>n}),n=JSON.parse(`[{"id":"qx-a2-001","clusterId":"A","werkstueckRef":"A.12","stufe":1,"question":"Maja sagt: „Stell dir mal vor, die Geheimdienste hätten alles von langer Hand geplant, und dann passiert genau das, was man jetzt in den Nachrichten sieht. Passt doch alles zusammen, also muss es so gewesen sein.“ Woran erkennst du, dass das keine tragfähige Überlegung ist?","options":["Sie legt weder Annahmen noch Spielregeln fest und kreist um eine bereits feststehende Überzeugung, statt prüfbare Folgen herzuleiten.","Sie beruft sich auf den Rang einer vermeintlichen Autorität statt auf Gründe, obwohl der Sprecher kein Argument ersetzt.","Sie verallgemeinert aus wenigen Einzelfällen auf eine Regel für alle Ereignisse dieser Art, obwohl so wenige Fälle keine Regel tragen.","Sie vernachlässigt die Ausgangshäufigkeit solcher Ereignisse, statt die Basisrate in ihre Wahrscheinlichkeitsabschätzung einzubeziehen."],"correctIndex":0,"explanation":"Ein Gedankenexperiment legt die Annahme und die Spielregeln vorab fest und folgt dann konsequent der Logik, um Stimmigkeit und Folgen zu prüfen. Majas Überlegung tut das Gegenteil: Sie beginnt beim gewünschten Ergebnis und schmückt es aus. Dass „alles zusammenpasst“, ist bei einer frei erzählten Geschichte kein Wunder, denn sie lässt sich beliebig anpassen. Entscheidend ist, ob Regeln gelten und ob sich daraus Schlüsse ziehen lassen, die man nachprüfen kann; ein erfundenes Szenario ist dagegen nicht das Problem, auch Einstein stellte sich vor, einem Lichtstrahl hinterherzujagen. Und selbst ein sauber durchgeführtes Gedankenexperiment liefert keinen Befund über die Wirklichkeit, sondern prüft nur, ob eine Idee in sich stimmig ist. Die anderen Einwände sind für sich bedenkenswert, treffen Majas Satz aber nicht: Sie beruft sich auf keine Autorität, sie verallgemeinert nicht aus Einzelfällen, und sie rechnet keine Wahrscheinlichkeit vor, bei der eine Basisrate fehlen könnte.","coreRule":"⚡ Ein Gedankenexperiment braucht klare Anfangsbedingungen und Regeln und leitet prüfbare Folgen her. Eine Geschichte, die nur eine fertige Überzeugung ausschmückt, ist kein Test.","quote":"","quoteLabel":"","beleg":"Werkstück A.12 (Kontext & Tiefe; Red Flag „Unstrukturierte Fantasie“; Der Kipppunkt)","status":"entwurf","scenario":"","kurz":"Maja beginnt beim gewünschten Ergebnis und erzählt es aus. Dass „alles zusammenpasst“, ist kein Wunder, denn eine frei erfundene Geschichte lässt sich beliebig anpassen. Tragfähig wäre sie nur mit festen Regeln und nachprüfbaren Folgen.","prueffrage":"Hätte Maja dieselbe Geschichte auch erzählen können, wenn in den Nachrichten etwas ganz anderes passiert wäre?","rueckmeldung":[{"option":1,"text":"Autoritätsberufungen sind ein verbreiteter Fehler, doch Maja zitiert niemanden als Gewährsmann. Die Geheimdienste sind bloß Figuren ihrer erzählten Geschichte. Der Mangel liegt woanders: Es gibt keine festen Regeln und keine prüfbaren Folgen."},{"option":2,"text":"Von Einzelfällen auf eine Regel zu schließen wäre tatsächlich ein Fehler, aber Maja nennt gar keine Fälle. Sie erzählt ein einziges Szenario und hält es für erwiesen, weil es stimmig wirkt. Das Problem ist diese Selbstbestätigung."},{"option":3,"text":"Basisraten zu übergehen ist ein echter Fehler, wenn man Wahrscheinlichkeiten abschätzt. Maja schätzt aber nichts ab, also fehlt auch keine Basisrate. Sie stützt sich allein darauf, dass die Geschichte zu den Nachrichten passt."}],"familie":"zu-ende-denken","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Stanford Encyclopedia of Philosophy: Thought Experiments (überarb. 28.11.2023)","oeffentlich":true,"url":"https://plato.stanford.edu/entries/thought-experiment/","abruf":"2026-10-12"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"0edece4a20a619e4"}},{"id":"qx-a2-002","clusterId":"A","werkstueckRef":"A.12","stufe":2,"question":"Welcher Prüfschritt deckt am besten auf, ob diese Behauptung in sich stimmig ist?","scenario":"Eine Bekannte erklärt dir beim Kaffee: „Deine Gedanken erschaffen deine Realität. Wer fest genug an etwas denkt, bekommt es auch.“ Du willst die Behauptung prüfen, ohne gleich ein aufwendiges Experiment zu planen.","options":["Du nimmst an, sie gelte für alle Menschen gleichzeitig, und suchst nach Widersprüchen, etwa wenn zwei Menschen sich denselben einmaligen Lottogewinn vorstellen.","Du vergleichst eine Gruppe, die fest an etwas denkt, mit einer Kontrollgruppe, die das nicht tut, und zählst nach, in welcher Gruppe sich mehr Wünsche erfüllen.","Du fragst, ob die Bekannte an ihrer Aussage verdient oder sonst ein Eigeninteresse hat, und gewichtest ihre Behauptung danach, wem sie nützen würde.","Du prüfst, ob sich berichtete Erfolgsgeschichten einfacher durch Zufall oder Auswahl erklären lassen, und ziehst die einfachste passende Erklärung vor."],"correctIndex":0,"explanation":"Ein Gedankenexperiment macht eine Behauptung testbar, ohne dass man sie in der Wirklichkeit ausprobieren muss: Man setzt sie als wahr voraus und spielt durch, was daraus folgt. Gilt der Satz für alle 8 Milliarden Menschen, müsste derselbe einmalige Lottogewinn mehreren Menschen zufallen. Ein Diktator, der sich den Gehorsam aller wünscht, und ein Freiheitskämpfer, der sich die Freiheit aller wünscht, würden unvereinbare Realitäten erzeugen. Eine Behauptung, die im Maßstab in Widersprüche gerät, ist in sich nicht stimmig. Die anderen Schritte sind in anderer Lage nützlich, beantworten hier aber nicht die Frage nach der inneren Stimmigkeit: Eine Kontrollgruppe wäre genau das aufwendige Experiment, das du vermeiden willst. Das Eigeninteresse der Bekannten sagt nichts darüber, ob ihr Satz in sich stimmt, und ob sich Erfolge durch Zufall erklären ließen, zeigt nichts über die Logik der Behauptung.","coreRule":"⚡ Prüfe eine Behauptung, indem du sie als wahr annimmst und im großen Maßstab durchspielst: Bleibt sie widerspruchsfrei?","beleg":"Werkstück A.12 (Anwendung: Esoterik & New Age, „Gesetz der Anziehung“)","status":"entwurf","kurz":"Setzt du den Satz als wahr voraus und spielst durch, was für alle Menschen zugleich folgt, geraten die Wünsche in Konflikt, etwa beim einmaligen Lottogewinn. Das deckt die innere Unstimmigkeit auf, ohne dass du etwas ausprobieren musst.","prueffrage":"Erfährst du aus gezählten Erfolgen oder aus dem Ruf einer Person, ob der Satz sich selbst widerspricht?","rueckmeldung":[{"option":1,"text":"Ein Vergleich mit Kontrollgruppe wäre ein gutes Mittel, um die Wirkung zu testen. Du wolltest aber gerade kein aufwendiges Experiment planen, und er sagt auch nichts darüber, ob der Satz in sich stimmig ist."},{"option":2,"text":"Ein Eigeninteresse kann misstrauisch machen und ist in anderen Situationen ein brauchbarer Hinweis. Ob ein Satz in sich stimmig ist, zeigt es nicht, denn auch eine interessengeleitete Behauptung kann wahr sein."},{"option":3,"text":"Zufall und Auswahl erklären Erfolgsgeschichten oft einfacher, das ist ein nützlicher Gedanke. Hier liegen aber gar keine Berichte vor, und die Frage nach der Logik der Behauptung beantwortet dieser Schritt nicht."}],"familie":"zu-ende-denken","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Stanford Encyclopedia of Philosophy: Thought Experiments (überarb. 28.11.2023)","oeffentlich":true,"url":"https://plato.stanford.edu/entries/thought-experiment/","abruf":"2026-10-12"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"160fe9b2ac14dbc6"}},{"id":"qx-a2-003","clusterId":"A","werkstueckRef":"A.12","stufe":3,"question":"Ein Redner sagt: „Mein Gedankenexperiment zeigt, dass Wasser ein Gedächtnis hat, denn man kann es widerspruchsfrei durchspielen.“ Was ist an diesem Schluss fehlerhaft?","options":["Widerspruchsfreiheit zeigt nur, dass die Idee denkbar und in sich stimmig ist, nicht dass sie in der Wirklichkeit tatsächlich zutrifft.","Er stützt sich auf einzelne Erfahrungsberichte statt auf systematische Daten, obwohl Einzelfälle zufällig und verzerrt sein können.","Er beruft sich auf die weite Verbreitung der Idee, obwohl die Zahl der Menschen, die etwas glauben, nichts über dessen Wahrheit sagt.","Er widerlegt eine Karikatur der Gegenposition statt ihrer eigentlichen Argumente, sodass ein Strohmann seinen Schluss trägt."],"correctIndex":0,"explanation":"Ein Gedankenexperiment prüft die logische Stimmigkeit einer Annahme, mehr nicht. Fällt eine Idee dabei durch, weil sie sich selbst widerspricht, muss man sie gar nicht erst an der Wirklichkeit testen. Besteht sie die Prüfung, ist sie damit noch nicht wahr: Nur weil eine Idee ein Gedankenexperiment überlebt, heißt das noch lange nicht, dass sie wahr ist. Ob Wasser ein Gedächtnis hat, entscheidet am Ende die Realität, nicht die Vorstellungskraft. Dabei sind Annahmen, die der Wirklichkeit widersprechen, durchaus erlaubt (Einstein ließ sich auf einem Lichtstrahl reiten), solange sie als Annahmen kenntlich bleiben und das Ergebnis nicht mit einem Beweis verwechselt wird. Die anderen Denkfehler gibt es durchaus, sie kommen hier aber nicht vor: Der Redner beruft sich weder auf Einzelfälle noch auf die Verbreitung der Idee, und eine Gegenposition, die er verzerren könnte, nennt er nicht.","coreRule":"⚡ Überleben im Gedankenexperiment heißt „möglich“, nicht „wahr“; entscheiden muss die Realität.","beleg":"Werkstück A.12 (Red Flags; Der Kipppunkt)","status":"entwurf","kurz":"Ein Gedankenexperiment prüft nur, ob eine Idee in sich stimmig ist, nicht ob sie in der Wirklichkeit zutrifft. Der Fehler liegt darin, aus „widerspruchsfrei durchspielbar“ auf „wahr“ zu schließen; ob Wasser ein Gedächtnis hat, entscheidet die Realität.","prueffrage":"Welche Messung oder Beobachtung könnte zeigen, dass der Redner mit seiner Behauptung danebenliegt?","rueckmeldung":[{"option":1,"text":"Einzelfälle sind tatsächlich ein häufiger Schwachpunkt, hier aber gar nicht im Spiel: Der Redner nennt keinen Erfahrungsbericht, sondern ein Gedankenexperiment. Der Fehler liegt woanders, nämlich im Schluss vom Durchspielen auf die Wirklichkeit."},{"option":2,"text":"Dass viele etwas glauben, ist ein schwaches Argument für seine Wahrheit, das stimmt. Der Redner sagt aber nichts über die Verbreitung der Idee. Er beruft sich allein darauf, dass sie sich widerspruchsfrei durchspielen lässt."},{"option":3,"text":"Ein Strohmann verzerrt eine Gegenposition, um sie leichter zu widerlegen. Im Zitat kommt aber keine Gegenposition vor, die verzerrt werden könnte. Der Redner argumentiert ausschließlich für seine eigene Idee."}],"familie":"zu-ende-denken","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Stanford Encyclopedia of Philosophy: Thought Experiments (überarb. 28.11.2023)","oeffentlich":true,"url":"https://plato.stanford.edu/entries/thought-experiment/","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"c1b00f521ad20c54"}},{"id":"qx-a2-004","clusterId":"A","werkstueckRef":"A.12","stufe":4,"question":"Wie belastbar ist das Ergebnis einer solchen Rechnung mit offengelegten, aber geschätzten Annahmen?","options":["Die Rechnung widerlegt die behauptete Täuschung, sofern das Ergebnis deutlich ausfällt und die Zahlen plausibel klingen.","Sie zeigt, welche Konsequenzen die Behauptung unter den genannten Annahmen hätte; weil die Annahmen offenliegen, kann jeder sie nachrechnen, ändern und angreifen.","Sie ist kaum aussagekräftig, weil geschätzte Zahlen zu ungenau sind, um daraus eine Schlussfolgerung zu ziehen.","Sie wird erst belastbar, wenn die Schätzungen durch gemessene Werte ersetzt sind und keine Annahme mehr offen ist."],"correctIndex":1,"explanation":"Eine Rechnung mit Schätzwerten ist kein Beweis, aber auch nicht wertlos. Sie macht aus einer vagen Vorstellung ein Modell: Die Annahmen stehen offen auf dem Tisch, und jeder kann prüfen, ob sie vernünftig sind, und sie verändern. Dass die Zahlen Schätzungen sind, entwertet die Rechnung nicht, solange die Annahmen sichtbar sind und überprüft werden können. Ein reales Beispiel: Der Forscher David Robert Grimes rechnete 2016 die Mondlandungsverschwörung so durch. Er setzte rund 411.000 Mitwissende an (die NASA-Beschäftigten im Spitzenjahr 1965) und schätzte das Risiko des Verrats bewusst niedrig. Selbst dann wäre der Schwindel nach knapp vier Jahren mit über 95 Prozent Wahrscheinlichkeit aufgeflogen. Grimes selbst nennt die Zahlen grobe Größenordnungen, und das Modell nimmt an, alle Gezählten wären eingeweiht. Der Wert liegt in der Nachprüfbarkeit der Annahmen, nicht in einem Beweis.","coreRule":"⚡ Ein Gedankenexperiment wird zum Modell, wenn seine Annahmen offenliegen und angreifbar sind.","beleg":"Werkstück A.12 (Anwendung: Verschwörungsmythen); Fn. ga-grimes (Grimes 2016, PLOS ONE 11(1), e0147905, S. 8 und S. 11)","status":"freigegeben","freigabe":{"datum":"2026-10-13","pruefsumme":"880871099472401a","vermerk":"Prüfpult"},"scenario":"Eine Forscherin schätzt für eine angebliche Jahrzehnte alte Täuschung grob die Zahl der Eingeweihten und das Risiko ein, dass jemand das Geheimnis ausplaudert. Sie rechnet beide Annahmen durch und legt sie in der Veröffentlichung offen. Ein Kritiker wendet ein: „Das sind doch nur geschätzte Zahlen, also ist die ganze Rechnung wertlos.“","kurz":"Die Rechnung ist kein Beweis, aber auch nicht wertlos: Sie zeigt, was die Behauptung unter den genannten Annahmen bedeuten würde. Weil diese offenliegen, kann jeder sie prüfen und ändern. Geschätzt heißt nicht wertlos, sondern angreifbar.","prueffrage":"Welche Zahlen stehen in der Rechnung, und würde sich das Ergebnis ändern, wenn man sie großzügig verschiebt?","rueckmeldung":[{"option":0,"text":"Ein deutliches Ergebnis wirkt wie ein Urteil. Doch die Rechnung zeigt nur, was unter den gewählten Annahmen folgt, und ist kein Beweis. Dass sie Zweifel begründet, heißt nicht, dass sie die Täuschung widerlegt."},{"option":2,"text":"Der Einwand hat einen wahren Kern: Schätzungen sind ungenau, und ein Beweis entsteht so nicht. Ungenau ist aber nicht wertlos, solange offenliegt, was angenommen wurde. Dann lässt sich prüfen, ob das Ergebnis auch bei anderen Zahlen hält."},{"option":3,"text":"Gemessene Werte wären natürlich besser. Wer Belastbarkeit aber erst ohne jede offene Annahme zugesteht, verlangt etwas, das kaum ein Modell erfüllt. Entscheidend ist, dass die Annahmen sichtbar und nachprüfbar sind, nicht dass sie gemessen sind."}],"familie":"zu-ende-denken","fertigkeit":"F1","quellen":[{"typ":"doi","kurz":"Grimes, D. R. (2016): On the Viability of Conspiratorial Beliefs. PLOS ONE 11(1), e0147905","oeffentlich":true,"doi":"10.1371/journal.pone.0147905"},{"typ":"doi","kurz":"Grimes, D. R. (2016): Correction: On the Viability of Conspiratorial Beliefs. PLOS ONE 11(3), e0151003","oeffentlich":true,"doi":"10.1371/journal.pone.0151003"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"880871099472401a"}},{"id":"qx-a2-005","clusterId":"A","werkstueckRef":"A.13","stufe":1,"question":"Was würdest du als Nächstes tun?","options":["Genau beobachten, wohin die Leute beim Hinuntergehen schauen und was sie auf ihrem Weg erreichen wollen.","Zwei Treppen vergleichen, eine mit zusätzlichen Schildern, eine ohne, und die Unfallzahlen beider auswerten.","Die Unfälle über mehr Monate auswerten, um zufällige Schwankungen von einem echten Muster zu trennen.","Eine Prämie für unfallfreie Monate ausloben, damit die Leute einen Anreiz haben, aufmerksamer zu sein."],"correctIndex":0,"explanation":"Wenn ein Verhalten unerklärlich wirkt, ist „dumm und unachtsam“ die bequeme, aber leere Erklärung: Sie prüft nichts und erklärt nicht, warum drei Maßnahmen nichts geändert haben. Wer Menschen als vernünftig Handelnde annimmt, fragt stattdessen, welches Ziel ihr Verhalten sinnvoll macht, und beobachtet es. Naheliegend ist hier etwa, dass die Leute beim Hinuntergehen schon die belebte Kreuzung am Treppenende im Blick haben, um eine Lücke zu finden, und deshalb nicht auf die Stufen achten. Erst wenn man das Ziel kennt, lässt sich das System ändern, statt die Menschen ändern zu wollen. Die anderen Schritte sind in anderer Lage sinnvoll, bringen hier aber nichts: Dass Schilder nicht helfen, weiß man schon, ein Vergleich mit einer weiteren Treppe würde es nur wiederholen. Dass die Unfälle ein Muster bilden und kein Zufall sind, zeigt die seit Monaten unveränderte Rate bereits. Und eine Prämie setzt weiter bei einer Unachtsamkeit an, die bisher nur behauptet, aber nicht festgestellt wurde.","coreRule":"⚡ Bevor du Menschen als dumm abstempelst, frag nach dem unsichtbaren Ziel hinter ihrem Verhalten.","quote":"Das Problem war nicht der Mensch, sondern die Treppe im Verhältnis zum Flur.","quoteLabel":"Merksatz:","beleg":"Werkstück A.13 (Einstiegsgeschichte „Die verfluchte Treppe“; Kernidee; Kontext & Tiefe)","status":"entwurf","scenario":"In einem Bürogebäude häufen sich die Unfälle auf einer steilen Treppe. Am Fuß der Treppe kreuzen sich zwei stark befahrene Hauptflure. Vorsicht-Schilder, hellere Beleuchtung und rutschfeste Streifen haben nichts geändert, die Unfallrate ist seit Monaten unverändert hoch. Ein Manager sagt: „Unsere Leute sind einfach zu dumm und unachtsam für eine Treppe.“","kurz":"Wenn drei Maßnahmen nichts ändern, trägt „zu dumm und unachtsam“ nicht, denn es erklärt nichts und prüft nichts. Besser ist die Frage, welches Ziel das Verhalten sinnvoll macht, und das zeigt genaues Beobachten, etwa der Blick zur belebten Kreuzung.","prueffrage":"Was haben Schilder, Beleuchtung und Streifen gemeinsam, und wurde vorher herausgefunden, warum die Leute gerade auf dieser Treppe stürzen?","rueckmeldung":[{"option":1,"text":"Ein Vergleich wirkt gründlich, doch dass Schilder nicht helfen, ist hier schon bekannt. Ein weiterer Test würde das nur wiederholen und nicht erklären, warum die Leute auf dieser Treppe stürzen."},{"option":2,"text":"Mehr Monate auszuwerten klingt nach sauberem Vorgehen. Die unveränderte Rate zeigt aber bereits ein Muster statt Zufall; zusätzliche Zahlen sagen weiterhin nicht, warum die Unfälle passieren."},{"option":3,"text":"Ein Anreiz scheint zumindest etwas zu bewirken. Er setzt aber bei einer Unachtsamkeit an, die bisher nur behauptet und nicht festgestellt wurde, und lässt offen, warum die bisherigen Maßnahmen nichts änderten."}],"familie":"wohlwollend-verstehen","fertigkeit":"F3","quellen":[{"typ":"url","kurz":"Gilbert, D. T.; Malone, P. S. (1995): The Correspondence Bias. Psychological Bulletin 117(1), 21–38 (Autorenkopie, Harvard)","oeffentlich":true,"url":"https://dtg.sites.fas.harvard.edu/Gilbert%20%26%20Malone%20%28CORRESPONDENCE%20BIAS%29.pdf","seite":"21","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"b25e6134436133c0"}},{"id":"qx-a2-006","clusterId":"A","werkstueckRef":"A.13","stufe":2,"question":"Welche Frage bringt dich am ehesten zu einer brauchbaren Erklärung seines Verhaltens?","scenario":"Dein Onkel lässt sich seit Monaten bei einem Energieheiler behandeln und geht für diese Beschwerden nicht mehr zum Arzt. Er ist sonst ein nüchterner, vernünftiger Mensch. Du willst verstehen, warum er so handelt.","options":["„Welche Studien gibt es zur Wirksamkeit solcher Energiebehandlungen, und was sagt die Forschungslage insgesamt dazu?“","„Wie viel verdient der Heiler an solchen Behandlungen, und wie stark bestimmt dieses Geschäftsinteresse sein Angebot?“","„Welche Wissenslücke hindert ihn daran, die fehlende Wirkung zu erkennen, und wie kann ich sie mit Fakten schließen?“","„Welches Problem löst der Heiler für ihn, etwa durch Zeit, Zuwendung, eine einfache Erzählung und Hoffnung?“"],"correctIndex":3,"explanation":"Wer ein Verhalten nur als Dummheit oder Charakterschwäche abtut, hat noch nichts erklärt. Die Frage nach dem Problem, das das Verhalten für die Person löst, macht sichtbar, was sie tatsächlich antreibt. Ein Heiler bietet oft ungeteilte Aufmerksamkeit, Empathie, eine verständliche Erzählung ohne Fachjargon und Hoffnung, wo die „Schulmedizin“ vielleicht nur noch von „Management“ spricht. Dann ist die Entscheidung des Onkels eher emotional und sozial rational als medizinisch dumm. Verstehen heißt dabei nicht gutheißen: Das Verständnis der Anreize ist der Schlüssel zu einem wirksamen Umgang mit dem Verhalten. Die anderen Fragen sind in anderer Lage sinnvoll, erklären aber nicht, warum der Onkel so handelt: Die Studienlage klärt nur, ob die Methode wirkt, nicht, warum er sie wählt. Das Geschäftsinteresse des Heilers beschreibt dessen Motive, nicht die deines Onkels. Und die Annahme einer Wissenslücke übersieht, dass er sich sonst nüchtern und vernünftig verhält.","coreRule":"⚡ Frag, welches Bedürfnis ein Verhalten erfüllt, nicht, wie jemand so etwas glauben kann.","beleg":"Werkstück A.13 (Anwendung: Pseudomedizin; Aktivierungs-Frage)","status":"entwurf","kurz":"Wer sein Verhalten nur als Dummheit abtut, hat nichts erklärt. Erst die Frage, welches Problem der Heiler für ihn löst, etwa Zeit, Zuwendung, Hoffnung, zeigt, was ihn antreibt. Verstehen heißt nicht gutheißen.","prueffrage":"Seit wann geht dein Onkel zum Heiler statt zum Arzt, und was hat sich für ihn damals verändert?","rueckmeldung":[{"option":0,"text":"Die Studienlage zeigt, ob die Methode wirkt, und das ist wichtig. Sie sagt aber nichts darüber, warum dein Onkel sie wählt, und genau das willst du verstehen."},{"option":1,"text":"Das Geschäftsinteresse sagt etwas über die Motive des Heilers aus. Gefragt ist aber, was deinen Onkel antreibt, und das lässt sich aus den Interessen eines anderen nicht ablesen."},{"option":2,"text":"Ein Wissensmangel wirkt als Erklärung naheliegend. Dein Onkel ist aber sonst nüchtern und vernünftig, deshalb greift das zu kurz. Fakten allein erklären nicht, warum er das tut."}],"familie":"wohlwollend-verstehen","fertigkeit":"F3","quellen":[{"typ":"url","kurz":"Mercer, S. W.; Reilly, D.; Watt, G. C. M. (2002): The importance of empathy in the enablement of patients attending the Glasgow Homoeopathic Hospital. Br J Gen Pract 52(484), 901–905 (Abstract, PubMed)","oeffentlich":true,"url":"https://pubmed.ncbi.nlm.nih.gov/12434958/","abruf":"2026-10-12"},{"typ":"url","kurz":"Gilbert, D. T.; Malone, P. S. (1995): The Correspondence Bias. Psychological Bulletin 117(1), 21–38 (Autorenkopie, Harvard)","oeffentlich":true,"url":"https://dtg.sites.fas.harvard.edu/Gilbert%20%26%20Malone%20%28CORRESPONDENCE%20BIAS%29.pdf","seite":"21","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"1e00b521e1818e82"}},{"id":"qx-a2-007","clusterId":"A","werkstueckRef":"A.13","stufe":3,"question":"Ein Kollege wirft dir vor: „Wenn du erklärst, warum Menschen extremistischen Ideologien folgen, entschuldigst du sie.“ Welche Antwort trifft den Denkfehler in diesem Vorwurf am besten?","options":["Der Vorwurf setzt Erklären mit Entschuldigen gleich; eine Erklärung nennt Ursachen, eine Entschuldigung spricht frei, und wer Ursachen kennt, kann Verhalten gezielter bekämpfen.","Der Vorwurf übersieht, dass Extremismus nie eine einzelne Ursache hat; wer Gründe nennt, vereinfacht das Bild, und wer vereinfacht, verfälscht damit die Wirklichkeit.","Der Vorwurf verwechselt Korrelation mit Kausalität; dass bestimmte Umstände und Extremismus zusammen auftreten, zeigt nicht, dass die Umstände ihn verursachen.","Der Vorwurf ersetzt ein Argument durch Empörung; er appelliert an Gefühle und prüft nicht, ob deine Erklärung der Ursachen inhaltlich stichhaltig und belegt ist."],"correctIndex":0,"explanation":"Der Vorwurf verwechselt zwei verschiedene Dinge: Verstehen, wie ein Verhalten zustande kommt, und Gutheißen, dass es richtig ist. Wer Anreize und Ursachen analysiert, beantwortet eine Sachfrage („Wie kommt es dazu?“), keine Wertungsfrage („Ist es in Ordnung?“). Man kann die systemischen Gründe für Rassismus untersuchen und ihn zugleich unmissverständlich bekämpfen. Ohne Verständnis der Ursachen bleibt die Gegenwehr dagegen oft wirkungslos, weil sie an den eigentlichen Anreizen vorbeigeht. Die anderen Einwände sind für sich bedenkenswert, passen aber nicht auf diesen Vorwurf: Von einer einzelnen Ursache oder einem behaupteten ursächlichen Zusammenhang ist gar nicht die Rede. Und der Kollege liefert mit der Gleichsetzung von Erklären und Entschuldigen immerhin eine Begründung, nur eben eine falsche.","coreRule":"⚡ Anreize zu verstehen heißt nicht, das Verhalten gutzuheißen.","beleg":"Werkstück A.13 (Der Kipppunkt)","status":"entwurf","scenario":"","kurz":"Wer erklärt, wie Extremismus entsteht, beantwortet eine Sachfrage, keine Wertungsfrage. Der Vorwurf setzt Erklären mit Entschuldigen gleich, obwohl man Ursachen untersuchen und das Verhalten zugleich klar ablehnen kann.","prueffrage":"Heißt eine Ärztin, die erklärt, wie eine Sucht entsteht, die Sucht damit gut?","rueckmeldung":[{"option":1,"text":"Dass Extremismus selten nur eine Ursache hat, ist gut möglich. Der Kollege behauptet aber nirgends eine einzelne Ursache. Sein Fehler liegt woanders: Er gleicht Erklären mit Entschuldigen."},{"option":2,"text":"Korrelation und Kausalität auseinanderzuhalten, ist wichtig, passt hier aber nicht. Der Kollege behauptet keinen ursächlichen Zusammenhang zwischen Umständen und Extremismus, sondern gleicht Erklären mit Entschuldigen."},{"option":3,"text":"Der Vorwurf klingt nach Empörung, hat aber eine Begründung: Erklären sei Entschuldigen. Sie ist nur falsch. Ob deine Ursachenanalyse belegt ist, ist eine andere Frage als der Fehler im Vorwurf."}],"familie":"wohlwollend-verstehen","fertigkeit":"F3","quellen":[{"typ":"url","kurz":"Miller, A. G.; Gordon, A. K.; Buddie, A. M. (1999): Accounting for evil and cruelty: is to explain to condone? Personality and Social Psychology Review 3(3), 254–268 (Abstract, PubMed)","oeffentlich":true,"doi":"10.1207/s15327957pspr0303_8","url":"https://pubmed.ncbi.nlm.nih.gov/15661676/","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"979c2ca9f0df4245"}},{"id":"qx-a2-008","clusterId":"A","werkstueckRef":"A.13","stufe":4,"question":"Was ist an dieser Überlegung fehlerhaft, und was wäre der bessere nächste Schritt?","options":["Er schließt aus „Ich kenne den Zweck nicht“ auf „Es gibt keinen Zweck“; besser wäre, zuerst herauszufinden, wozu der Ablauf eingeführt wurde, und dann zu entscheiden.","Er übersieht die Opportunitätskosten, also was die gewonnene Zeit sonst bringen könnte; besser wäre, zuerst deren besten anderen Einsatz zu bestimmen und dann zu entscheiden.","Er verallgemeinert aus einem einzigen Ablauf auf die ganze Abteilung; besser wäre, zuerst viele ähnliche Abläufe in anderen Abteilungen zu vergleichen und dann zu entscheiden.","Er entscheidet über die Köpfe der Beschäftigten hinweg; besser wäre, die Beschäftigten zuerst abstimmen zu lassen, ob sie den Ablauf behalten wollen, und dann zu entscheiden."],"correctIndex":0,"explanation":"Dass niemand den Zweck nennen kann, zeigt nur, dass er nicht bekannt ist, nicht dass es keinen gibt. Ein Ablauf, der aufwendig und lästig wirkt, kann trotzdem ein Problem lösen, das man von außen nicht sieht (zum Beispiel eine frühere Panne oder eine Prüfpflicht; das sind hier nur denkbare Beispiele, über den konkreten Fall ist nichts bekannt). Wer ihn abschafft, ohne das zu klären, riskiert, genau dieses Problem zurückzuholen. Das ist die Logik von Chestertons Zaun: Man reißt einen Zaun quer über dem Weg erst ein, wenn man weiß, wozu er gebaut wurde. Das ist kein Verbot der Änderung, sondern die Forderung, zuerst den Zweck zu verstehen. Chesterton sprach von Einrichtungen und Gesetzen; die Übertragung auf Arbeitsabläufe ist eine Erweiterung. Die anderen Gedanken sind in anderer Lage berechtigt, helfen hier aber nicht weiter: Was die gewonnene Zeit sonst bringen könnte, sagt nichts darüber, was der Ablauf bisher verhindert. Ein Vergleich mit anderen Abteilungen klärt nicht, wozu dieser Ablauf eingeführt wurde, und eine Abstimmung nützt wenig, wenn schon jetzt niemand den Zweck kennt.","coreRule":"⚡ Aus „Ich sehe den Zweck nicht“ folgt nicht „Es gibt keinen“: Kläre erst, wozu etwas da ist, dann entscheide.","beleg":"Werkstück A.13 (Kontext & Tiefe); Fn. ga-chesterton (Chesterton 1929, The Thing, Nachdruck 1946, S. 29)","status":"entwurf","scenario":"Ein neuer Abteilungsleiter findet in seiner Abteilung einen dreifachen Formularlauf für jede Bestellung. Niemand kann ihm sagen, wozu er gut ist. Er sagt: „Das ist offensichtlich sinnloser Aufwand, ich schaffe das ab diese Woche ab.“","kurz":"Dass niemand den Zweck kennt, zeigt nur, dass er unbekannt ist, nicht dass es keinen gibt. Wer den Ablauf abschafft, ohne zu klären, wozu er eingeführt wurde, riskiert, das Problem zurückzuholen, das er womöglich löste.","prueffrage":"Seit wann arbeitet der Abteilungsleiter in dieser Abteilung, und wie viel von ihrer Geschichte kann er kennen?","rueckmeldung":[{"option":1,"text":"Was die gewonnene Zeit sonst bringen könnte, ist eine berechtigte Frage, aber sie kommt zu früh. Sie sagt nichts darüber, was der Ablauf bisher verhindert hat, und genau das ist hier noch offen."},{"option":2,"text":"Im Szenario geht es nur um einen einzigen Ablauf, nicht um die ganze Abteilung. Ein Vergleich mit anderen Abteilungen kann Hinweise geben, klärt aber nicht, wozu dieser Ablauf hier eingeführt wurde."},{"option":3,"text":"Beschäftigte einzubeziehen wirkt fair und vorsichtig. Wenn aber schon jetzt niemand den Zweck kennt, stimmen alle über etwas ab, das sie nicht kennen. Erst der Zweck, dann die Entscheidung."}],"familie":"vorstellung-ist-kein-massstab","fertigkeit":"F2","quellen":[{"typ":"literatur","kurz":"Chesterton, G. K. (1929): The Thing. London: Sheed & Ward, Essay „The Drift from Domesticity“","oeffentlich":false}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"db71805389cda194"}},{"id":"qx-a2-009","clusterId":"A","werkstueckRef":"A.14","stufe":2,"question":"Was ist an dieser Begründung fürs Weitermachen fehlerhaft, und welche Frage prüft stattdessen, ob du weitermachen solltest?","scenario":"Seit drei Jahren pflegst du die Website eines Vereins, die kaum jemand besucht. Du hast schon rund 400 Stunden hineingesteckt. Auf der nächsten Sitzung sagt ein Mitglied: „Nach all der Arbeit wäre es doch schade, jetzt aufzuhören. Mach weiter, dann hat sich alles gelohnt.“","options":["Sie stützt sich auf bereits geleistete Stunden, die sich nicht zurückholen lassen. Besser prüft die Frage: „Würde ich heute, ohne diese Vorgeschichte, mit dem Projekt anfangen?“","Sie stützt sich darauf, dass andere Vereine ebenfalls eine Website pflegen. Besser prüft die Frage: „Wie viele vergleichbare Vereine betreiben eine eigene Website?“","Sie stützt sich auf die Erinnerung an wenige gelungene Vereinsseiten und blendet Misserfolge aus. Besser prüft die Frage: „Wie viele Vereinsseiten sind trotz großer Mühe gescheitert?“","Sie stützt sich auf die Meinung eines Mitglieds, das womöglich selbst von der Seite profitiert. Besser prüft die Frage: „Welches Eigeninteresse hat dieses Mitglied am Fortbestand der Seite?“"],"correctIndex":0,"explanation":"Das Argument begründet das Weitermachen mit dem, was schon investiert wurde: „Nach all der Arbeit …“. Das ist ein Red Flag der Versunkene-Kosten-Falle, denn die Begründung ist rückwärtsgewandt statt vorwärtsgewandt. Die Frage „Würde ich heute damit anfangen?“ blendet die Vergangenheit bewusst aus und bewertet ausschließlich die gegenwärtigen und zukünftigen Vor- und Nachteile. Lautet die Antwort „Nein“, ist das ein starkes Signal, dass dich nur die Vorgeschichte hält. Die anderen Gedanken sind für sich nützlich, passen aber nicht: Der Satz beruft sich weder auf andere Vereine noch auf erinnerte Erfolgsfälle, und über ein Eigeninteresse des Mitglieds steht nichts da. Sie prüfen deshalb nicht, ob du heute neu damit anfangen würdest.","coreRule":"⚡ Frag nicht „Wie viel habe ich schon investiert?“, sondern „Würde ich heute damit anfangen?“","beleg":"Werkstück A.14 (Kernidee; Red Flags)","status":"entwurf","kurz":"Das Argument rechnet mit den 400 schon geleisteten Stunden, die sich nicht zurückholen lassen, statt mit dem, was Weitermachen künftig bringt. Die Frage, ob du heute neu damit anfangen würdest, blendet die Vorgeschichte aus.","prueffrage":"Was würde dem Verein fehlen, wenn die Website ab morgen nicht mehr gepflegt würde, und wer würde es bemerken?","rueckmeldung":[{"option":1,"text":"Wie andere Vereine ihre Auftritte pflegen, ist eine nützliche Information. Das Mitglied beruft sich darauf aber gar nicht, sondern auf die geleistete Arbeit. Und der Vergleich sagt nichts darüber, ob sich dein weiterer Aufwand lohnt."},{"option":2,"text":"Nur erinnerte Erfolge zu sehen, ist ein bekannter Denkfehler. Im Satz des Mitglieds tauchen aber keine Erfolgsbeispiele auf, er stützt sich auf die schon investierte Arbeit. Gescheiterte Seiten zu zählen, ersetzt außerdem nicht die Frage, ob du heute neu anfangen würdest."},{"option":3,"text":"Eigeninteressen von Fürsprechern zu hinterfragen, ist oft sinnvoll. Hier steht dazu aber nichts im Szenario, es wäre eine bloße Vermutung. Und selbst ein uneigennütziges Mitglied würde mit den 400 Stunden argumentieren, also mit dem, was schon verbraucht ist."}],"familie":"versunkene-kosten","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Arkes, H. R.; Blumer, C. (1985): The Psychology of Sunk Cost. OBHDP 35(1), 124–140 (Kopie auf einem Kursserver der Universität Klagenfurt, nicht die Verlagsfassung)","oeffentlich":true,"doi":"10.1016/0749-5978(85)90049-4","url":"https://cognition.aau.at/bg/BA/Arkes%20%26%20Blumer%201985.pdf","seite":"124–125","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"f5b6966174883c84"}},{"id":"qx-a2-010","clusterId":"A","werkstueckRef":"A.14","stufe":3,"question":"Wer wendet die Null-Basis-Frage falsch an?","scenario":"Im vierten Jahr deines Medizinstudiums wird die Prüfungsphase hart. Du bist erschöpft und überlegst, ob du dir die sogenannte Null-Basis-Frage stellen solltest: „Würde ich heute, ohne meine bisherige Zeit zu zählen, noch einmal mit diesem Studium anfangen?“ Vier Kommilitonen schildern, wie sie die Frage nutzen.","options":["Jule bricht ab, weil ihr die Prüfungsphase zu anstrengend ist, obwohl sich an Ziel und Aussichten nichts geändert hat.","Tom wägt bei der Frage ausdrücklich auch die künftigen Vor- und Nachteile einer Fortsetzung ab.","Lena stellt die Frage auch einem Bekannten, der seit Jahren Geld in ein Hobbyprojekt steckt und überlegt, ob es sich künftig noch lohnt.","Jonas gibt eine liebgewonnene Gewohnheit auf, weil er auf die Frage ehrlich „Nein“ antwortet."],"correctIndex":0,"explanation":"Die Null-Basis-Frage soll versunkene Kosten und bloße Trägheit ausblenden und prüfen, ob eine Fortsetzung zu den heutigen Umständen und dem heutigen Wissen passt. Sie ist kein Freibrief, bei der ersten Anstrengung aufzugeben. Wer ein langes, schwieriges Vorhaben abbricht, obwohl sich nur die Mühe und nicht die Lage oder das Wissen geändert haben, wendet sie falsch an. Ausdauer ist für langfristige Ziele nötig. Tom, Lena und Jonas nutzen die Frage so, wie sie gedacht ist: Sie beurteilen die Zukunft statt der Vergangenheit und ziehen ehrlich Konsequenzen.","coreRule":"⚡ Der Check prüft veränderte Umstände, er ersetzt nicht Ausdauer bei Anstrengung.","beleg":"Werkstück A.14 (Der Kipppunkt)","status":"entwurf","quote":"","quoteLabel":"","kurz":"Die Null-Basis-Frage prüft, ob eine Fortsetzung zu heutigen Umständen und heutigem Wissen passt. Wer abbricht, nur weil es anstrengender wird, obwohl sich Lage und Wissen nicht geändert haben, verwechselt Mühe mit einem Grund zum Aufhören.","prueffrage":"Was weiß jede Person heute über ihr Vorhaben, das sie zu Beginn noch nicht wusste, und worauf stützt sie ihre Entscheidung?","rueckmeldung":[{"option":1,"text":"Die Frage blendet bereits investierte Zeit und Mühe aus, nicht die Zukunft. Gerade der Blick auf künftige Vor- und Nachteile ist ihr Zweck; wer so abwägt wie Tom, nutzt sie richtig."},{"option":2,"text":"Dass Lena die Frage auf das Hobbyprojekt eines Bekannten überträgt, wirkt zunächst ungewöhnlich. Die Frage zielt dort aber genau auf den künftigen Nutzen und lässt das bisher hineingesteckte Geld außen vor; das ist ihr Sinn."},{"option":3,"text":"Ein ehrliches „Nein“ ernst zu nehmen, ist gewollt, besonders bei Gewohnheiten, die oft nur aus Trägheit weiterlaufen. Dass Jonas Konsequenzen zieht, ist daher kein Fehler, sondern der Zweck der Frage."}],"familie":"versunkene-kosten","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Arkes, H. R.; Blumer, C. (1985): The Psychology of Sunk Cost. OBHDP 35(1), 124–140 (Kopie auf einem Kursserver der Universität Klagenfurt, nicht die Verlagsfassung)","oeffentlich":true,"doi":"10.1016/0749-5978(85)90049-4","url":"https://cognition.aau.at/bg/BA/Arkes%20%26%20Blumer%201985.pdf","seite":"125","abruf":"2026-10-12"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"65ba6fd81e60baf8"}},{"id":"qx-a2-011","clusterId":"A","werkstueckRef":"A.14","stufe":4,"question":"Eine Frau hängt seit zehn Jahren einer Lehre an, in die sie viel Geld und Lebenszeit gesteckt hat. Ein Freund fragt sie: „Stell dir vor, du hörtest heute zum ersten Mal davon. Würden dich die Beweise, die dir jetzt präsentiert werden, überzeugen, dein Leben dafür umzukrempeln?“ Warum ist diese Frage hier hilfreich, aber für sie zugleich besonders schwer zu beantworten?","options":["Sie prüft die Lehre allein anhand heutiger Beweise ohne Vorgeschichte; ein „Nein“ würde aber heißen, dass sie zehn Jahre lang falsch entschieden hat.","Sie rechnet der Frau vor, wie viel Geld und Zeit sie bereits verloren hat; dieser Verlust lässt sich aber nicht mehr beziffern.","Sie zwingt die Frau, ihre Zweifel vor den anderen Anhängern auszusprechen; das fällt ihr schwer, weil sie Ablehnung fürchtet.","Sie blendet die Vorgeschichte aus; bei Überzeugungen lässt sich diese aber nie von der heutigen Beweislage trennen."],"correctIndex":0,"explanation":"Die Frage löscht die Vergangenheit aus der Entscheidungs-Gleichung: Nur heutige Belege und künftiger Nutzen zählen, bisherige Investitionen nicht mehr. Genau das macht sie stark gegen die Versunkene-Kosten-Falle. Bei lange gehegten Überzeugungen ist sie aber schwer anzuwenden, denn ein „Nein“ hieße, jahrelang an einer schlechten Entscheidung festgehalten zu haben. Das erzeugt kognitive Dissonanz, und um ihr Selbstbild als gute Entscheiderin zu schützen, suchen Menschen in dieser Lage oft lieber Gründe, an der Lehre festzuhalten. Die Frage rechnet dabei keine Verluste vor, muss vor niemandem beantwortet werden, und die Trennung von Vorgeschichte und heutiger Beweislage ist schwer, aber nicht unmöglich.","coreRule":"⚡ Der Null-Basis-Check fragt: „Würde ich heute damit anfangen?“ Bei festgefahrenen Überzeugungen ist er kraftvoll, aber schwer anzuwenden.","beleg":"Werkstück A.14 (Anwendung: festgefahrene Überzeugungen; Verbindungen: Kognitive Dissonanz)","status":"entwurf","scenario":"","kurz":"Die Frage zählt nur heutige Belege und künftigen Nutzen, nicht das bereits Investierte. Schwer fällt die Antwort, weil ein „Nein“ hieße, zehn Jahre lang falsch entschieden zu haben, und dagegen sträubt sich das Selbstbild als kluge Entscheiderin.","prueffrage":"Was soll die Frau nach der Frage ihres Freundes in ihre Antwort einbeziehen, und was ausdrücklich nicht?","rueckmeldung":[{"option":1,"text":"Geld und Zeit stecken tatsächlich in der Lehre. Die Frage rechnet sie aber nicht vor, sie lässt sie bewusst außen vor. Schwer wird die Antwort, weil ein „Nein“ das Selbstbild als kluge Entscheiderin träfe."},{"option":2,"text":"Ablehnung durch andere Anhänger kann real sein. Doch die Frage stellt ihr ein Freund, nicht die Gruppe, und vor den Anhängern muss sie nichts aussprechen. Die Hürde liegt im Inneren: Ein „Nein“ würde ihr Bild als gute Entscheiderin erschüttern."},{"option":3,"text":"Dass die Frage die Vorgeschichte ausblendet, stimmt. Doch Vorgeschichte und heutige Beweislage lassen sich trennen, wenn auch mühsam. Schwer fällt die Antwort, weil ein „Nein“ eine frühere Entscheidung als schlecht entlarven würde."}],"familie":"versunkene-kosten","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Harmon-Jones, E.; Mills, J. (2019): An Introduction to Cognitive Dissonance Theory and an Overview of Current Perspectives on the Theory. In: Harmon-Jones, E. (Hg.): Cognitive Dissonance, 2. Aufl., APA (Leseprobe auf apa.org)","oeffentlich":true,"doi":"10.1037/0000135-001","url":"https://www.apa.org/pubs/books/Cognitive-Dissonance-Intro-Sample.pdf","seite":"3; 6–7","abruf":"2026-10-12"},{"typ":"url","kurz":"Arkes, H. R.; Blumer, C. (1985): The Psychology of Sunk Cost. OBHDP 35(1), 124–140 (Kopie auf einem Kursserver der Universität Klagenfurt, nicht die Verlagsfassung)","oeffentlich":true,"doi":"10.1016/0749-5978(85)90049-4","url":"https://cognition.aau.at/bg/BA/Arkes%20%26%20Blumer%201985.pdf","seite":"124","abruf":"2026-10-12"},{"typ":"doi","kurz":"Festinger, L. (1957): A Theory of Cognitive Dissonance. Stanford University Press","oeffentlich":false,"doi":"10.1515/9781503620766"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"b507faf2f5b56d72"}},{"id":"qx-a2-012","clusterId":"A","werkstueckRef":"A.15","stufe":1,"question":"Eine Kollegin sagt: „Ein Schluss ist genau dann deduktiv, wenn er vom Allgemeinen zum Besonderen geht, und genau dann induktiv, wenn er vom Besonderen zum Allgemeinen geht.“ Du sollst prüfen, ob das stimmt. Welche Frage trennt deduktive und induktive Schlüsse am besten?","options":["Geht der Schluss vom Allgemeinen zum Besonderen oder vom Besonderen zum Allgemeinen? Daran erkennt man zuverlässig die Schlussart.","Muss die Konklusion wahr sein, wenn die Prämissen wahr sind, oder ist sie nur wahrscheinlich? Daran erkennt man zuverlässig die Schlussart.","Sind die Prämissen tatsächlich wahr oder sind sie zumindest teilweise falsch? Daran erkennt man zuverlässig die Schlussart.","Ist die Konklusion tatsächlich wahr oder widerspricht sie den Tatsachen? Daran erkennt man zuverlässig die Schlussart."],"correctIndex":1,"explanation":"Die Richtungsregel scheitert an beiden Beispielen. Schluss (1) ist deduktiv, bleibt aber zwischen allgemeinen Sätzen. Schluss (2) ist induktiv, bleibt aber bei Einzelfällen, nämlich von bisher untersuchten Spinnen auf die nächste. Verlässlich trennt etwas anderes: Bei einem deduktiven Schluss muss die Konklusion wahr sein, wenn die Prämissen wahr sind. Bei einem induktiven Schluss bleibt sie auch bei wahren Prämissen nur wahrscheinlich, denn die nächste Spinne könnte eine Ausnahme sein. Die Richtung ist deshalb nur eine Faustregel. Die Wahrheit der Prämissen oder der Konklusion gehört zu einer anderen Frage, nämlich ob ein Schluss stichhaltig ist: Auch ein deduktiver Schluss kann falsche Prämissen haben und bleibt dennoch deduktiv, und ein induktiver kann aus wahren Prämissen eine falsche Konklusion ziehen.","coreRule":"⚡ Deduktion zwingt, Induktion macht wahrscheinlich; die Richtung ist nur eine Faustregel.","beleg":"Werkstück A.15 (Kernidee); Fn. ga-deduktion-richtung (Shanahan, Internet Encyclopedia of Philosophy, Abschn. 9)","status":"entwurf","scenario":"Zwei Schlüsse zur Prüfung:\\n(1) „Alle A sind B, alle B sind C, also sind alle A auch C.“\\n(2) „Die zehn Spinnen, die ich bisher untersucht habe, haben acht Beine. Also hat auch die nächste Spinne, die ich finde, acht Beine.“","kurz":"Entscheidend ist, ob die Konklusion bei wahren Prämissen wahr sein muss (deduktiv) oder nur wahrscheinlich ist (induktiv). Die Richtung täuscht: Schluss (1) bleibt bei Allgemeinem, Schluss (2) bei Einzelfällen.","prueffrage":"Wovon handeln Prämissen und Konklusion in Schluss (1) und in Schluss (2): von allen Fällen einer Art oder von einzelnen Dingen?","rueckmeldung":[{"option":0,"text":"Die Richtung ist oft ein brauchbarer Anhaltspunkt, aber keine verlässliche Regel. Schluss (1) bleibt zwischen allgemeinen Sätzen und ist deduktiv, Schluss (2) geht von untersuchten Spinnen auf die nächste und ist induktiv."},{"option":2,"text":"Ob die Prämissen wahr sind, entscheidet darüber, ob ein Schluss stichhaltig ist, nicht über seine Art. Auch ein deduktiver Schluss mit falschen Prämissen bleibt deduktiv, weil die Konklusion aus ihnen folgen würde, wären sie wahr."},{"option":3,"text":"Eine wahre Konklusion sagt wenig über die Schlussart: Auch ein induktiver Schluss kann aus wahren Prämissen eine falsche Konklusion ziehen, und ein deduktiver Schluss kann bei falschen Prämissen eine wahre haben. Das gehört zur Frage nach der Stichhaltigkeit."}],"familie":"schluss-pruefen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Shanahan, T.: Deductive and Inductive Arguments. Internet Encyclopedia of Philosophy","oeffentlich":true,"url":"https://iep.utm.edu/deductive-inductive-arguments/","abruf":"2026-10-07"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"035dc27c8f45042e"}},{"id":"qx-a2-013","clusterId":"A","werkstueckRef":"A.15","stufe":2,"question":"Was ist an diesem Schluss falsch?","scenario":"Dein Mitbewohner kommt nass nach Hause. Du denkst: „Wenn es regnet, wird man nass. Er ist nass. Also hat es geregnet.“","options":["Er ist ungültig, weil er aus einer einzelnen Beobachtung ein Gesetz für alle ähnlichen Fälle ableitet.","Er ist ungültig, weil Nässe auch andere Ursachen haben kann und „Es hat geregnet“ daher nicht zwingend folgt.","Er ist ungültig, weil die Schlussfolgerung nur wiederholt, was die erste Prämisse schon als Behauptung enthält.","Er ist ungültig, weil er aus dem Ausbleiben von Regen auf Trockenheit schließt (Verneinung des Vorderglieds)."],"correctIndex":1,"explanation":"„Wenn es regnet, wird man nass“ und „Er ist nass“ erlauben nicht den Schluss „Es hat geregnet“: Das ist der klassische Fehlschluss der Bejahung der Folge. Nass kann auch jemand sein, den ein Rasensprenger getroffen hat oder der mit einem Eimer übergossen wurde. Eine gültige Deduktion wäre zwingend; diese ist es nicht. Verallgemeinert wird hier nichts, denn der Schluss geht von einer Regel auf einen Einzelfall. Ein Zirkelschluss liegt auch nicht vor, denn „Es hat geregnet“ steht in der ersten Aussage nicht als Behauptung, sondern nur als Bedingung. Und von ausbleibendem Regen ist gar nicht die Rede.","coreRule":"⚡ Aus „Wenn A, dann B“ und „B“ folgt nicht „A“.","beleg":"Werkstück A.15 (Denkweg 1); Fn. ga-bejahung (Dowden, Internet Encyclopedia of Philosophy, „Affirming the Consequent“)","status":"entwurf","kurz":"„Nass“ folgt aus Regen, aber nicht jede Nässe kommt vom Regen: Auch ein Rasensprenger oder ein Eimer Wasser macht nass. Wer die Regel umdreht, schließt von der Folge auf eine von mehreren möglichen Ursachen, und das ist nicht zwingend.","prueffrage":"Ist die Straße vor der Tür nass, und sind andere, die gerade von draußen kommen, ebenfalls nass?","rueckmeldung":[{"option":0,"text":"Hier wird nichts verallgemeinert: Der Schluss geht von einer Regel auf einen einzelnen Fall, nicht von einem Einzelfall auf ein Gesetz. Der Fehler liegt in der Richtung, in der die Regel gelesen wird."},{"option":2,"text":"Ein Zirkel wäre es, wenn schon die erste Aussage behauptete, dass es geregnet hat. Dort steht Regen aber nur als Bedingung („Wenn es regnet …“), die Schlussfolgerung bringt also etwas Neues hinzu. Es fehlt ihr die zwingende Grundlage."},{"option":3,"text":"Von ausbleibendem Regen ist gar nicht die Rede, dein Mitbewohner ist ja nass. Den Schluss von „kein Regen“ auf „trocken“ gibt es als eigenen Fehlschluss, hier wird aber aus der Nässe auf Regen geschlossen."}],"familie":"schluss-pruefen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Dowden, B.: Fallacies, Eintrag „Affirming the Consequent“. Internet Encyclopedia of Philosophy","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-07"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"b2de38164f191404"}},{"id":"qx-a2-014","clusterId":"A","werkstueckRef":"A.15","stufe":3,"question":"Ein Mitglied einer Gruppe argumentiert: „Alles, was unser Anführer sagt, ist wahr. Der Anführer sagt, die Welt gehe nächste Woche unter. Also geht sie unter.“ Du sollst die Schwachstelle benennen. Wo setzt du an?","options":["Bei der Form des Schlusses: Er schließt von der Folge auf die Bedingung und ist deshalb logisch ungültig.","Bei der Konklusion, denn aus einer Allaussage darf man grundsätzlich keinen Schluss auf einen Einzelfall ziehen.","Bei den Beobachtungen: Der Anführer hat bisher zu wenige Weltuntergänge erlebt, um sich sicher sein zu können.","Bei der ersten Aussage: Der Schluss folgt sauber aus ihr, aber niemand hat belegt, dass der Anführer immer recht hat."],"correctIndex":3,"explanation":"Formal ist der Schluss gültig: Wenn wirklich alles wahr ist, was der Anführer sagt, und er den Weltuntergang ankündigt, dann folgt der Weltuntergang zwingend. Der Aufbau entspricht dem klassischen „Alle Menschen sind sterblich, Sokrates ist ein Mensch, also ist Sokrates sterblich“. Ein gültiger Schluss ist aber nur so verlässlich wie seine Ausgangsaussage, und genau die ist hier unbelegt und in dieser Absolutheit kaum haltbar: Kein Mensch irrt nie. Wer nur die Form prüft, findet keinen Fehler und lässt das Gedankengebäude unangetastet. Die Prüfung muss bei der Prämisse ansetzen: Woher weiß man, dass der Anführer immer recht hat, und gibt es Belege für das Gegenteil, etwa frühere Vorhersagen, die nicht eingetroffen sind? Die anderen Ansätze scheitern: Der Schluss bejaht nicht die Folge, aus einer Allaussage darf man sehr wohl auf Einzelfälle schließen, und von Beobachtungen oder Stichproben ist hier gar nicht die Rede.","coreRule":"⚡ Prüfe bei einem logischen Argument immer auch die Prämissen, nicht nur die Form.","beleg":"Werkstück A.15 (Anwendung: Sekten & Kulte; Red Flags; Der Kipppunkt)","status":"entwurf","scenario":"","kurz":"Der Schluss ist formal gültig, trägt aber nur so weit wie seine Ausgangsaussage. Dass der Anführer immer recht hat, ist unbelegt und kaum haltbar. Wer nur die Form prüft, findet keinen Fehler und übersieht die schwache Stelle.","prueffrage":"Wenn die erste und die zweite Aussage stimmen, muss dann auch die dritte stimmen?","rueckmeldung":[{"option":0,"text":"Bei einem Fehlschluss lohnt sich der Blick auf die Form, doch hier wird nicht von der Folge auf die Bedingung geschlossen, sondern von der Bedingung auf die Folge. Die Form ist gültig, der Fehler steckt woanders."},{"option":1,"text":"Die Konklusion ist das Unglaubliche am Satz, deshalb setzt man gern dort an. Aus einer Allaussage darf man aber sehr wohl auf einen Einzelfall schließen, so funktionieren gültige Schlüsse; der Mangel liegt in der Allaussage selbst."},{"option":2,"text":"Behauptungen auf Belege zu prüfen, ist richtig. Von Beobachtungen oder Stichproben ist hier aber keine Rede, und Weltuntergänge lassen sich ohnehin nicht sammeln. Zu prüfen ist die erste Aussage: Woher weiß man, dass der Anführer immer recht hat?"}],"familie":"schluss-pruefen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Shanahan, T.: Deductive and Inductive Arguments. Internet Encyclopedia of Philosophy","oeffentlich":true,"url":"https://iep.utm.edu/deductive-inductive-arguments/","abruf":"2026-10-07"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"b47fe6e40350d3da"}},{"id":"qx-a2-015","clusterId":"A","werkstueckRef":"A.15","stufe":4,"question":"Welche Aussage über den Schluss der Ärztin ist richtig?","options":["Sie schließt auf die beste Erklärung aller Beobachtungen; das Ergebnis ist nur wahrscheinlich und kann durch weitere Befunde widerlegt werden.","Sie verallgemeinert aus vielen beobachteten Fällen eine neue Regel (Induktion); je mehr Fälle vorliegen, desto besser ist die Regel gestützt.","Sie wendet eine bekannte Regel auf diesen Einzelfall an (Deduktion); dabei steckt die Schlussfolgerung schon vollständig in den Prämissen.","Sie überträgt das Ergebnis eines früher behandelten, ähnlichen Patienten auf diesen Fall (Analogie); je ähnlicher, desto stärker der Schluss."],"correctIndex":0,"explanation":"Der Schluss geht von mehreren Beobachtungen auf die Erklärung, die sie am besten verbindet. Er liefert nur Wahrscheinliches: Fieber, Husten und Gliederschmerzen passen auch zu anderen Erkrankungen, und ein weiterer Befund, etwa ein negativer Test, könnte die Diagnose kippen. Man nennt das einen Schluss auf die beste Erklärung; er ist eng verwandt mit dem, was der Philosoph Charles S. Peirce Abduktion nannte. Eine Induktion bildet aus vielen Fällen eine Regel, hier wird aber eine Diagnose für einen einzelnen Patienten gestellt. Bei einer Deduktion läge die Diagnose schon in den Prämissen, hier steht sie aber nirgends fest. Von einem früher behandelten, ähnlichen Patienten ist im Szenario keine Rede.","coreRule":"⚡ Frag bei einem Schluss auf eine Ursache: Ist er zwingend oder nur wahrscheinlich, und welche Erklärung passt zu allen Beobachtungen am besten?","beleg":"Werkstück A.15 (Denkweg 2); Fn. ga-abduktion (Douven, Stanford Encyclopedia of Philosophy, „Abduction“, Abschn. 1.1)","status":"entwurf","scenario":"Eine Ärztin sieht einen Patienten mit Fieber, Husten und Gliederschmerzen. In der Nachbarschaft sind mehrere Grippefälle bekannt. Sie schließt: „Das ist sehr wahrscheinlich Grippe.“","kurz":"Die Ärztin sucht die Erklärung, die Fieber, Husten, Gliederschmerzen und die Grippefälle in der Nachbarschaft am besten verbindet. Das ergibt nur Wahrscheinliches, denn ein negativer Test könnte die Diagnose kippen, anders als bei einem zwingenden Schluss.","prueffrage":"Worauf stützt die Ärztin ihr Urteil im Einzelnen, und was davon hat sie selbst gezählt oder getestet?","rueckmeldung":[{"option":1,"text":"Mehr Fälle stützen eine Regel tatsächlich besser. Hier wird aber keine neue Regel gebildet, sondern für einen einzelnen Patienten die passendste Erklärung gesucht; die Fälle in der Nachbarschaft sind dafür ein Hinweis."},{"option":2,"text":"Bei einer Deduktion folgt der Schluss zwingend aus den Prämissen. Hier gibt es keine Regel, nach der diese Beschwerden immer Grippe bedeuten, und die Ärztin sagt selbst nur „sehr wahrscheinlich“; ein negativer Test könnte die Diagnose kippen."},{"option":3,"text":"Eine Analogie stützt sich auf einen konkreten früheren Vergleichsfall, und je ähnlicher dieser ist, desto stärker der Schluss. Ein solcher Patient kommt im Szenario aber nicht vor; die Ärztin wertet die Beschwerden und die Grippefälle in der Nachbarschaft aus."}],"familie":"sparsamste-erklaerung","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Douven, I.: Abduction. Stanford Encyclopedia of Philosophy (überarb. 2025)","oeffentlich":true,"url":"https://plato.stanford.edu/entries/abduction/","abruf":"2026-10-07"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"d63de4d2ebea6eff"}},{"id":"qx-a2-016","clusterId":"A","werkstueckRef":"A.16","stufe":1,"question":"Zwei Menschen streiten heftig darüber, ob ein bestimmtes Nahrungsergänzungsmittel Krebs heilt. Die eine Person verweist auf mehrere unabhängige Studien, die andere sagt: „Mein Bauchgefühl und der Rat meines Gurus sagen mir, dass es wirkt.“ Der Streit dreht sich im Kreis. Was ist die hilfreichste Reaktion?","options":["Beide sammeln weitere Einzelfakten zum Mittel, bis die Faktenlage auf einer Seite so erdrückend ist, dass die andere sie nicht mehr ablehnen kann.","Beide klären zuerst, mit welchem Verfahren sich in dieser Art von Frage überhaupt zuverlässig zwischen Wirkung und Einbildung unterscheiden lässt.","Beide prüfen zuerst, ob hinter den Studien finanzielle Interessen stehen, weil Geldgeber Ergebnisse beeinflussen können, und werten die Studien danach neu aus.","Beide suchen eine Kompromissformel, mit der sich beide Seiten wiederfinden, etwa dass das Mittel vielleicht ein wenig wirkt, und beenden so den Streit."],"correctIndex":1,"explanation":"Wenn zwei Seiten ihre Behauptungen mit völlig unterschiedlichen Verfahren rechtfertigen (hier: überprüfbare Daten gegen Bauchgefühl und Autorität), führt ein Streit über Einzelfakten selten weiter, denn jede Seite lässt andere Belege gelten. Erst wenn geklärt ist, welches Verfahren die Frage überhaupt entscheiden kann, kommt man weiter. Ob ein Stoff Krebs heilt, lässt sich nur mit öffentlich überprüfbaren Daten, Beobachtungen und Experimenten klären: Intuition kann helfen einzuschätzen, ob man einer Person vertraut, aber nicht, ob ein Molekül einen Tumor heilt. Mehr Fakten zu sammeln ändert daran nichts, solange das Verfahren strittig ist. Die Geldgeber von Studien zu prüfen ist sonst ein guter Schritt, hier aber sind die Studien als unabhängig beschrieben, und die andere Seite lässt Studien ohnehin nicht als Maßstab gelten. Und eine Mittelposition hilft bei einer prüfbaren Sachfrage nicht, weil Entgegenkommen nicht entscheidet, ob ein Stoff wirkt.","coreRule":"⚡ Frag nicht nur „Was weißt du?“, sondern „Woher weißt du es?“ Wer über die Methode der Wahrheitsfindung streitet, streitet nicht mehr im Kreis.","beleg":"Werkstück A.16 (Kernidee; Kontext & Tiefe)","status":"entwurf","scenario":"","kurz":"Solange die eine Seite Daten und die andere Bauchgefühl und Autorität gelten lässt, führt der Streit um Einzelfakten im Kreis. Erst ein gemeinsames Verfahren, das Wirkung von Einbildung trennen kann, lässt eine Antwort zu.","prueffrage":"Was hat der bisherige Austausch von Argumenten bewirkt, und woran ist er jedes Mal hängengeblieben?","rueckmeldung":[{"option":0,"text":"Mehr Fakten wirken gründlich, und oft sind sie der richtige Weg. Hier lässt eine Seite Studien aber gar nicht als Maßstab gelten, und selbst eine erdrückende Faktenlage ändert daran meist nichts."},{"option":2,"text":"Auf Geldgeber zu achten ist sonst eine kluge Prüfung. Hier sind die Studien aber als unabhängig beschrieben, und die andere Seite lässt Studien ohnehin nicht als Maßstab gelten."},{"option":3,"text":"Ein Kompromiss kann den Streit beenden, entscheidet aber nicht, was stimmt. Ob ein Stoff wirkt, ist eine prüfbare Sachfrage, und eine Mittelposition ist dort nicht schon deshalb richtig, weil beide sich darin wiederfinden."}],"familie":"nach-weg-und-kriterium-fragen","fertigkeit":"F3","quellen":[{"typ":"url","kurz":"Hansson, S. O.: Science and Pseudo-Science. Stanford Encyclopedia of Philosophy","oeffentlich":true,"url":"https://plato.stanford.edu/entries/pseudo-science/","abruf":"2026-10-07"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"ee140d7eafb09dbc"}},{"id":"qx-a2-017","clusterId":"A","werkstueckRef":"A.16","stufe":2,"question":"Was ist jetzt der klügste nächste Schritt?","scenario":"Du diskutierst seit einer Stunde mit einem Bekannten über einen Verschwörungsmythos. Du bringst Studien, er winkt ab: „Die gehören doch alle zum System.“ Jede neue Quelle wird auf dieselbe Weise abgelehnt.","options":["Die aussagekräftigste Studie heraussuchen und ihre Methode Schritt für Schritt erklären, damit er die Belege endlich versteht und anerkennt.","Euch auf eine Mittelposition einigen, etwa dass an dem Mythos ein wahrer Kern sein könnte, damit das Gespräch freundlich zu Ende geht.","Erst über die Methode reden: Welches Verfahren halten wir beide in dieser Frage für das verlässlichste, und was würde ihn umstimmen?","Nachzeichnen, wer den Mythos zuerst verbreitet hat und welche Interessen dahinterstanden, damit er die Herkunft der Behauptung einordnen kann."],"correctIndex":2,"explanation":"Wenn jede Gegenevidenz von vornherein als Teil der Verschwörung gilt, können weitere Fakten nichts bewirken: Ihr benutzt zwei verschiedene Verfahren, um zwischen wahr und falsch zu unterscheiden. Solange das nicht geklärt ist, redet ihr aneinander vorbei, weil jede Seite andere Beweise gelten lässt. Sinnvoll ist deshalb, zuerst die Methode zu besprechen: Wie lässt sich in dieser Art von Frage am verlässlichsten die Wahrheit herausfinden, und unter welchen Umständen würde er seine Meinung ändern? Eine einzelne Studie genauer zu erklären hilft nicht, denn er zweifelt nicht am Verständnis, sondern lehnt die Quellen als Gruppe ab. Eine Mittelposition passt nicht, weil es bei einer Sachfrage kein halbes Wahr gibt. Und die Herkunft des Mythos zu erzählen liefert nur weiteren Stoff, den er auf dieselbe Weise abtun würde.","coreRule":"⚡ Wenn Fakten nichts bewirken, klärt zuerst die Methode der Wahrheitsfindung.","quote":"","quoteLabel":"","beleg":"Werkstück A.16 (Anwendung; Red Flags; Anti-Denkmuster)","status":"entwurf","kurz":"Wenn jede Quelle als Teil des „Systems“ gilt, könnt ihr mit weiteren Fakten nichts mehr klären, weil ihr zwei verschiedene Verfahren benutzt, um Wahres von Falschem zu trennen. Erst wenn ihr dieses Verfahren besprecht, habt ihr eine gemeinsame Grundlage.","prueffrage":"Wie hat er auf jede bisher genannte Studie reagiert, und hat sich daran im Lauf der Stunde etwas geändert?","rueckmeldung":[{"option":0,"text":"Eine Studie genau zu erklären, wirkt hilfsbereit, setzt aber voraus, dass er sie nicht verstanden hat. Er zweifelt jedoch nicht am Verständnis, sondern lehnt die Quellen als Gruppe ab, und das ändert eine bessere Erklärung nicht."},{"option":1,"text":"Eine Mittelposition beendet das Gespräch angenehm, passt aber nicht zu einer Sachfrage, bei der es kein halbes Wahr gibt. Ein „wahrer Kern“ ohne Beleg würde den Mythos nur aufwerten und den Streit über das Verfahren verdecken."},{"option":3,"text":"Die Herkunft eines Mythos kann aufschlussreich sein. Hier ist sie aber nur weiterer Stoff, den er mit demselben „gehört zum System“ abtun würde, und das eigentliche Problem, die unterschiedlichen Maßstäbe für Beweise, bleibt unberührt."}],"familie":"nach-weg-und-kriterium-fragen","fertigkeit":"F3","quellen":[{"typ":"url","kurz":"Hansson, S. O.: Science and Pseudo-Science. Stanford Encyclopedia of Philosophy","oeffentlich":true,"url":"https://plato.stanford.edu/entries/pseudo-science/","abruf":"2026-10-07"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"b72fe58e031dabaf"}},{"id":"qx-a2-018","clusterId":"A","werkstueckRef":"A.16","stufe":3,"question":"Du steigst in ein Flugzeug und vertraust der Pilotin, ohne ihre Berechnungen nachzuprüfen. Ein Bekannter sagt: „Das ist doch genauso unkritisch wie der blinde Glaube an einen Guru. Wer wirklich rational ist, vertraut nur dem, was er selbst überprüft hat.“ Was ist an seinem Einwand fehlerhaft?","options":["Er setzt jedes Vertrauen in Fachleute mit blindem Guruglauben gleich, obwohl entscheidend ist, ob die Quelle nachprüfbar und korrigierbar ist und zur Art der Frage passt.","Er beruft sich auf eine Autorität, ohne zu prüfen, ob sie für diese Frage überhaupt Fachwissen hat, und stützt seine Behauptung allein auf deren Ansehen (Autoritätsargument).","Er malt eine unbelegte Kette von Folgen aus: Wer der Pilotin vertraue, werde bald jedem vertrauen, und am Ende stehe blinde Gefolgschaft gegenüber jedem Sektenführer (Dammbruchargument).","Er schließt von der Verbreitung einer Haltung auf ihre Richtigkeit: Weil die meisten Menschen Fachleuten vertrauen, müsse dieses Vertrauen gerechtfertigt sein (Mehrheitsargument)."],"correctIndex":0,"explanation":"Vertrauen ohne eigene Nachprüfung ist nicht automatisch ein Denkfehler. Einer erfahrenen Pilotin vertrauen wir, weil ihr Können geprüft wurde, ihre Arbeit kontrolliert wird und Fehler auffallen und korrigiert werden können. Beim Guru gilt dagegen oft: Zweifel ist verboten, und widersprüchliche Evidenz wird umgedeutet, bis sie wieder zur Lehre passt. Entscheidend ist also, ob die Quelle nachprüfbar und korrigierbar ist und ob die Methode zur Art der Frage passt. Problematisch wird es dort, wo Bauchgefühl oder unprüfbare Autorität Sachfragen beantworten sollen, etwa ob ein Molekül ein Krebsgeschwür heilt oder ob Impfungen sicher sind. Der Bekannte beruft sich dabei weder auf eine Autorität noch auf die Mehrheit. Auch eine Kette immer größerer Folgen malt er nicht aus.","coreRule":"⚡ Vertrauen in Autorität und Intuition ist nicht per se falsch: Es kommt darauf an, ob die Quelle nachprüfbar und korrigierbar ist und zur Art der Frage passt. Fragen, die nur Daten beantworten, entscheiden weder Gefühl noch Guru.","beleg":"Werkstück A.16 (Der Kipppunkt)","status":"entwurf","scenario":"","kurz":"Vertrauen ohne eigene Nachprüfung ist nicht automatisch blind. Die Pilotin ist geprüft, wird kontrolliert, und Fehler fallen auf. Beim Guru ist Zweifel verboten. Der Bekannte übersieht diesen Unterschied und wirft beides zusammen.","prueffrage":"Wie viel von dem, was der Bekannte täglich für wahr hält, hat er selbst überprüft?","rueckmeldung":[{"option":1,"text":"Hier hört sich das nach einem Autoritätsproblem an, weil es ums Vertrauen in Fachleute geht. Der Bekannte stützt sich aber auf keine Autorität, im Gegenteil: Er lehnt sie ab. Sein Fehler liegt woanders."},{"option":2,"text":"Ein Vergleich mit Gurus erinnert schnell an eine Rutschbahn-Argumentation. Der Bekannte malt aber keine Kette von Folgen aus, sondern setzt Pilotin und Guru unmittelbar gleich. Eine Prognose „erst das, dann das“ fehlt."},{"option":3,"text":"Mehrheitsargumente kommen bei Vertrauensfragen oft vor. Der Bekannte sagt aber nichts über die Zahl der Vertrauenden. Und für die Pilotin spricht auch nicht, dass viele ihr trauen, sondern dass ihr Können geprüft wird und Fehler korrigierbar sind."}],"familie":"autoritaet-pruefen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Stanford Encyclopedia of Philosophy: Epistemological Problems of Testimony (2021)","oeffentlich":true,"url":"https://plato.stanford.edu/entries/testimony-episprob/","abruf":"2026-10-12"},{"typ":"url","kurz":"Hansson, S. O.: Science and Pseudo-Science. Stanford Encyclopedia of Philosophy","oeffentlich":true,"url":"https://plato.stanford.edu/entries/pseudo-science/","abruf":"2026-10-07"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"b7fb5234d3800f62"}},{"id":"qx-a2-019","clusterId":"A","werkstueckRef":"A.16","stufe":4,"question":"Welche Frage deckt am besten auf, ob die Behauptung des Anbieters wissenschaftlich begründet ist oder nur so klingt?","options":["Wie anerkannt ist der Entwickler der Methode in seinem Fachgebiet, und seit wann ist er dort tätig?","Wie viele Menschen haben die Methode schon angewendet, und wie zufrieden waren sie im Durchschnitt?","Wie teuer ist die Methode im Vergleich zu ähnlichen Angeboten, und ist der Preis ihrem Nutzen angemessen?","Unter welchen Ergebnissen wäre die Methode widerlegt, und kann das jemand unabhängig nachprüfen?"],"correctIndex":3,"explanation":"Entscheidend ist die Methode der Begründung, nicht das Vokabular. Der Anbieter ahmt die Sprache der Wissenschaft nach (Studien, Fachjargon), stützt sich aber auf Autorität (den Entwickler) und Intuition (die Erlebnisberichte der Kunden). Eine wissenschaftliche Begründung erkennt man an zwei Merkmalen: Sie ist falsifizierbar, man kann also sagen, welches Ergebnis sie widerlegen würde, und sie ist öffentlich überprüfbar, jeder kann die Prüfung wiederholen. Der Ruf eines Entwicklers ersetzt keine Prüfung, denn Ansehen ist Autorität und kein Beleg. Viele zufriedene Berichte sind Anekdoten, die jede Behauptung stützen können. Und der Preis sagt etwas über das Angebot, aber nichts darüber, ob die Methode wirkt.","coreRule":"⚡ Prüfe nicht den Jargon, sondern auf welcher Methode eine Behauptung wirklich ruht.","beleg":"Werkstück A.16 (Anwendung: Pseudowissenschaft; Weg 1 bis 3; Prinzipien Falsifizierbarkeit und öffentliche Überprüfbarkeit)","status":"entwurf","scenario":"Ein Anbieter wirbt für seine „Energie-Methode“. Er verweist auf „Studien“ und benutzt viel Fachjargon. Fragt man, warum die Methode wirkt, antwortet er: „So hat es der Entwickler der Methode festgelegt, und unsere Kundinnen und Kunden berichten begeistert von ihren Erfahrungen.“","kurz":"Wissenschaftlich begründet ist nur, was sich widerlegen und unabhängig nachprüfen lässt. Der Anbieter ahmt die Fachsprache nach, stützt sich aber auf Autorität und Erlebnisberichte. Beides kann jede Behauptung stützen.","prueffrage":"Welche Gründe nennt der Anbieter, wenn man ihn nach der Wirkung fragt, und woher stammt jeder davon?","rueckmeldung":[{"option":0,"text":"Ein anerkannter Entwickler wirkt vertrauenswürdig, und Fachwissen kann ein Hinweis sein. Aber Ansehen ist Autorität und keine Prüfung: Auch ein renommierter Name sagt nicht, ob die Methode geprüft wurde und wirkt."},{"option":1,"text":"Viele zufriedene Anwender wirken überzeugend. Zufriedenheit zeigt aber nicht, dass die Methode wirkt: Erwartung und Zufall können sie ebenso erklären, und solche Berichte stützen fast jede Behauptung."},{"option":2,"text":"Der Preisvergleich ist als Verbraucherfrage sinnvoll. Er sagt aber nur etwas über das Angebot, nicht darüber, ob die Methode wirkt. Teuer ist nicht wirksamer, billig nicht unwirksamer."}],"familie":"nach-weg-und-kriterium-fragen","fertigkeit":"F3","quellen":[{"typ":"url","kurz":"Hansson, S. O.: Science and Pseudo-Science. Stanford Encyclopedia of Philosophy","oeffentlich":true,"url":"https://plato.stanford.edu/entries/pseudo-science/","abruf":"2026-10-07"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"1246c67d893c5025"}},{"id":"qx-a2-020","clusterId":"A","werkstueckRef":"A.17","stufe":1,"question":"Eine Studentin sagt: „Ich hab den Text zweimal gelesen, aber ich kapier ihn nicht, ich bin einfach schlecht in Statistik.“ Was würde jemand mit gutem Blick auf das eigene Denken stattdessen tun?","options":["Sie fragt sich, an welcher Stelle sie den Faden verloren hat, und sucht gezielt eine einfachere Erklärung genau dafür.","Sie liest den Text ein drittes Mal von vorn, diesmal langsamer, weil Wiederholung das Verständnis festigt.","Sie plant ihre Lernzeit neu und legt fest, wie viele Seiten sie pro Tag liest, damit sie den Stoff rechtzeitig schafft.","Sie prüft, ob sie im Vergleich zu anderen Studierenden zu langsam liest, und übt dann gezielt schnelleres Lesen."],"correctIndex":0,"explanation":"„Ich hab’s nicht verstanden“ ist ein pauschales Urteil, aus dem sich nichts ableiten lässt. Wer das eigene Verstehen überwacht, benennt, wo genau es abgerissen ist, und sucht gezielt eine andere Quelle für genau diesen Abschnitt. Nochmaliges Lesen von vorn hilft, wenn man einen Text nur überflogen hat, hier hat sie ihn aber schon zweimal gelesen, ohne die Stelle zu finden. Zeitplanung regelt, wie viel sie liest, nicht ob sie es versteht. Und schnelleres Lesen löst kein Verständnisproblem, denn sie scheitert nicht am Tempo.","coreRule":"⚡ Gutes Denken über das eigene Denken bedeutet: genau benennen, wo es hakt, und dann die Strategie wechseln, statt sich pauschal als „schlecht darin“ abzustempeln.","quote":"","quoteLabel":"","beleg":"Werkstück A.17 (Kernidee; Kontext & Tiefe)","status":"entwurf","scenario":"","kurz":"„Ich kapier es nicht“ ist ein pauschales Urteil, aus dem sich nichts ableiten lässt. Erst wenn sie die Stelle benennt, an der es abriss, kann sie genau dafür eine andere Erklärung suchen.","prueffrage":"Was hat die Studentin bisher unternommen, um den Text zu verstehen, und was hat sich zwischen erstem und zweitem Lesen geändert?","rueckmeldung":[{"option":1,"text":"Noch einmal zu lesen und dabei langsamer zu werden, fühlt sich nach Einsatz an. Zweimal hat es aber schon nicht gezeigt, wo es hakt, und ein weiterer Durchgang von vorn sucht die Lücke nicht gezielt."},{"option":2,"text":"Ein Plan hilft, den Stoff rechtzeitig zu schaffen. Er bestimmt aber nur, wie viel gelesen wird, und sagt nichts darüber, ob das Gelesene verstanden wird."},{"option":3,"text":"Tempo ist leicht zu messen und mit anderen zu vergleichen, deshalb liegt der Gedanke nahe. Sie hat den Text aber zweimal gelesen und scheitert am Verstehen, nicht an der Geschwindigkeit, schneller lesen löst das also nicht."}],"familie":"wissensgrenze-benennen","fertigkeit":"F5","quellen":[{"typ":"url","kurz":"O’Leary, A. J.; Sloutsky, V. M.: Carving metacognition at its joints: Protracted development of component processes. Child Development 88(3), 1015–1032 (PMC)","oeffentlich":true,"url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC5397377/","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Flavell, J. H. (1979): Metacognition and Cognitive Monitoring: A New Area of Cognitive-Developmental Inquiry. American Psychologist 34, 906–911","oeffentlich":false}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"8ae99605a2cc1eba"}},{"id":"qx-a2-021","clusterId":"A","werkstueckRef":"A.17","stufe":2,"question":"Du liest einen Fachtext und verlierst im Abschnitt über Statistik den Faden. Welche Reaktion nutzt das Nachdenken über das eigene Lernen am besten?","scenario":"Du arbeitest dich durch einen Fachtext. Der Anfang war klar, doch im Abschnitt über Statistik kommst du nicht mehr mit. Du hast noch eine knappe Stunde Zeit.","options":["Du teilst die knappe Stunde in feste Zeitblöcke ein und liest in jedem Block ein festes Stück des Textes.","Du benennst, bis wohin du verstanden hast, und gehst gezielt diesen Abschnitt noch einmal an.","Du liest den ganzen Text sofort von vorn, bis du dir bei jeder Stelle sicher bist.","Du liest zügig weiter, um den Text ganz durchzuhaben, und prüfst erst am Ende."],"correctIndex":1,"explanation":"Wer sein eigenes Verständnis überwacht, merkt nicht nur, dass etwas nicht klappt, sondern kann genau sagen, wo es aussetzt. Erst diese Genauigkeit erlaubt eine passende Gegenmaßnahme: den fraglichen Abschnitt noch einmal ansehen oder eine einfachere Quelle suchen. Ein fester Zeitplan hilft, die Stunde zu nutzen, sagt aber nichts darüber, ob du den Stoff verstanden hast. Ein Neustart ganz von vorn verschwendet Zeit auf Abschnitte, die du längst verstanden hast. Und Weiterlesen ohne Prüfung setzt nicht an der Stelle an, an der das Verständnis tatsächlich abbrach.","coreRule":"⚡ Benenne genau, wo dein Verständnis endet, und passe dann deine Strategie an.","beleg":"Werkstück A.17 (Anwendung: Beim Lernen & Verstehen; Red Flags)","status":"entwurf","kurz":"Wer genau sagen kann, bis wohin er verstanden hat, kann gezielt dort ansetzen. Naheliegend ist, nur zu merken, dass es hakt, und dann pauschal etwas zu tun, was weder zur Lücke noch zur knappen Zeit passt.","prueffrage":"Wie viel Zeit bleibt dir, und für welchen Teil des Textes brauchst du sie wirklich?","rueckmeldung":[{"option":0,"text":"Ein Zeitplan hilft, die Stunde auszunutzen, das ist ein echter Gewinn. Er sagt aber nichts darüber, ob du den Stoff verstanden hast, und die Stelle, an der du den Faden verloren hast, bleibt dabei unberührt."},{"option":2,"text":"Gründlichkeit wirkt hier sicher, doch ein Neustart steckt Zeit in Abschnitte, die du längst verstanden hast. Bei knapper Zeit fehlt sie dann genau dort, wo das Verständnis abbrach."},{"option":3,"text":"Den Text fertig zu bekommen, fühlt sich nach Fortschritt an. Gelesen heißt aber nicht verstanden: Die Lücke im Statistikabschnitt bleibt bestehen, und eine Prüfung erst am Ende kommt zu spät, um gezielt nachzubessern."}],"familie":"wissensgrenze-benennen","fertigkeit":"F5","quellen":[{"typ":"url","kurz":"O’Leary, A. J.; Sloutsky, V. M.: Carving metacognition at its joints: Protracted development of component processes. Child Development 88(3), 1015–1032 (PMC)","oeffentlich":true,"url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC5397377/","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Flavell, J. H. (1979): Metacognition and Cognitive Monitoring: A New Area of Cognitive-Developmental Inquiry. American Psychologist 34, 906–911","oeffentlich":false}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"5c1904683ad484c2"}},{"id":"qx-a2-022","clusterId":"A","werkstueckRef":"A.17","stufe":3,"question":"Was erklärt das am besten?","options":["Die Selbstprüfung ist zu oberflächlich: Sie fragt nur nach ihren Gefühlen und nicht nach ihrer Strategie, daher bringt sie im Spiel nichts.","Die Selbstprüfung kommt am falschen Ort und zur falschen Zeit: Wo Sekundenbruchteile zählen, kostet sie Reaktionszeit, und die Spielerin zögert.","Im Spiel lässt der Druck ihre Konzentration einbrechen (Leistungsangst), und diese Unsicherheit hat mit ihrer Selbstprüfung nichts zu tun.","Die Erkenntnisse aus Training und Videoanalyse lassen sich nicht auf echte Spielsituationen übertragen, daher wirkt sie im Spiel unsicher."],"correctIndex":1,"explanation":"Nachdenken über das eigene Denken (Fachbegriff: Metakognition) kann in Situationen hinderlich sein, die schnelle, intuitive Entscheidungen erfordern; Sport und Notfälle sind typische Beispiele. Solche Selbstprüfung ist langsam und anstrengend: Wo Sekundenbruchteile zählen, kostet sie Zeit, man analysiert, statt zu reagieren, und zögert. Das Werkzeug an sich bleibt nützlich, es kommt auf den passenden Ort und Zeitpunkt an, etwa im Training oder in der Pause. Oberflächlich ist ihre Selbstprüfung nicht, denn sie fragt nach Gefühlen und nach Strategie. Von Wettkampfdruck ist im Szenario keine Rede; die Unsicherheit entsteht, seit sie auch im Spiel jeden Wurf prüft. Und Training und Videoanalyse bringen ihr ja nachweislich viel.","coreRule":"⚡ Selbstprüfung gehört in ruhige Momente; wo Sekundenbruchteile zählen, zählt das Handeln.","beleg":"Werkstück A.17 (Der Kipppunkt; Anwendung)","status":"entwurf","scenario":"Die Torhüterin einer Handballmannschaft will nach jedem Gegentor ihre Entscheidungen verbessern. Im Training, in der Halbzeitpause und bei der Videoanalyse prüft sie ihre Entscheidungen gründlich, und dort bringt ihr das viel. Inzwischen prüft sie auch im Spiel bei jedem Wurf zuerst, was sie gerade denkt und fühlt, welche Strategie sie nutzt und ob die zu ihr passt. Das Team kassiert viele Tore, sie wirkt unsicher.","quote":"","quoteLabel":"","kurz":"Im Spiel zählen Sekundenbruchteile, und Selbstprüfung ist langsam: Wer analysiert, statt zu reagieren, zögert. Das Werkzeug taugt weiter, nur nicht an diesem Ort. Im Training und in der Pause nützt es ihr ja nachweislich.","prueffrage":"Wie hat die Torhüterin gehalten, bevor sie im Spiel mit dieser Selbstprüfung begann, und wie seitdem?","rueckmeldung":[{"option":0,"text":"Oberflächlich ist ihre Selbstprüfung nicht: Sie fragt nach Gedanken, Gefühlen, Strategie und deren Passung. Im Training bringt genau diese Gründlichkeit viel, es kommt also auf den Einsatzort an, nicht auf die Tiefe."},{"option":2,"text":"Druck kann Konzentration tatsächlich stören, doch davon steht im Szenario nichts. Die Unsicherheit beginnt, seit sie im Spiel jeden Wurf prüft, ein Zusammenhang liegt also nahe, und ihn auszuschließen, wäre voreilig."},{"option":3,"text":"Dass sich Gelerntes nicht immer aufs Spiel übertragen lässt, kommt vor. Hier spricht aber dagegen, dass Training und Videoanalyse ihr viel bringen und das Problem erst mit der Prüfung im laufenden Spiel entsteht."}],"familie":"wissensgrenze-benennen","fertigkeit":"F5","quellen":[{"typ":"url","kurz":"Worthy, D. A.; Markman, A. B.; Maddox, W. T. (2009): Choking and excelling under pressure in experienced classifiers. Attention, Perception & Psychophysics 71(4), 924–935 (PMC)","oeffentlich":true,"url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC2708085/","abruf":"2026-10-12"},{"typ":"url","kurz":"Kahneman, D. (2002): Maps of Bounded Rationality. Nobel Prize Lecture, nobelprize.org","oeffentlich":true,"url":"https://www.nobelprize.org/uploads/2018/06/kahnemann-lecture.pdf","seite":"450","abruf":"2026-10-12"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"5c87a77862b7a24c"}},{"id":"qx-a2-023","clusterId":"A","werkstueckRef":"A.18","stufe":1,"question":"Zwei Personen reagieren auf eine neue Meldung: „Ein Präparat soll Erkältungen halbieren.“ Person A sagt: „Zeig mir eine kontrollierte Studie, die das belegt. Bis dahin halte ich die Aussage für unbewiesen. Wenn die Daten stimmen, ändere ich meine Meinung.“ Person B sagt: „Das ist Unsinn, das stimmt nie. Egal, welche Studie du bringst: Die ist gekauft.“ Was unterscheidet die beiden Haltungen im Kern?","options":["A macht sein Urteil vom Prüfergebnis abhängig und würde es ändern; B hat das Ergebnis schon festgelegt und wertet jeden Beleg ab.","A zeigt Autoritätsgläubigkeit, weil er Studien über sein eigenes Urteil stellt; B denkt selbstständig und lässt sich nicht von Studien vorschreiben, was er glaubt.","A lehnt die Behauptung wegen Zweifeln an der Quelle ab, ohne sie zu prüfen; B untersucht zuerst die Interessen der Studienautoren und urteilt erst danach.","A vertraut der Behauptung, solange sie nicht widerlegt ist; B misstraut ihr, solange sie nicht bewiesen ist; beide suchen nur Bestätigung ihrer Haltung."],"correctIndex":0,"explanation":"Person A legt fest, was sie überzeugen würde, und hält ihr Urteil bis dahin zurück. Das ist eine Methode: Die Stärke der Überzeugung richtet sich nach der Stärke der Belege. Person B hat die Schlussfolgerung schon gefasst und arbeitet sich rückwärts: Jeder widersprechende Beleg wird im Voraus abgewertet, damit das Ergebnis nicht gefährdet wird. Eine solche Position ist gegen Evidenz immun und deshalb keine Prüfung, sondern die Verteidigung eines fertigen Ergebnisses. Pauschales Misstrauen gegenüber allem wäre ebenfalls keine Methode, sondern Zynismus. A stellt Studien nicht über sein Urteil, sondern macht sein Urteil von ihnen abhängig, das ist keine Autoritätsgläubigkeit. B untersucht keine Studienautoren, er erklärt jede Studie vorab für gekauft. Und A hält die Behauptung gerade nicht für wahr, solange sie nicht widerlegt ist, sondern für unbewiesen.","coreRule":"⚡ Ein Skeptiker prüft mit offener Methode und kann sagen, was ihn umstimmen würde; ein Leugner verteidigt ein fertiges Ergebnis.","quote":"","quoteLabel":"","beleg":"Werkstück A.18 (Kernidee; Kontext & Tiefe); Fn. ga-leugnung (Hansson 2017, Studies in History and Philosophy of Science 63, S. 39–47)","status":"entwurf","scenario":"","kurz":"A sagt vorab, was ihn überzeugen würde, und hält sein Urteil bis dahin zurück: Die Überzeugung folgt den Belegen. B wertet jede Studie schon ab, bevor er sie kennt, und verteidigt ein fertiges Ergebnis. Das ist keine Prüfung mehr.","prueffrage":"Was sagt jede der beiden Personen über eine Studie, die es noch gar nicht gibt?","rueckmeldung":[{"option":1,"text":"Studien nicht blind zu glauben, ist sinnvoll. Hier ist es aber umgekehrt: A macht sein Urteil von Belegen abhängig und bleibt offen, während B jede Studie vorab verwirft und sein Ergebnis gar nicht mehr überprüfen lässt."},{"option":2,"text":"Die Rollen sind hier vertauscht. A lehnt nichts ab, sondern hält die Aussage bis zu den Daten für unbewiesen. B prüft auch keine Interessen der Autoren, sondern erklärt jede Studie vorab für gekauft."},{"option":3,"text":"Pauschales Misstrauen wie bei B trägt tatsächlich nicht, und es ist keine Methode. A glaubt der Behauptung aber nicht, sondern nennt sie unbewiesen, und er sucht keine Bestätigung, weil er seine Meinung bei guten Daten ändern würde."}],"familie":"gewissheit-kalibrieren","fertigkeit":"F5","quellen":[{"typ":"url","kurz":"Hansson, S. O.: Science and Pseudo-Science. Stanford Encyclopedia of Philosophy","oeffentlich":true,"url":"https://plato.stanford.edu/entries/pseudo-science/","abruf":"2026-10-07"},{"typ":"doi","kurz":"Hansson, S. O. (2017): Science denial as a form of pseudoscience. Studies in History and Philosophy of Science Part A 63, 39–47","oeffentlich":false,"doi":"10.1016/j.shpsa.2017.05.002"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"5aa2313b612d3bd6"}},{"id":"qx-a2-024","clusterId":"A","werkstueckRef":"A.18","stufe":2,"question":"Welche Frage prüft seine Behauptung am besten?","scenario":"Auf einer Feier erzählt dir ein Astrologe begeistert, die Stellung der Planeten sage seit Jahren zuverlässig voraus, was im Leben seiner Kundschaft geschieht.","options":["„Kannst du mir Fälle nennen, in denen deine Vorhersagen eingetroffen sind, und wie viele waren es?“","„Welche Ausbildung hast du, und in welchen Medien wurdest du als Experte zitiert?“","„Wie wirken die Planeten auf mich, und gibt es Tests mit Treffern über dem Zufall?“","„Wie lange gibt es die Astrologie schon, und in wie vielen Kulturen wird sie bis heute genutzt?“"],"correctIndex":2,"explanation":"Eine Behauptung wird geprüft, indem man fragt, welcher Mechanismus sie erklären soll und ob kontrollierte Studien zeigen, dass die Vorhersagen besser sind als reiner Zufall. Einzelne eingetroffene Vorhersagen sind kein Beleg, denn ohne Vergleich mit dem Zufall lässt sich nicht sagen, ob die Treffer mehr sind als Glück. Fragen nach Ausbildung oder Medienauftritten prüfen die Person, nicht die Behauptung. Alter und Verbreitung einer Praxis sagen nichts darüber, ob sie wirkt. Astrologie hat in kontrollierten Tests bisher keine Treffer über dem Zufall gezeigt. Die Frage nach solchen Tests lässt das Gegenüber selbst nachsehen, statt es nur abzuwerten.","coreRule":"⚡ Frag nach Mechanismus und kontrollierten Tests, nicht nach dem Ruf des Behauptenden.","beleg":"Werkstück A.18 (Anwendung: Gegenüber Pseudowissenschaft & Esoterik; Red Flags)","status":"entwurf","kurz":"Eine Behauptung prüft man, indem man nach einem erklärenden Mechanismus und nach kontrollierten Tests fragt, deren Treffer über dem Zufall liegen. Einzelne eingetroffene Vorhersagen, Titel oder Alter beweisen nichts, weil sie keinen Vergleich mit dem Zufall liefern.","prueffrage":"Welche Vorhersagen hat er in den letzten Jahren gemacht, und wurden sie aufgeschrieben, bevor sich zeigte, ob sie eintreffen?","rueckmeldung":[{"option":0,"text":"Nach konkreten Fällen zu fragen, wirkt greifbar und ist besser als blindes Vertrauen. Gezählt werden aber nur die Treffer, ohne Fehlschläge und ohne Vergleich mit dem Zufall. Bei vagen Vorhersagen trifft immer etwas ein, auch ohne Wirkung."},{"option":1,"text":"Ausbildung und Medienauftritte lassen sich leicht erfragen und klingen nach Seriosität. Sie sagen aber etwas über die Person und nicht darüber, ob die Vorhersagen besser sind als der Zufall. Die Behauptung selbst bleibt damit ungeprüft."},{"option":3,"text":"Alter und weite Verbreitung sind überprüfbare Tatsachen und beeindrucken leicht. Ob eine Praxis wirkt, sagt das jedoch nicht: Auch Irrtümer können sehr alt sein und in vielen Kulturen gepflegt werden."}],"familie":"wissenschaft-abgrenzen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Dean, G.; Kelly, I. W. (2003): Is astrology relevant to consciousness and psi? (Nachdruck auf astrology-and-science.com)","oeffentlich":true,"url":"https://astrology-and-science.com/D-psia1.htm","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Dean, G.; Kelly, I. W. (2003): Is astrology relevant to consciousness and psi? Journal of Consciousness Studies 10(6–7), 175–198","oeffentlich":false}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"6192bad0c375c7f2"}},{"id":"qx-a2-025","clusterId":"A","werkstueckRef":"A.18","stufe":3,"question":"Jemand sagt: „Es gibt keine absolute Gewissheit, also ist die Kugelgestalt der Erde ebenso gut begründet wie die Scheibe.“ Was ist an diesem Schluss fehlerhaft?","options":["Er fordert zu Recht Belege für beide Seiten, wendet diese Forderung aber nur auf die Kugelgestalt an.","Er behandelt Quellen und Motive der Wissenschaft pauschal als verdächtig, statt Belege zu prüfen.","Er folgert aus fehlender absoluter Gewissheit, dass alle Behauptungen gleich gut belegt sind.","Er verlässt sich auf eine einzelne Autorität, statt die Behauptung selbst zu prüfen."],"correctIndex":2,"explanation":"Dass es keine absolute Gewissheit gibt, stimmt, aber daraus folgt nicht, dass alle Behauptungen gleich unsicher wären. Es gibt verlässliche Methoden, um gut begründetes, wenn auch vorläufiges Wissen zu gewinnen, und die Stärke einer Überzeugung sollte der Stärke der Belege entsprechen. Für die Kugelgestalt der Erde sprechen unabhängige Belege aus vielen Richtungen, etwa Satellitenbilder, Erdumrundungen und der runde Erdschatten bei Mondfinsternissen; für die Scheibe gibt es nichts Vergleichbares. Beide gleichzusetzen ist kein Skeptizismus, sondern gibt das Prüfen auf: Hier kippt der Zweifel in die Haltung, dass gar kein Wissen möglich sei. Ein echter Skeptiker fragt, welche Belege jeweils vorliegen, und stuft sein Vertrauen danach ab.","coreRule":"⚡ Skeptizismus misst Überzeugung an der Stärke der Belege; Gleichmacherei ist keiner.","beleg":"Werkstück A.18 (Der Kipppunkt; Kontext & Tiefe: Proportionalität)","status":"entwurf","quote":"","quoteLabel":"","kurz":"Dass es keine absolute Gewissheit gibt, stimmt, macht aber nicht alle Behauptungen gleich unsicher: Entscheidend ist die Stärke der Belege, und die ist bei der Kugelgestalt ungleich größer. Wer alles gleichsetzt, ist nicht skeptisch, sondern gibt das Prüfen auf.","prueffrage":"Welche Belege lassen sich für jede der beiden Behauptungen tatsächlich nennen, und wie viele sind es?","rueckmeldung":[{"option":0,"text":"Belege von beiden Seiten zu verlangen, ist grundsätzlich fair. Im Satz steht aber keine einseitige Forderung: Er stellt beide Behauptungen gleich, weil nichts absolut gewiss sei. Der Fehler liegt in diesem Schluss, nicht in einem Doppelstandard."},{"option":1,"text":"Quellen und Motive kritisch anzusehen, gehört zum guten Prüfen, und manchmal wird es übertrieben. Der Satz greift aber weder Quellen noch Motive an, sondern schließt allein aus fehlender absoluter Gewissheit auf Gleichwertigkeit."},{"option":3,"text":"Selbst zu prüfen, statt einer einzelnen Autorität zu folgen, ist ein guter Grundsatz. Hier beruft sich der Sprecher aber auf keine Autorität, sondern auf ein allgemeines Prinzip, das er zu weit treibt."}],"familie":"gewissheit-kalibrieren","fertigkeit":"F5","quellen":[{"typ":"url","kurz":"Hume, D.: An Enquiry Concerning Human Understanding, Sect. X „Of Miracles“, Part I (Project Gutenberg, Ausg. Selby-Bigge)","oeffentlich":true,"url":"https://www.gutenberg.org/files/9662/9662-h/9662-h.htm","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"3cd1c60724ea0d91"}},{"id":"qx-a2-026","clusterId":"A","werkstueckRef":"A.18","stufe":4,"question":"Warum ist das Vorgehen von Prüfer B das methodisch bessere?","options":["Prüfer B legt die Regeln vorab fest; so kann der Test eine echte Fähigkeit belegen oder die Behauptung scheitern lassen, ohne dass das Ergebnis nachträglich zurechtgebogen wird.","Prüfer B bleibt freundlich und respektvoll gegenüber dem Mann; so fühlt dieser sich ernst genommen und führt seine Fähigkeit bereitwilliger und entspannter vor.","Prüfer B wiederholt den Test oft genug, bis sich ein stabiles Muster zeigt; so gleichen sich einzelne Zufallstreffer in der Gesamtzahl der Versuche aus.","Prüfer B zieht erfahrene Wünschelrutengänger als Beurteiler hinzu; so wird die Behauptung nach den Maßstäben derer geprüft, die sich damit auskennen."],"correctIndex":0,"explanation":"Wer von vornherein weiß, dass jemand betrügt, und dann nur nach dem Trick sucht, kann nichts anderes finden als eine Bestätigung seiner Annahme. Das mag als Entlarvung brillant sein, ist aber keine Untersuchung, denn die Schlussfolgerung stand schon fest. Ein vorab vereinbarter, fairer Test ist ergebnisoffen: Besteht der Prüfling unter kontrollierten Bedingungen, muss man die eigene Meinung ändern; besteht er nicht, bleibt die Behauptung unbewiesen, und kein Prüfer hat sich sein Urteil nachträglich zurechtgelegt. So arbeitete auch der Zauberkünstler James Randi, dessen Millionen-Dollar-Herausforderung nach diesem Prinzip aufgebaut war und bis zu ihrem Ende 2015 von niemandem bestanden wurde. Respekt gegenüber dem Mann ist wichtig, macht den Test aber nicht aussagekräftiger. Wiederholungen sind in Tests sinnvoll, davon ist hier aber nicht die Rede, und sie ersetzen nicht die vorab vereinbarten Regeln. Und nicht die Maßstäbe der Praktiker entscheiden, sondern die vorab festgelegten Erfolgskriterien.","coreRule":"⚡ Echte Skepsis lässt dem Behauptenden eine faire Chance, sich zu bewähren.","beleg":"Werkstück A.18 (Einstiegsgeschichte); Fn. ga-randi (Houdini † 1926, Randi * 1928; Zuspitzung, keine wörtlich belegte Aussage)","status":"entwurf","scenario":"Ein Mann behauptet, er könne mit einer Wünschelrute Wasseradern unter der Erde aufspüren. Zwei Prüfer sollen die Behauptung untersuchen. Prüferin A sagt: „Das ist Schwindel. Ich beobachte ihn, bis ich den Trick finde, mit dem er die Leute täuscht.“ Prüfer B sagt: „Wir legen vorab gemeinsam fest, was als Erfolg zählt, schließen Tricks aus und testen ihn unter diesen Bedingungen.“","kurz":"Wer schon weiß, dass getäuscht wird, und nur den Trick sucht, findet höchstens die eigene Annahme bestätigt. Ein vorab vereinbarter Test ist ergebnisoffen: Er kann die Fähigkeit belegen oder scheitern, ohne dass jemand sein Urteil nachträglich zurechtlegt.","prueffrage":"Was genau soll der Mann bei Prüfer B tun, und woran liest man danach ab, ob er Erfolg hatte?","rueckmeldung":[{"option":1,"text":"Respekt gegenüber dem Mann ist wichtig und gehört zu einem anständigen Test. Wie aussagekräftig das Ergebnis ist, hängt aber an den Bedingungen und Kriterien, nicht an der Stimmung des Prüflings."},{"option":2,"text":"Wiederholungen sind in Tests sinnvoll, weil sie Zufallstreffer ausgleichen. Hier ist davon aber nicht die Rede, und sie ersetzen nicht, dass die Erfolgskriterien vorab feststehen. Ohne sie lässt sich auch eine lange Versuchsreihe nachträglich zurechtbiegen."},{"option":3,"text":"Sachkundige Beurteiler klingen nach einem fairen Test. Steht aber nicht fest, was als Erfolg zählt, entscheiden deren Maßstäbe, und die gehen von der Wirksamkeit der Rute aus. Maßgeblich sind die vorab festgelegten Erfolgskriterien."}],"familie":"fair-testen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Wikipedia: One Million Dollar Paranormal Challenge","oeffentlich":true,"url":"https://en.wikipedia.org/wiki/One_Million_Dollar_Paranormal_Challenge","abruf":"2026-10-04"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"9409769ab9898b9a"}},{"id":"qx-a2-027","clusterId":"A","werkstueckRef":"A.19","stufe":1,"question":"Bevor du am Abend deinem Bauchgefühl folgst: Welche Frage hilft dir am meisten zu beurteilen, ob es für diese Entscheidung verlässlich ist?","options":["Wie stark und eindeutig fühlt sich mein Bauchgefühl gerade an, und wie überzeugt bin ich von ihm?","Wie gut könnte ich meine Entscheidung vor anderen begründen, falls später jemand danach fragt?","Wie hoch sind die Kosten eines Irrtums, und ist das ein Bereich, in dem sich mein Bauchgefühl bewährt hat?","Wie viele andere Menschen würden in dieser Lage wahrscheinlich dieselbe Entscheidung treffen wie ich?"],"correctIndex":2,"explanation":"Schnelle Faustregeln wie das Bauchgefühl sind nützlich, wenn ein Fehler wenig kostet: Wer bei Marmelade danebengreift, verliert kaum etwas. Bei einer Wahl oder einer Behandlung kann ein Irrtum dagegen schwere Folgen haben; je mehr auf dem Spiel steht, desto weniger sollte man sich ungeprüft auf eine Faustregel verlassen. Deshalb prüfst du zuerst, was auf dem Spiel steht und ob sich dein Bauchgefühl in diesem Bereich schon bewährt hat. Ist der Einsatz hoch und fehlt diese Bewährung, lohnt sich eine langsamere, gründlichere Prüfung anhand von Daten und Alternativen. Weder ein starkes Gefühl der Sicherheit noch die Zahl der Menschen, die genauso entscheiden würden, zeigt, ob das Bauchgefühl richtigliegt. Auch die Frage, wie gut sich die Entscheidung vor anderen begründen lässt, ist als Rechenschaft sinnvoll, sagt aber nichts darüber, ob das Gefühl in diesem Bereich treffsicher ist.","coreRule":"⚡ Faustregeln sind meist gut genug, aber je höher die Kosten eines Fehlers, desto eher lohnt die langsame Prüfung.","quote":"Der Kipppunkt ist die Relevanz der Entscheidung.","quoteLabel":"Zum Weiterdenken:","beleg":"Werkstück A.19 (Kernidee; Kontext & Tiefe); Fn. ga-heuristiken (Tversky/Kahneman 1974, Science 185, S. 1124)","status":"entwurf","scenario":"Zwei Situationen am selben Tag: Im Supermarkt greifst du ohne Nachdenken zur Marmeladensorte, die du kennst. Am Abend soll dein Bauchgefühl entscheiden, ob du einem Kandidaten bei einer wichtigen Wahl deine Stimme gibst oder einer teuren medizinischen Behandlung zustimmst.","kurz":"Entscheidend ist, was bei einem Irrtum auf dem Spiel steht und ob sich dein Gefühl in diesem Bereich schon bewährt hat. Bei der Marmelade ist ein Fehler billig, bei Wahl oder Behandlung nicht; das Gefühl der Sicherheit zeigt davon nichts.","prueffrage":"Wie oft hast du bei Marmelade und wie oft bei Wahlen oder Behandlungen schon aus dem Bauch entschieden, und wie ging es aus?","rueckmeldung":[{"option":0,"text":"Ein starkes, eindeutiges Gefühl ist leicht zu spüren und fühlt sich wie ein Qualitätsmerkmal an. Wie sicher du dich fühlst, sagt aber nichts darüber, ob du in diesem Bereich richtigliegst oder wie viel bei einem Irrtum auf dem Spiel steht."},{"option":1,"text":"Dich vor anderen erklären zu können, ist als Rechenschaft sinnvoll. Es zeigt aber nicht, ob dein Gefühl in diesem Bereich treffsicher ist; eine Begründung lässt sich auch im Nachhinein um ein Gefühl herum bauen."},{"option":3,"text":"Wenn viele ähnlich entscheiden würden, wirkt die Entscheidung abgesichert. Viele können sich aber gemeinsam irren, und die Zahl sagt nichts darüber, wie schwer ein Irrtum wiegt oder ob dein Gefühl hier verlässlich ist."}],"familie":"faustregel-oder-rechnen","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Kahneman, D.; Klein, G. (2009): Conditions for intuitive expertise: a failure to disagree. American Psychologist 64(6), 515–526 (PubMed-Abstract)","oeffentlich":true,"url":"https://pubmed.ncbi.nlm.nih.gov/19739881/","abruf":"2026-10-12"},{"typ":"url","kurz":"Kahneman, D. (2002): Maps of Bounded Rationality. Nobel Prize Lecture, nobelprize.org","oeffentlich":true,"url":"https://www.nobelprize.org/uploads/2018/06/kahnemann-lecture.pdf","seite":"465","abruf":"2026-10-12"},{"typ":"doi","kurz":"Tversky, A.; Kahneman, D. (1974): Judgment under Uncertainty: Heuristics and Biases. Science 185(4157), 1124–1131","oeffentlich":false,"doi":"10.1126/science.185.4157.1124","seite":"1124"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"99daa7e09724d09a"}},{"id":"qx-a2-028","clusterId":"A","werkstueckRef":"A.19","stufe":2,"question":"Warum ist es hier vernünftig, einfach die bekannte Marke zu nehmen, statt alle Sorten zu vergleichen?","scenario":"Im Supermarkt stehst du vor einem Regal mit 50 Marmeladensorten und greifst ohne langes Nachdenken zu deiner gewohnten Marke.","options":["Vertrautes wirkt sympathischer, und Sympathie ist ein guter Hinweis darauf, welche Sorte am besten schmeckt.","Ein Fehlgriff kostet wenig, ein Vergleich aller Sorten dagegen unverhältnismäßig viel Zeit und Mühe.","Die meisten Käufer greifen zur bekannten Marke, und die Wahl der Mehrheit ist ein guter Hinweis auf die beste Sorte.","Wer die Marke schon oft gekauft hat, sollte ihr treu bleiben, damit die bisherigen Käufe nicht umsonst waren."],"correctIndex":1,"explanation":"Faustregeln sind mentale Abkürzungen, die in den meisten Fällen „gut genug“ sind, aber nicht optimal und nicht fehlerfrei. Entscheidend ist das Verhältnis von Aufwand und Einsatz: Bei der Marmelade ist ein möglicher Fehler trivial, während ein vollständiger Vergleich aller 50 Sorten viel Zeit und Energie kostet. Wer vor jedem Regal alles durchrechnen wollte, käme im Alltag kaum zum Handeln. Anders sieht es aus, wenn viel auf dem Spiel steht, etwa bei einer medizinischen Entscheidung: Dort lohnt sich der Wechsel zum langsamen, genauen Prüfen, weil ein Fehler teuer wäre. Dass Vertrautes sympathischer wirkt, erklärt höchstens die Vorliebe, nicht ihre Vernunft. Von anderen Käufern ist im Szenario keine Rede, und die Wahl der Mehrheit sagt nichts über die Qualität. Bereits getätigte Käufe sind ausgegeben und sprechen deshalb nicht für künftige.","coreRule":"⚡ Bei geringem Einsatz ist die Faustregel klug, bei hohem Einsatz lohnt das genaue Rechnen.","beleg":"Werkstück A.19 (Das Adaptive Talent; Der Kipppunkt)","status":"entwurf","kurz":"Hier ist die Abkürzung vernünftig, weil ein Fehlgriff bei Marmelade wenig kostet, ein Vergleich aller 50 Sorten aber viel Zeit und Energie. Faustregeln sind „gut genug“, nicht optimal. Bei großen Entscheidungen lohnt sich genaues Prüfen.","prueffrage":"Wie oft hat dich die gewohnte Marke schon enttäuscht, und was hast du dann getan?","rueckmeldung":[{"option":0,"text":"Vertrautes wirkt tatsächlich sympathischer. Das erklärt aber höchstens die Vorliebe, nicht ihre Vernunft: Wie sehr dir etwas gefällt, sagt nicht, ob die Sorte am besten schmeckt."},{"option":2,"text":"Von anderen Käufern ist im Szenario nirgends die Rede, und die Wahl der Mehrheit sagt ohnehin nichts über die Qualität einer Sorte. Viele können sich irren oder einfach einander folgen."},{"option":3,"text":"Die früheren Käufe sind bezahlt und ausgegeben, sie begründen keinen künftigen. Ob die Marke gut ist, ist eine andere Frage als die, ob sich frühere Käufe „gelohnt“ haben."}],"familie":"faustregel-oder-rechnen","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Stanford Encyclopedia of Philosophy: Bounded Rationality (überarb. 2024)","oeffentlich":true,"url":"https://plato.stanford.edu/entries/bounded-rationality/","abruf":"2026-10-12"},{"typ":"url","kurz":"Kahneman, D. (2002): Maps of Bounded Rationality. Nobel Prize Lecture, nobelprize.org","oeffentlich":true,"url":"https://www.nobelprize.org/uploads/2018/06/kahnemann-lecture.pdf","seite":"483","abruf":"2026-10-12"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"c4386bfc115af618"}},{"id":"qx-a2-029","clusterId":"A","werkstueckRef":"A.19","stufe":3,"question":"Woran lässt sich am besten erkennen, dass die Kollegin hier nicht auf die schnelle Faustregel vertrauen sollte?","options":["Sie fühlt sich absolut sicher, also ist die schnelle Faustregel in diesem Fall besonders verlässlich.","Der Einsatz ist hoch und eine Prüfung wäre möglich, also sollte sie in die langsame, datenbasierte Analyse wechseln.","Ein Bauchgefühl entsteht aus eigener Erfahrung, also ist es verlässlicher als jede Zahl oder Gegenprüfung.","Fünf Minuten sind für so einen Vertrag zu kurz, also wäre er nach einer Stunde Grübeln automatisch gut geprüft."],"correctIndex":1,"explanation":"Faustregeln sind schnell und meist gut genug, aber ihre Fehler sind vorhersagbar. Ob du ihnen trauen darfst, hängt davon ab, was ein Fehler kostet: Beim Marmeladenkauf ist er trivial, bei einem mehrjährigen Vertrag oder einer medizinischen Entscheidung kann er schwer wiegen. Dann lohnt sich der Wechsel ins langsame, analytische Denken, zumal Zeit zum Prüfen da ist. Ein starkes Sicherheitsgefühl spricht nicht für die Faustregel: Gerade wer bei einer schnellen Entscheidung in komplexer Lage absolut sicher ist, sollte misstrauisch werden. Und es kommt nicht auf die Dauer des Grübelns an, sondern auf die Art der Prüfung: Daten, Vergleiche, Gegenfragen.","coreRule":"⚡ Je höher der Einsatz, desto weniger darfst du dich auf die schnelle Faustregel verlassen.","beleg":"Werkstück A.19 (Der Kipppunkt; Red Flags)","status":"entwurf","scenario":"Eine Kollegin will in fünf Minuten über einen Vertrag entscheiden, der die Firma mehrere Jahre bindet. Sie sagt: „Ich habe sofort ein gutes Gefühl dabei, das passt. Ich bin mir absolut sicher.“ Detailprüfung oder Vergleichsangebote gab es nicht.","quote":"","quoteLabel":"","kurz":"Hoher Einsatz und vorhandene Zeit zum Prüfen sprechen für die langsame Analyse: Faustregeln sind meist gut genug, aber ihre vorhersagbaren Fehler können bei einem mehrjährigen Vertrag teuer werden. Das Gefühl absoluter Sicherheit ersetzt die Prüfung nicht.","prueffrage":"Was weiß die Kollegin über diesen Vertrag tatsächlich, außer dass er sich nach fünf Minuten gut anfühlt?","rueckmeldung":[{"option":0,"text":"Das Gefühl ist echt, und Faustregeln sind meist gut genug. Starke Sicherheit verbürgt aber keine gute Entscheidung; bei einer schnellen Wahl in komplexer Lage ist sie eher ein Grund zum Misstrauen."},{"option":2,"text":"Bauchgefühle speisen sich tatsächlich oft aus Erfahrung und treffen meist gut. Das macht sie aber nicht verlässlicher als jede Gegenprüfung: Ihre Fehler sind vorhersagbar, und bei hohem Einsatz lohnen sich Daten und Vergleiche."},{"option":3,"text":"Fünf Minuten wirken für diesen Vertrag zwar knapp. Doch eine Stunde Grübeln ändert nichts, wenn nur dieselben Gedanken kreisen. Entscheidend ist die Art der Prüfung: Daten, Vergleiche, Gegenfragen."}],"familie":"faustregel-oder-rechnen","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Kahneman, D.; Klein, G. (2009): Conditions for intuitive expertise: a failure to disagree. American Psychologist 64(6), 515–526 (PubMed-Abstract)","oeffentlich":true,"url":"https://pubmed.ncbi.nlm.nih.gov/19739881/","abruf":"2026-10-12"},{"typ":"url","kurz":"Kahneman, D. (2002): Maps of Bounded Rationality. Nobel Prize Lecture, nobelprize.org","oeffentlich":true,"url":"https://www.nobelprize.org/uploads/2018/06/kahnemann-lecture.pdf","seite":"465, 472","abruf":"2026-10-12"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"271b7c222a944df9"}},{"id":"qx-a2-030","clusterId":"A","werkstueckRef":"A.19","stufe":4,"question":"Welcher Denkfehler steckt im Argument des Freundes?","options":["Er nimmt an, die erste Erklärung, die er gehört hat, sei die richtige, und passt seine Einschätzung nur geringfügig an.","Er hält die Verschwörungserklärung für häufig, weil ihm viele Fälle von geheimen Plänen leicht einfallen.","Er hält die Erklärung für glaubwürdig, weil sie ihm aus früheren Gesprächen und Berichten schon vertraut vorkommt.","Er schließt von der Größe des Ereignisses auf eine ebenso große, geordnete Ursache, ohne diese zu prüfen."],"correctIndex":3,"explanation":"Der Freund verlässt sich auf eine Faustregel: Ein großes Ereignis muss auch eine ebenso große Ursache haben. Geplant war der Anschlag zwar, aber von al-Qaida mit 19 Attentätern und nicht von allmächtigen Hintermännern im Verborgenen. Die gewaltigen Folgen sagen also wenig darüber, wie groß und mächtig die Urheber sind; das Gefühl, eine riesige Wirkung verlange eine riesige Ursache, ersetzt keine Prüfung an Belegen. Die anderen Antworten beschreiben andere Denkfehler (Anker, leichte Erinnerbarkeit, Vertrautheit), die im Argument gar nicht vorkommen: Der Freund beruft sich weder auf eine zuerst gehörte Erklärung noch auf erinnerte Einzelfälle noch auf Bekanntes, sondern allein auf die Größe des Ereignisses.","coreRule":"⚡ Wenn eine Erklärung überzeugt, weil sie so groß ist wie das Ereignis, frage nach Belegen statt nach Stimmigkeit.","beleg":"Werkstück A.19 (Anwendung: Bei Verschwörungsmythen; Kontext & Tiefe: Repräsentativitätsheuristik)","status":"entwurf","scenario":"Nach dem Anschlag vom 11. September 2001 verbreitet sich die Behauptung, dahinter müsse ein langfristig geplanter, geheimer Plan mächtiger Hintermänner stecken. Ein Freund sagt: „So etwas Riesiges kann doch unmöglich einfach so passiert sein.“","kurz":"Der Freund schließt von der Größe des Ereignisses auf eine ebenso große, geordnete Ursache. Das fühlt sich stimmig an, ersetzt aber keine Prüfung an Belegen: Riesige Folgen beweisen keine mächtigen Hintermänner.","prueffrage":"Was müsste man über die Täter eines Anschlags wissen, um zu beurteilen, wie mächtig und gut organisiert sie waren?","rueckmeldung":[{"option":0,"text":"Sich an eine zuerst gehörte Erklärung zu klammern, ist ein bekannter Fehler. Davon ist hier aber nichts zu sehen: Der Freund beruft sich nicht darauf, was er zuerst gehört hat, sondern auf die schiere Größe des Ereignisses."},{"option":1,"text":"Dass uns auffällige Einzelfälle leicht einfallen und deshalb häufiger wirken, ist ein echter Denkfehler. Der Freund nennt aber keine Einzelfälle und schätzt keine Häufigkeit; sein ganzer Gedanke hängt an der Größe des Ereignisses."},{"option":2,"text":"Vertraut Klingendes wirkt oft glaubwürdiger, das ist ein bekannter Effekt. Der Freund begründet seine Haltung aber nicht damit, dass er die Geschichte schon kennt, sondern damit, dass etwas so Großes nicht zufällig geschehen könne."}],"familie":"deutung-von-fakten-trennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Brotherton, R.; French, C. C. (2014): Belief in Conspiracy Theories and Susceptibility to the Conjunction Fallacy. Applied Cognitive Psychology 28, 238–248 (Repositorium Goldsmiths)","oeffentlich":true,"url":"https://eprints-gro.gold.ac.uk/10794/1/acp2995.pdf","seite":"238","abruf":"2026-10-12"},{"typ":"url","kurz":"National Commission on Terrorist Attacks Upon the United States: The 9/11 Commission Report, Executive Summary","oeffentlich":true,"url":"https://www.9-11commission.gov/report/911Report_Exec.htm","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"7ab9641d917dd846"}},{"id":"qx-a2-031","clusterId":"A","werkstueckRef":"A.20","stufe":1,"question":"Welche Antwort erklärt am besten, warum die Ärzte damals Semmelweis’ Idee nicht prüften, sondern als „sinnlosen Lärm“ abtaten?","options":["Die Idee passte nicht in den unausgesprochenen Rahmen aus Annahmen, den alle für selbstverständlich hielten, und galt deshalb gar nicht erst als ernsthafte Hypothese.","Die Ärzte hielten die Idee insgeheim für möglich, wollten aber ihr Ansehen nicht gefährden und wiesen sie deshalb bewusst zurück, ohne sie zu prüfen.","Die Ärzte konnten die Idee mangels Fachwissen nicht einordnen und verwarfen sie, weil sie die Zusammenhänge nicht durchschauten und schlicht überfordert waren.","Die Ärzte beurteilten die Idee nach ihrem Urheber: Weil er jung war und im Fach noch nichts galt, nahmen sie seine Aussagen von vornherein nicht ernst."],"correctIndex":0,"explanation":"Die Ablehnung lässt sich am sparsamsten so erklären: Ein System selbstverständlicher Annahmen (Krankheit durch Miasmen oder Säfteungleichgewicht) bestimmt, was überhaupt als sinnvolle Idee zählt. Innerhalb dieses Rahmens war „Leichenteilchen an den Händen“ keine falsche Hypothese, sondern unverständlich. Solche Rahmen sind meist unbewusst, die Beteiligten halten sie schlicht für „normal“. Das erklärt auch, warum Fakten allein den Streit nicht entschieden: Erst Jahrzehnte später, mit Pasteurs Keimtheorie, wurde Semmelweis’ Idee bestätigt. Ganz unschuldig war Semmelweis allerdings nicht: Er veröffentlichte spät, konnte die Wirkung des Chlorkalks nicht erklären und beschimpfte Kritiker. Andere Gründe, Neues abzulehnen, gibt es durchaus, sie passen aber nicht zu diesem Fall. Die Ärzte werden ausdrücklich als ehrlich und erfahren beschrieben, sodass weder bewusstes Verschweigen aus Eigennutz noch Überforderung die Ablehnung erklärt. Und sie hielten die Idee selbst für absurd, weil sie ihrem Weltbild widersprach, nicht weil ihr Urheber jung war.","coreRule":"⚡ Ein Paradigma ist die unsichtbare Karte, nach der ein Fach navigiert: Es entscheidet mit, was als sinnvolle Idee gilt, noch bevor jemand prüft.","beleg":"Werkstück A.20 (Kernidee; Kontext & Tiefe); Fn. ga-kuhn (Kuhn 1962, The Structure of Scientific Revolutions)","status":"entwurf","scenario":"Wien, 1847: Viele Wöchnerinnen sterben am Kindbettfieber. Ein junger Arzt behauptet, unsichtbare Leichenteilchen an den Händen der Ärzte seien die Ursache, und verlangt, dass sich alle vor jeder Untersuchung die Hände in Chlorkalklösung waschen. Seine Kollegen halten das für absurd und beleidigend. Dabei sind sie weder dumm noch unehrlich, sondern erfahrene Ärzte, die sich an dem orientieren, was zu ihrer Zeit als gesichertes Wissen gilt: Krankheiten entstehen durch schlechte Luft (Miasmen) oder ein Ungleichgewicht der Körpersäfte.","quote":"","quoteLabel":"","kurz":"Im damaligen Rahmen aus Miasmen und Säfteungleichgewicht war „Leichenteilchen an den Händen“ keine falsche Hypothese, sondern unverständlich. Der Fehler liegt nicht in Dummheit oder Bosheit, sondern in unbewussten Annahmen, die alle für normal hielten.","prueffrage":"Wofür hielten die Kollegen die Forderung, und wie würdest du reagieren, wenn du nur ihr damaliges Wissen hättest?","rueckmeldung":[{"option":1,"text":"Dass Statusdenken beim Ablehnen von Neuem mitspielen kann, ist richtig. Das Szenario beschreibt die Ärzte aber als ehrlich: Sie hielten die Idee wirklich für absurd, statt sie wider besseres Wissen zu verwerfen."},{"option":2,"text":"Eine fehlende Prüfung wirkt schnell wie Unwissen. Die Ärzte waren jedoch erfahren und urteilten nach dem damaligen gesicherten Wissen. Sie durchschauten die Idee durchaus, sie passte nur nicht zu ihrem Weltbild."},{"option":3,"text":"Dass der Urheber jung war, stimmt, und Urteile nach der Person kommen tatsächlich vor. Hier ist die Ablehnung aber so besser erklärt: Die Ärzte hielten die Idee selbst für absurd, weil sie ihrem Weltbild widersprach, ganz unabhängig vom Alter."}],"familie":"weltsicht-sichtbar-machen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Bird, A.: Thomas Kuhn. Stanford Encyclopedia of Philosophy (überarb. 2025)","oeffentlich":true,"url":"https://plato.stanford.edu/entries/thomas-kuhn/","abruf":"2026-10-07"},{"typ":"doi","kurz":"Best, M.; Neuhauser, D. (2004): Ignaz Semmelweis and the birth of infection control. Quality & Safety in Health Care 13(3), 233–234","oeffentlich":true,"doi":"10.1136/qshc.2004.010918","seite":"233–234","abruf":"2026-10-12"},{"typ":"doi","kurz":"Schreiner, S. (2020): Ignaz Semmelweis: a victim of harassment? Wiener Medizinische Wochenschrift 170(11–12), 293–302","oeffentlich":true,"doi":"10.1007/s10354-020-00738-1","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"871ee38c315a02ec"}},{"id":"qx-a2-033","clusterId":"A","werkstueckRef":"A.20","stufe":3,"question":"Wie ist das Verhalten dieser Fachgesellschaft zu beurteilen, und welcher Schritt wäre sinnvoll?","options":["Das Verhalten ist problematisch, weil Abweichungen ohne Prüfung wegerklärt und die Kritikerin ausgegrenzt werden. Sinnvoll wäre, die Daten unabhängig nachzuprüfen.","Das Verhalten ist unproblematisch, weil ein gemeinsamer Rahmen effizient arbeiten lässt und Abweichungen sich meist als Messfehler erweisen. Sinnvoll wäre, bei dieser Linie zu bleiben.","Das Verhalten ist problematisch, weil gehäufte Abweichungen die Theorie bereits widerlegt haben. Sinnvoll wäre, sie sofort aufzugeben und die Forschung neu zu beginnen.","Das Verhalten ist unproblematisch, weil eine Tagung ihre Beiträge frei auswählen darf und niemand Anspruch auf eine Einladung hat. Sinnvoll wäre, die Einladungspraxis beizubehalten."],"correctIndex":0,"explanation":"Ein gemeinsamer Theorierahmen ist nützlich: Er erspart es, bei jeder Beobachtung die Grundlagen neu zu verhandeln, und macht die Arbeit an Detailproblemen effizient. Dass die Theorie meist funktioniert und von vielen geteilt wird, spricht also nicht gegen sie, aber auch nicht gegen die Prüfung von Abweichungen. Problematisch wird ein Rahmen, wenn Abweichungen nicht mehr untersucht, sondern ungeprüft wegerklärt und Kritiker nicht mehr als Herausforderer, sondern als Feinde behandelt werden: Dann erstarrt er zum Dogma. Genau das passiert hier: Die Daten werden ungeprüft abgetan, die Forscherin wird ausgegrenzt. Sinnvoll ist deshalb, die Daten unabhängig nachzuprüfen; ob die Theorie angepasst oder gar ersetzt werden muss, zeigt erst diese Prüfung. Dass Abweichungen oft Messfehler sind, stimmt zwar, ist aber ohne Nachprüfung nur eine Vermutung. Ein freies Einladungsrecht ändert nichts daran, dass die Daten ungeprüft abgetan werden.","coreRule":"⚡ Ein Rahmen wird zum Dogma, wenn er Abweichungen und Kritiker bekämpft, statt sie zu untersuchen.","beleg":"Werkstück A.20 (Der Kipppunkt; Das Adaptive Talent; Kontext & Tiefe; Einleitung zu Semmelweis)","status":"entwurf","scenario":"In einer Fachgesellschaft häufen sich seit Jahren Messergebnisse, die zur herrschenden Theorie nicht passen. Der Vorstand erklärt sie regelmäßig zu Messfehlern, ohne die Daten nachzuprüfen. Eine Forscherin, die die Abweichungen systematisch untersuchen will, gilt als Querulantin; ihre Beiträge werden nicht mehr zu Tagungen eingeladen. Im Alltag funktioniert die Theorie sonst gut, und die meisten Mitglieder arbeiten gern damit.","kurz":"Der Rahmen darf nützlich sein, solange Abweichungen untersucht werden. Hier werden sie ungeprüft als Messfehler abgetan und die Forscherin ausgegrenzt; erst eine unabhängige Nachprüfung zeigt, ob die Theorie angepasst oder ersetzt werden muss.","prueffrage":"Wie lange häufen sich die Abweichungen schon, und was ist mit der Forscherin geschehen, die sie untersuchen wollte?","rueckmeldung":[{"option":1,"text":"Ein gemeinsamer Rahmen spart tatsächlich Aufwand, und Abweichungen sind oft Messfehler. Ohne Nachprüfung bleibt „Messfehler“ aber nur eine Vermutung, und Effizienz rechtfertigt es nicht, Kritik abzutun."},{"option":2,"text":"Die gehäuften Abweichungen verdienen Ernst, und das Verhalten ist problematisch. Widerlegt ist die Theorie damit aber nicht, denn geprüft wurde bisher nichts; erst die Prüfung zeigt, ob sie angepasst oder ersetzt werden muss."},{"option":3,"text":"Eine Tagung darf ihre Beiträge frei wählen, einen Anspruch auf Einladung gibt es nicht. Das Kernproblem liegt aber woanders: Die Daten werden ungeprüft abgetan, und daran ändert ein freies Einladungsrecht nichts."}],"familie":"weltsicht-sichtbar-machen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Bird, A.: Thomas Kuhn. Stanford Encyclopedia of Philosophy (überarb. 2025)","oeffentlich":true,"url":"https://plato.stanford.edu/entries/thomas-kuhn/","abruf":"2026-10-07"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"0156298f8ca82c38"}},{"id":"qx-a2-034","clusterId":"A","werkstueckRef":"A.20","stufe":4,"question":"Ein Anbieter wirbt für sein „neues Paradigma“ und sagt: „Wer zweifelt, ist noch im alten Denken gefangen.“ Wie bewertest du das?","options":["Als Warnzeichen: Eine Neuerung überzeugt durch bessere Erklärungen; der Satz macht den Anspruch gegen Kritik unangreifbar.","Als Fehlschluss aus der Mehrheit: Der Anbieter schließt von der Verbreitung seiner Idee auf deren Wahrheit.","Als überzeugend: Der Anbieter zeigt damit, welche Probleme das alte Modell hat und wie sein neues sie löst.","Als Hinweis auf Mut: Neue Ideen stoßen anfangs oft auf Ablehnung, und der Widerstand spricht eher für den Anbieter."],"correctIndex":0,"explanation":"Wer Zweifel als Zeichen von Befangenheit abwertet, macht seine Behauptung unprüfbar: Jeder Einwand wird zum Beweis, dass der Kritiker „es nicht verstanden hat“. Eine echte Neuerung in der Wissenschaft setzt sich anders durch: Sie erklärt Beobachtungen, an denen das Alte scheitert, und leistet dabei fast alles, was das Alte leistete. Selbst dann gehen manchmal einzelne Erklärungen verloren, aber nicht der Großteil des Bewährten. Entscheidend ist, ob eine Neuerung mehr erklärt und prüfbar ist. Der Satz nennt weder Probleme des alten Modells noch eine Lösung, er zeigt also nichts davon. Von Verbreitung oder Mehrheit ist darin keine Rede, der Vorwurf eines Mehrheitsschlusses läuft ins Leere. Dass Neues anfangs auf Widerstand stößt, stimmt oft, ist aber kein Gütezeichen: Auch Semmelweis’ Idee setzte sich erst später durch, als sie erklärt werden konnte.","coreRule":"⚡ Eine Neuerung überzeugt durch bessere Erklärungen, nicht dadurch, Kritik zu entwerten.","beleg":"Werkstück A.20 (Anwendung: Bei Pseudowissenschaften & Esoterik; Red Flags: „Kritik wird als Beweis dafür abgetan, dass der Kritiker noch im alten Paradigma gefangen ist“); Fn. ga-kuhn (Kuhn 1962; Bird, SEP „Thomas Kuhn“, Abschn. 2: Kuhn-loss)","status":"entwurf","kurz":"Wer Zweifel als Befangenheit abtut, macht seine Behauptung unprüfbar, denn jeder Einwand gilt dann als Beweis, dass der Kritiker nichts verstanden hat. Eine echte Neuerung überzeugt dagegen, weil sie mehr erklärt und sich prüfen lässt.","prueffrage":"Was erfährt man aus dem Satz des Anbieters über sein Produkt selbst, und was nur über die Zweifler?","rueckmeldung":[{"option":1,"text":"Vom Anbieter ist hier nur zu hören, wer zweifelt, sei befangen. Auf viele Anhänger oder weite Verbreitung beruft er sich nicht. Der Fehler liegt woanders: Kritik wird von vornherein entwertet, die Behauptung so unprüfbar."},{"option":2,"text":"Das klingt nach einem Argument, doch im Satz kommt weder ein Problem des alten Modells noch eine Lösung vor. Er zeigt also nichts davon. Eine echte Neuerung erklärt, woran das Alte scheitert, und bewahrt dabei fast alles Bewährte."},{"option":3,"text":"Dass Neues oft zuerst auf Widerstand stößt, stimmt. Widerstand ist aber kein Gütezeichen: Semmelweis setzte sich erst durch, als seine Idee erklärt werden konnte. Der Satz hier lässt gar keine Prüfung mehr zu."}],"familie":"weltsicht-sichtbar-machen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Bird, A.: Thomas Kuhn. Stanford Encyclopedia of Philosophy (überarb. 2025), Abschn. 2","oeffentlich":true,"url":"https://plato.stanford.edu/entries/thomas-kuhn/","abruf":"2026-10-07"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"ab5c95c0eaba9b1c"}},{"id":"qx-a2-035","clusterId":"A","werkstueckRef":"A.21","stufe":1,"question":"Du bekommst eine Wette angeboten: Münzwurf, bei Kopf gewinnst du 150 Euro, bei Zahl verlierst du 100 Euro. Du lehnst ab, obwohl du bei vielen Wiederholungen im Schnitt Geld gewinnen würdest. Wie lässt sich deine Ablehnung am besten erklären?","options":["Menschen scheuen Wetten mit unbekannten Gewinnchancen stärker als solche mit bekannten, obwohl der Durchschnitt hier positiv ist.","Ein Gewinn, der erst später käme, zählt weniger als ein Verlust jetzt (Gegenwartsverzerrung), obwohl der Durchschnitt positiv ist.","Menschen überschätzen kleine Wahrscheinlichkeiten, sodass dir der seltene Verlust größer erscheint, als er ist, obwohl der Durchschnitt positiv ist.","Ein möglicher Verlust von 100 Euro wiegt psychologisch schwerer als die Aussicht auf einen Gewinn von 150 Euro, obwohl der Durchschnitt positiv ist."],"correctIndex":3,"explanation":"Der Durchschnittswert der Wette liegt bei +25 Euro (0,5 × 150 − 0,5 × 100). Trotzdem lehnen die meisten Menschen ab, weil ein möglicher Verlust von 100 Euro stärker wiegt als ein gleich großer Gewinn. Das ist Verlustaversion, ein Kernstück der Prospect Theory von Kahneman und Tversky: Entschieden wird nicht über absolute Endzustände, sondern über Gewinne und Verluste relativ zu einem Referenzpunkt (dem, was man schon hat). In der Messung von 1992 zählte ein Verlust etwa doppelt so stark wie ein gleich hoher Gewinn. Die anderen Mechanismen gibt es durchaus, sie passen aber nicht zu dieser Wette: Bei einer fairen Münze sind die Chancen bekannt, es geht also nicht um unbekannte Wahrscheinlichkeiten. Sie sind mit 50 Prozent auch nicht klein, und Gewinn wie Verlust träten sofort ein, sodass auch keine zeitliche Gewichtung etwas erklärt.","coreRule":"⚡ Verluste und Gewinne wiegen nicht gleich: Ein Verlust zählt psychologisch etwa doppelt, deshalb lehnen wir auch Wetten mit positivem Durchschnitt ab.","beleg":"Werkstück A.21 (Einstiegsgeschichte; Kernidee); Fn. ga-prospect (Kahneman/Tversky 1979, Econometrica 47(2), S. 279; Tversky/Kahneman 1992, S. 311)","status":"entwurf","scenario":"Eine Freundin schlägt dir vor: „Wir werfen eine faire Münze. Bei Kopf zahle ich dir 150 Euro, bei Zahl zahlst du mir 100 Euro.“ Du merkst, dass du eigentlich keine Lust darauf hast, obwohl du nachrechnest, dass du im Durchschnitt 25 Euro pro Wurf gewinnen würdest.","kurz":"Der mögliche Verlust von 100 Euro wiegt psychologisch schwerer als der Gewinn von 150 Euro: Verlustaversion. Der Fehler liegt darin, nur den Durchschnitt von +25 Euro zu zählen, obwohl Verluste meist etwa doppelt so stark ins Gewicht fallen wie gleich hohe Gewinne.","prueffrage":"Was ergibt 0,5 × 150 − 0,5 × 100, und reicht dieses Ergebnis, damit du zusagst?","rueckmeldung":[{"option":0,"text":"Unsichere Wahrscheinlichkeiten schrecken tatsächlich oft ab. Hier sind die Chancen aber genau bekannt: Eine faire Münze ergibt 50 zu 50. Unbekanntes spielt in dieser Wette keine Rolle."},{"option":1,"text":"Dass Spätes weniger zählt als Sofortiges, kommt im Alltag oft vor. Hier träfen Gewinn und Verlust aber beide sofort nach dem Wurf ein, es gibt also keinen zeitlichen Unterschied, der etwas erklären könnte."},{"option":2,"text":"Kleine Wahrscheinlichkeiten werden tatsächlich oft überschätzt. Der Verlust hier tritt aber mit 50 Prozent ein, ist also weder selten noch klein. Dieser Mechanismus greift bei einer Münzwette nicht."}],"familie":"verlust-und-gewinn-abwaegen","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Kahneman, D. (2002): Maps of Bounded Rationality. Nobel Prize Lecture, nobelprize.org","oeffentlich":true,"url":"https://www.nobelprize.org/uploads/2018/06/kahnemann-lecture.pdf","seite":"461–462","abruf":"2026-10-12"},{"typ":"doi","kurz":"Tversky, A.; Kahneman, D. (1992): Advances in Prospect Theory: Cumulative Representation of Uncertainty. Journal of Risk and Uncertainty 5(4), 297–323","oeffentlich":false,"doi":"10.1007/BF00122574","seite":"311"}],"thema":"Geld und Zahlen","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"3f533ee1ed060148"}},{"id":"qx-a2-036","clusterId":"A","werkstueckRef":"A.21","stufe":2,"question":"Ein Anleger hat zwei Aktien: eine liegt 30 % im Plus, die andere 30 % im Minus. Er muss eine davon verkaufen und sagt: „Die Gewinneraktie nehme ich mit, die Verliererin behalte ich, die erholt sich schon wieder.“ Welche Erklärung für dieses Verhalten passt zu dem, was die Prospect Theory über Entscheidungen unter Unsicherheit beschreibt?","scenario":"Ein Anleger besitzt zwei Aktien: Die eine liegt 30 % im Plus, die andere 30 % im Minus. Er muss eine verkaufen und entscheidet sich für die Gewinneraktie. Die Verliereraktie behält er und sagt: „Die erholt sich schon wieder.“","options":["Er entscheidet nach dem erwarteten Endvermögen: Die Verliereraktie hat nach nüchterner Rechnung die besseren Aussichten, deshalb behält er sie und verkauft die Gewinneraktie.","Im Plus will er den sicheren Gewinn festhalten, im Minus wagt er lieber das Risiko eines noch größeren Verlusts, um die Chance auf Rückkehr zum Einstandskurs zu wahren.","Er überschätzt seine Fähigkeit, Kurse vorherzusagen (Selbstüberschätzung), und glaubt deshalb fest, gerade die Verliereraktie werde sich bald erholen.","Er folgt dem Herdentrieb: Er verkauft, was andere gerade verkaufen, und hält, was andere halten, ohne die Aussichten beider Aktien selbst zu vergleichen."],"correctIndex":1,"explanation":"Die Prospect Theory beschreibt ein asymmetrisches Risikoverhalten: Im Bereich der Gewinne bevorzugen Menschen den sicheren, kleineren Gewinn, im Bereich der Verluste nehmen sie lieber ein größeres Risiko in Kauf, um den Verlust vielleicht ganz zu vermeiden. Der Referenzpunkt ist dabei der Einstandskurs. Deshalb werden Gewinne oft zu früh realisiert und Verluste zu lange gehalten. Der Satz „die erholt sich schon wieder“ ist selbst ein Warnzeichen: Er begründet das Festhalten mit der Hoffnung, nicht mit einer Prüfung der Aussichten. Die klärende Frage lautet: „Würde ich diese Aktie heute zu diesem Kurs neu kaufen?“ Wenn nicht, spricht wenig fürs Halten. Wenn ja, ist das Halten begründet, aber dann nicht wegen des Verlusts. Die anderen Erklärungen beschreiben mögliche Einflüsse, passen aber nicht zur Prospect Theory: Reines Rechnen mit dem Endvermögen behandelt Gewinn und Verlust gleich, während die Prospect Theory gerade den Unterschied beschreibt. Selbstüberschätzung und Herdentrieb sind eigene Phänomene, die nicht erklären, warum der Anleger im Plus anders handelt als im Minus.","coreRule":"⚡ Gewinne sichern wir zu früh, Verluste halten wir zu lange.","beleg":"Werkstück A.21 (Kontext & Tiefe, Pfeiler 3; Anwendung: finanzielle Entscheidungen); Fn. ga-prospect-gewichtung (Kahneman/Tversky 1979, S. 268–269)","status":"entwurf","kurz":"Die Prospect Theory beschreibt, dass Menschen im Plus den sicheren Gewinn nehmen, im Minus aber ein größeres Risiko eingehen, um den Verlust noch zu vermeiden. „Die erholt sich schon wieder“ ist dann Hoffnung statt Prüfung.","prueffrage":"Was tut der Anleger mit der Gewinneraktie, was mit der Verliererin, und womit begründet er das Halten?","rueckmeldung":[{"option":0,"text":"Rechnen mit dem erwarteten Endvermögen klingt vernünftig. Es behandelt aber Gewinn und Verlust gleich, während die Prospect Theory gerade den Unterschied beschreibt. Im Szenario begründet er zudem nur mit Hoffnung, nicht mit nüchternen Aussichten."},{"option":2,"text":"Selbstüberschätzung kann Optimismus erklären und ist ein echtes Phänomen. Sie sagt aber nichts darüber, warum er im Plus anders handelt als im Minus, und genau diese Asymmetrie fragt die Aufgabe ab."},{"option":3,"text":"Herdentrieb gibt es, und er kann Kauf- und Verkaufsentscheidungen prägen. Im Szenario kommen aber keine anderen Anleger vor, und er erklärt nicht, warum Gewinne und Verluste unterschiedlich behandelt werden."}],"familie":"verlust-und-gewinn-abwaegen","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Kahneman, D. (2002): Maps of Bounded Rationality. Nobel Prize Lecture, nobelprize.org","oeffentlich":true,"url":"https://www.nobelprize.org/uploads/2018/06/kahnemann-lecture.pdf","seite":"461–462","abruf":"2026-10-12"},{"typ":"url","kurz":"Odean, T.: Are Investors Reluctant to Realize Their Losses? (Autorenseite, UC Berkeley)","oeffentlich":true,"url":"https://faculty.haas.berkeley.edu/odean/papers/disposition/disposition.html","abruf":"2026-10-12"},{"typ":"doi","kurz":"Kahneman, D.; Tversky, A. (1979): Prospect Theory: An Analysis of Decision under Risk. Econometrica 47(2), 263–291","oeffentlich":false,"doi":"10.2307/1914185","seite":"268"}],"thema":"Geld und Zahlen","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"e5e635a5e490cf4a"}},{"id":"qx-a2-037","clusterId":"A","werkstueckRef":"A.21","stufe":3,"question":"Was ist an der Aussage des Kollegen fehlerhaft?","scenario":"Eine Beraterin legt einem Kunden zwei Aufgaben vor. Aufgabe 1: Du erhältst zuerst 1.000 € und wählst dann zwischen A) garantiert weiteren 500 € und B) Münzwurf: bei Kopf weitere 1.000 €, bei Zahl nichts. Aufgabe 2: Du erhältst zuerst 2.000 € und wählst dann zwischen C) garantiert 500 € Verlust und D) Münzwurf: bei Kopf 1.000 € Verlust, bei Zahl nichts. In einem Test wählt die Mehrheit bei Aufgabe 1 die sichere Option A und bei Aufgabe 2 den Münzwurf D. Ein Kollege sagt: „Die Leute haben eben zwei unterschiedliche Situationen bewertet, das ist völlig vernünftig.“","options":["Er übersieht, dass A und C beide garantiert 1.500 € bedeuten und B und D beide im Schnitt 1.500 €; nur die Formulierung als Gewinn oder Verlust unterscheidet sich.","Er übersieht, dass in Aufgabe 2 das Anfangsguthaben höher ist, sodass die Endbeträge dort höher ausfallen und beide Aufgaben nicht dieselbe Lage beschreiben.","Er übersieht, dass der Erwartungswert von B höher ist als der von A, sodass die Wahl der sicheren Option A unvernünftig ist und mit der Wahl von D nichts zu tun hat.","Er übersieht, dass Menschen Münzwürfe meiden, weil sie Zufall ungern in Entscheidungen zulassen, und deshalb in beiden Aufgaben die sichere Option wählen müssten."],"correctIndex":0,"explanation":"Rechne die Endzustände durch: Bei A hast du garantiert 1.000 € + 500 € = 1.500 €, bei C garantiert 2.000 € − 500 € = 1.500 €. Bei B ergibt sich je zur Hälfte 2.000 € oder 1.000 €, bei D je zur Hälfte 1.000 € oder 2.000 €, also im Schnitt jeweils 1.500 €. Aufgabe 1 und Aufgabe 2 sind daher in der Sache identisch. Trotzdem wählen die meisten bei der Gewinnrahmung die sichere Option und bei der Verlustrahmung den Münzwurf. Das ist kein vernünftiger Unterschied in der Lage, sondern ein Rahmungseffekt: Wer von einem Referenzpunkt aus in Gewinnen denkt, meidet Risiko; wer in Verlusten denkt, geht es ein, um den sicheren Verlust zu vermeiden. Wäre die Wahl rein vom Endzustand bestimmt, müsste sie in beiden Aufgaben gleich ausfallen. Die anderen Einwände halten der Nachrechnung nicht stand: Das höhere Anfangsguthaben wird durch den Verlust genau ausgeglichen, und A und B haben denselben Erwartungswert. Wer Münzwürfe grundsätzlich meiden würde, hätte auch in Aufgabe 2 die sichere Option gewählt.","coreRule":"⚡ Gleiche Fakten, andere Rahmung: Prüfe zuerst die Endzustände. Ändert sich die Entscheidung nur durch die Formulierung als Gewinn oder Verlust, steuert der Referenzpunkt dein Risikoverhalten.","beleg":"Werkstück A.21 (Das Härten im Feuer: Die Schmiede-Übung; Red Flags)","status":"entwurf","kurz":"Rechnest du die Endzustände durch, sind beide Aufgaben identisch: sicher 1.500 € oder Münzwurf mit im Schnitt 1.500 €. Der Unterschied liegt nur in der Darstellung als Gewinn oder Verlust, und diese Rahmung lenkt die Wahl, obwohl die Lage dieselbe ist.","prueffrage":"Mit welchem Betrag gehst du in jeder der vier Varianten nach der Entscheidung nach Hause?","rueckmeldung":[{"option":1,"text":"Das Anfangsguthaben ist in Aufgabe 2 tatsächlich höher. Der angekündigte Verlust gleicht das aber genau aus, sodass du in beiden Aufgaben bei denselben Endbeträgen landest. Die Lage ist also keine andere."},{"option":2,"text":"Wer einen höheren Erwartungswert bei B vermutet, rechnet leicht falsch: A und B liegen im Schnitt beide bei 1.500 €. Die sichere Wahl ist daher nicht unvernünftig, und die Wahl von D hängt mit der von A zusammen, weil beide Aufgaben dieselbe Lage beschreiben."},{"option":3,"text":"Eine allgemeine Scheu vor Zufall würde auch in Aufgabe 2 zur sicheren Option führen. Die Mehrheit wählt dort aber den Münzwurf, das Muster folgt also der Rahmung und nicht einer festen Abneigung gegen Zufall."}],"familie":"rahmen-wechseln","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Kahneman, D. (2002): Maps of Bounded Rationality. Nobel Prize Lecture, nobelprize.org","oeffentlich":true,"url":"https://www.nobelprize.org/uploads/2018/06/kahnemann-lecture.pdf","seite":"461–463","abruf":"2026-10-12"},{"typ":"doi","kurz":"Kahneman, D.; Tversky, A. (1979): Prospect Theory: An Analysis of Decision under Risk. Econometrica 47(2), 263–291","oeffentlich":false,"doi":"10.2307/1914185","seite":"268"}],"thema":"Geld und Zahlen","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"17a3206678c481b8"}},{"id":"qx-a2-038","clusterId":"A","werkstueckRef":"A.21","stufe":4,"question":"Ein Marketingteam schlägt vor, den Slogan „Jetzt kaufen und 20 % sparen!“ durch „Verpass nicht die Chance, 20 % zu sparen!“ zu ersetzen. Begründung: Verluste wiegen psychologisch schwerer als gleich hohe Gewinne, also müsse der Verlust-Frame stärker wirken. Wie sicher darf man sich bei dieser Erwartung sein?","options":["Sehr sicher: Weil Verluste schwerer wiegen als Gewinne, muss jede Verlust-Botschaft stärker überzeugen als die Gewinn-Version.","Gar nicht sicher: Eine Theorie über Entscheidungen unter Risiko sagt über die Wirkung von Werbesätzen grundsätzlich nichts aus.","Eher unsicher: Gewinn- und Verlust-Frames bei Botschaften wurden bisher noch gar nicht systematisch miteinander verglichen.","Mäßig sicher: Die Erwartung ist plausibel, aber Vergleichsstudien zeigen meist nur kleine, uneinheitliche Unterschiede zwischen beiden Frames."],"correctIndex":3,"explanation":"Aus einer gut belegten Theorie über Entscheidungen unter Unsicherheit folgt nicht automatisch, dass ein bestimmter Werbesatz besser verkauft. Zwischen Theorie und Anwendung liegen viele Zwischenschritte: Wie nehmen Menschen die Botschaft wahr, wie viel Aufmerksamkeit schenken sie ihr, welche Alternativen haben sie? Eine Metaanalyse von O'Keefe und Jensen (2007) mit 93 Studien und 21.656 Teilnehmenden zu Botschaften über Krankheitsvorsorge, also nicht zu Werbung, fand sogar einen sehr kleinen Vorteil des Gewinn-Frames (r = 0,03). Das lässt sich nicht direkt auf Kaufverhalten übertragen, zeigt aber, dass Frame-Effekte klein und uneinheitlich sein können. Die Erwartung ist daher eine plausible Hypothese, keine gesicherte Wirkung; ob der Verlust-Frame beim eigenen Publikum wirkt, lässt sich nur messen, etwa mit einem Vergleichstest.","coreRule":"⚡ Was eine Theorie nahelegt, muss sich in der Praxis erst messen lassen.","beleg":"Werkstück A.21 (Anwendung: Im Marketing); Fn. ga-framing-persuasion (O'Keefe/Jensen 2007, Journal of Health Communication 12(7), S. 623–644)","status":"entwurf","scenario":"","kurz":"Aus einer gut belegten Theorie folgt nicht automatisch, dass ein bestimmter Werbesatz besser wirkt. Gewinn- und Verlustformulierungen von Botschaften unterschieden sich in Vergleichsstudien meist nur wenig; die Erwartung ist plausibel, aber eine Hypothese, die man testen muss.","prueffrage":"Was geschieht zwischen dem Lesen des Satzes und dem tatsächlichen Kauf, und wie ließe sich die Wirkung beim eigenen Publikum messen?","rueckmeldung":[{"option":0,"text":"Dass Verluste schwerer wiegen, ist gut belegt, und genau daher kommt die Sicherheit. Aus der Theorie folgt aber nicht, dass jeder Verlust-Satz besser verkauft; in Vergleichsstudien waren die Unterschiede meist klein und uneinheitlich."},{"option":1,"text":"Die Theorie allein sagt tatsächlich nicht vorher, wie ein Satz wirkt. Daraus folgt aber nicht, dass sie nichts aussagt: Sie liefert eine begründete Hypothese, die man prüfen kann."},{"option":2,"text":"Der Vergleich wurde durchaus untersucht, etwa in einer Metaanalyse mit 93 Studien. Die Unsicherheit entsteht nicht durch fehlende Forschung, sondern weil die Unterschiede dort klein und uneinheitlich ausfielen."}],"familie":"befund-reichweite","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"O’Keefe, D. J.; Jensen, J. D. (2007): The relative persuasiveness of gain-framed and loss-framed messages for encouraging disease prevention behaviors: a meta-analytic review. Journal of Health Communication 12(7), 623–644 (PubMed-Abstract)","oeffentlich":true,"url":"https://pubmed.ncbi.nlm.nih.gov/17934940/","abruf":"2026-10-12"},{"typ":"doi","kurz":"O’Keefe, D. J.; Jensen, J. D. (2007), Verlagsfassung","oeffentlich":false,"doi":"10.1080/10810730701615198"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"4cb3fffe29bfe8cf"}},{"id":"qx-a2-039","clusterId":"A","werkstueckRef":"A.22","stufe":1,"question":"Ein Video-Kommentar zu einer Termitenburg lautet: „So ein Bauwerk mit Belüftungsschächten und Kühlsystem braucht zwingend einen Gesamtplan. Irgendwo muss der gespeichert sein, sonst wäre das reiner Zufall.“ Was ist an dieser Schlussfolgerung fehlerhaft?","options":["Sie setzt voraus, dass komplexe Ordnung einen zentralen Plan braucht. Sie kann aber aus einfachen Regeln und Wechselwirkungen vieler Individuen entstehen, ohne dass irgendwo ein Gesamtplan existiert.","Sie verallgemeinert von einem einzelnen Bauwerk auf alle Termitenarten. Dabei kann jede Art anders bauen, sodass sich aus einem einzigen Beispiel kein allgemeiner Schluss auf einen Gesamtplan ziehen lässt.","Sie übersieht, dass der Gesamtplan im Erbgut jeder Termite gespeichert ist. Von dort wird er Schritt für Schritt in das Bauverhalten übersetzt, sodass jedes Tier den Plan in sich trägt.","Sie unterschätzt den Zufall. Das Bauwerk entsteht durch bloßes Aufhäufen von Material, ohne dass irgendwelche Regeln oder Wechselwirkungen der Tiere dahinterstehen müssten, und genau das erklärt seine Form."],"correctIndex":0,"explanation":"Der Schluss „komplexes Ergebnis, also muss es einen Plan geben“ ist ein Fehlschluss. Einzelne Tiere folgen simplen Regeln und kennen weder Belüftungsschacht noch Gesamtform. Erst das Zusammenspiel vieler Individuen erzeugt Strukturen auf der höheren Ebene, die man aus der Untersuchung eines einzelnen Tieres nicht vorhersagen könnte. Das nennt man Emergenz. Ein zentraler Plan ist dafür nicht nötig. Eine sinnvolle Gegenprobe ist die Frage, welche einfachen Regeln und Wechselwirkungen das Ergebnis erzeugen könnten. Die anderen Einwände klingen nach bekannten Denkfehlern oder Erklärungen, treffen aber nicht: Der Kommentar verallgemeinert nicht auf andere Arten, sondern spricht über dieses eine Bauwerk. Ein Plan im Erbgut widerspricht der Beschreibung, dass jedes Tier nur einfachen Reaktionsregeln folgt. Und reiner Zufall ist es auch nicht, denn die Regeln lenken das Tun der Tiere.","coreRule":"⚡ Komplexe Ordnung braucht keinen zentralen Plan: Sie kann aus den Beziehungen einfacher Teile entstehen.","beleg":"Werkstück A.22 (Einstiegsgeschichte; Kernidee)","status":"entwurf","scenario":"Eine Termitenkolonie besteht aus Tausenden Tieren. Jedes folgt nur einfachen Reaktionsregeln, etwa „Lege Material ab, wo schon Material liegt“ oder „Folge dem Duftsignal der Nachbarn“. Beobachtet wird: Das Gesamtbauwerk ist komplex und zweckmäßig, etwa mit Belüftung und Temperaturregelung.","kurz":"Aus einem komplexen Ergebnis folgt nicht, dass ein Gesamtplan existiert. Einfache Regeln vieler Tiere, die einander beeinflussen, können Schächte und Kühlung hervorbringen, obwohl keine Termite die Form kennt.","prueffrage":"Weiß eine einzelne Termite, wie der fertige Bau aussehen soll, und woran würdest du das erkennen?","rueckmeldung":[{"option":1,"text":"Verallgemeinerungen sind ein häufiger Denkfehler, hier greift er aber nicht: Der Kommentar spricht nur über dieses eine Bauwerk. Der Fehler liegt im Schluss vom komplexen Ergebnis auf einen Plan."},{"option":2,"text":"Wer „irgendwo muss der Plan gespeichert sein“ ernst nimmt, landet leicht beim Erbgut. Laut Szenario folgt aber jedes Tier nur einfachen Reaktionsregeln, einen Gesamtplan trägt keines in sich. Er wird nur an einen anderen Ort verlegt."},{"option":3,"text":"Dass es keinen Gesamtplan braucht, stimmt. Falsch ist aber, dass keine Regeln dahinterstehen: Die Tiere folgen festen Reaktionsregeln, die ihr Tun lenken. Reiner Zufall wäre es daher nicht."}],"familie":"auslese-statt-plan","fertigkeit":"F1","quellen":[{"typ":"doi","kurz":"Calovi, D. S. u. a. (2019): Surface curvature guides early construction activity in mound-building termites. Phil. Trans. R. Soc. B 374","oeffentlich":true,"doi":"10.1098/rstb.2018.0374","abruf":"2026-10-12"},{"typ":"url","kurz":"O'Connor, T.: Emergent Properties. Stanford Encyclopedia of Philosophy","oeffentlich":true,"url":"https://plato.stanford.edu/entries/properties-emergent/","abruf":"2026-10-12"},{"typ":"url","kurz":"Reynolds, C. W.: Boids (Background and Update), red3d.com","oeffentlich":true,"url":"https://www.red3d.com/cwr/boids/","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"fc7521197762daec"}},{"id":"qx-a2-040","clusterId":"A","werkstueckRef":"A.22","stufe":2,"question":"Ein Redner sagt: „Wasser ist nass, obwohl weder Wasserstoff noch Sauerstoff nass sind. Das beweist, dass man nichts verstehen kann, wenn man nur die Einzelteile untersucht.“ Wo liegt der Fehler in dieser Schlussfolgerung?","options":["Er begeht einen Zusammensetzungsfehlschluss: Er überträgt die Eigenschaften der Teile ungeprüft auf das Ganze, obwohl beides verschieden sein kann.","Er geht zu weit: Dass sich eine Eigenschaft nicht aus den Einzelteilen allein ablesen lässt, heißt nicht, dass die Einzelteile unwichtig sind.","Er benutzt „nass“ in zwei Bedeutungen: einmal für einzelne Moleküle, einmal für den Stoff Wasser, sodass der Schluss auf einer Mehrdeutigkeit beruht.","Er unterschätzt, dass sich Eigenschaften wie Nässe mit genügend Rechenleistung exakt aus einem einzelnen Molekül vorhersagen lassen."],"correctIndex":1,"explanation":"Die Beobachtung stimmt: Wasserstoff ist ein brennbares Gas, Sauerstoff nährt Feuer, aber Wasser ist flüssig, hat Oberflächenspannung und macht Dinge nass. Ein einzelnes H₂O-Molekül ist nicht nass; die Eigenschaft zeigt sich erst im Zusammenspiel unzähliger Moleküle, die über Wasserstoffbrücken aneinander haften. Der Fehler liegt im Sprung von „nicht an einem einzelnen Teil ablesbar“ zu „Teile untersuchen bringt nichts“. Gerade die Kräfte zwischen den Molekülen erklären, warum Wasser Tropfen bildet und Oberflächen benetzt: Nässe widerspricht der Chemie nicht, sie baut auf ihr auf. Wer verstehen will, muss also die Teile und ihr Zusammenspiel untersuchen, nicht das eine statt des anderen. Die anderen Einwände nennen bekannte Fehlerquellen, treffen aber nicht: Der Redner schließt nicht von den Teilen auf das Ganze, er betont ja gerade den Unterschied. Er verwendet „nass“ durchgehend im selben Sinn. Und Nässe lässt sich aus einem einzelnen Molekül nicht ablesen, so viel man auch rechnet.","coreRule":"⚡ Eine emergente Eigenschaft steckt in den Beziehungen der Teile, nicht in den Teilen selbst, und sie baut auf den Gesetzen der Teile auf, statt ihnen zu widersprechen.","beleg":"Werkstück A.22 (Einstiegsgeschichte, Das Wasser; Anti-Denkmuster: Konsistenz)","status":"entwurf","scenario":"","kurz":"Der Redner springt von „am einzelnen Teil nicht ablesbar“ zu „Teile untersuchen bringt nichts“. Dabei erklären gerade die Kräfte zwischen den Molekülen, warum Wasser nass ist: Teile und Zusammenspiel gehören zusammen.","prueffrage":"Woher stammt das heutige Wissen darüber, warum Wasser Tropfen bildet und Oberflächen benetzt?","rueckmeldung":[{"option":0,"text":"Ein Fehlschluss von Teilen aufs Ganze würde voraussetzen, dass der Redner beides gleichsetzt. Er betont aber gerade, dass das Ganze Eigenschaften hat, die die Teile nicht haben. Sein Fehler liegt woanders: im Schluss auf die Nutzlosigkeit der Teile."},{"option":2,"text":"Mehrdeutigkeit ist eine häufige Fehlerquelle, hier aber nicht im Spiel: „Nass“ meint durchgehend dasselbe, nämlich die Eigenschaft, Oberflächen zu benetzen. Dass ein einzelnes Molekül sie nicht zeigt, ist die Beobachtung selbst, kein Bedeutungswechsel."},{"option":3,"text":"Das trifft nicht zu: Nässe lässt sich aus einem einzelnen Molekül nicht ablesen, so viel man auch rechnet. Sie entsteht erst im Zusammenspiel unzähliger Moleküle. Genau das stimmt am Beispiel des Redners; falsch ist erst sein Schluss daraus."}],"familie":"auslese-statt-plan","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"USGS Water Science School: Adhesion and Cohesion Water","oeffentlich":true,"url":"https://www.usgs.gov/special-topics/water-science-school/science/adhesion-and-cohesion-water","abruf":"2026-10-12"},{"typ":"url","kurz":"USGS Water Science School: Surface Tension and Water","oeffentlich":true,"url":"https://www.usgs.gov/special-topics/water-science-school/science/surface-tension-and-water","abruf":"2026-10-12"},{"typ":"url","kurz":"O'Connor, T.: Emergent Properties. Stanford Encyclopedia of Philosophy","oeffentlich":true,"url":"https://plato.stanford.edu/entries/properties-emergent/","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"4537c96377be82b7"}},{"id":"qx-a2-041","clusterId":"A","werkstueckRef":"A.22","stufe":3,"question":"Du hörst in einer Diskussion diese Erklärung: „Wie die Methode wirkt? Das ist eine emergente Eigenschaft des Quantenfeldes.“ Was ist an dieser Antwort der entscheidende Schwachpunkt?","options":["Die Antwort benennt keinen Mechanismus: Es bleibt offen, welche Wechselwirkungen welcher Teile die behauptete Wirkung erzeugen sollen.","Die Antwort ist zu fachsprachlich gehalten; sobald sie in Alltagssprache formuliert wäre, wäre die Behauptung überprüfbar und damit belegt.","Die Antwort setzt voraus, dass Emergenz nur in lebenden Systemen vorkommt, während Felder und Teilchen nie neue Eigenschaften zeigen.","Die Antwort scheitert, weil sich emergente Eigenschaften grundsätzlich nicht erklären lassen und jede Erklärung deshalb unzulässig ist."],"correctIndex":0,"explanation":"Emergenz beschreibt nur, dass auf einer höheren Ebene Eigenschaften auftauchen, die einzelne Teile nicht zeigen. Sie erklärt nichts, solange offen bleibt, wie das geschieht. Ein Verkehrsforscher kann die Regeln nennen, nach denen aus dem Verhalten einzelner Fahrer ein Stau entsteht. Wer dagegen nur sagt „Das ist emergent“, ersetzt den Mechanismus durch ein Etikett und beendet die Diskussion, statt sie zu beginnen. Prüffragen: Welche Interaktionen zwischen welchen Komponenten erzeugen die Wirkung? Und widerspricht sie bekannten physikalischen Gesetzen? Echte Emergenz baut auf den Gesetzen der unteren Ebene auf und bricht sie nicht.","coreRule":"⚡ „Es ist emergent“ ist keine Erklärung, solange kein Mechanismus benannt wird.","quote":"Das ist eine emergente Eigenschaft des Quantenfeldes.","quoteLabel":"Beispielantwort:","beleg":"Werkstück A.22 (Anwendung: Pseudowissenschaftlicher Missbrauch; Der Kipppunkt; Aktivierungs-Frage 1)","status":"entwurf","scenario":"Eine Anbieterin von „Energieheilung“ wird gefragt, wie ihre Methode funktioniert. Sie antwortet: „Das ist eine emergente Eigenschaft des Quantenfeldes.“ Danach geht das Gespräch zu einem anderen Thema über.","kurz":"„Emergent“ besagt nur, dass auf höherer Ebene neue Eigenschaften auftreten, nicht wie. Ohne Angabe, welche Wechselwirkungen welcher Teile die Wirkung erzeugen, ersetzt das Etikett den Mechanismus und beendet die Diskussion.","prueffrage":"Was sagt die Anbieterin nach diesem Satz noch über ihre Methode, und was weiß man danach mehr als vorher?","rueckmeldung":[{"option":1,"text":"Fachwörter können Leere tatsächlich verdecken. Einfachere Sprache macht eine Behauptung aber noch nicht überprüfbar, geschweige denn belegt; dafür bräuchte es einen benannten Mechanismus, und genau der fehlt."},{"option":2,"text":"Emergenz ist nicht auf Lebewesen beschränkt, auch die Nässe von Wasser entsteht erst aus dem Zusammenspiel vieler Teilchen. Zudem setzt der Satz das gar nicht voraus: Er schreibt die Emergenz ja einem Quantenfeld zu."},{"option":3,"text":"Emergente Eigenschaften lassen sich oft gut erklären, etwa über die Regeln, nach denen einzelne Fahrer einen Stau erzeugen. Nicht das Erklären ist unzulässig, sondern das bloße Etikett „emergent“ ohne jede Erklärung."}],"familie":"mechanismus-verlangen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Craver, C.; Tabery, J.; Illari, P.: Mechanisms in Science. Stanford Encyclopedia of Philosophy","oeffentlich":true,"url":"https://plato.stanford.edu/entries/science-mechanisms/","abruf":"2026-10-12"},{"typ":"url","kurz":"O'Connor, T.: Emergent Properties. Stanford Encyclopedia of Philosophy","oeffentlich":true,"url":"https://plato.stanford.edu/entries/properties-emergent/","abruf":"2026-10-12"},{"typ":"url","kurz":"Reynolds, C. W.: Boids (Background and Update), red3d.com","oeffentlich":true,"url":"https://www.red3d.com/cwr/boids/","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"66ad8cabbb2bfd50"}},{"id":"qx-a2-042","clusterId":"A","werkstueckRef":"A.22","stufe":4,"question":"Ein Anbieter erklärt, sein „energetisiertes“ Wasser heile Beschwerden. Auf die Rückfrage nach dem Wirkmechanismus sagt er: „Das ist eine emergente Eigenschaft des Wassers, die man nicht auf einzelne Moleküle zurückführen kann.“ Welche Rückfrage prüft diese Behauptung am besten?","options":["Welche Wechselwirkungen zwischen welchen Bestandteilen sollen diese Eigenschaft erzeugen, und passt sie zu den bekannten Gesetzen der Physik?","Wie viele Kundinnen und Kunden haben das Wasser schon gekauft, und wie zufrieden äußern sie sich im Nachhinein über die Wirkung?","Welche anerkannten Fachleute haben das Wort „emergent“ schon in einem ähnlichen Zusammenhang verwendet, und wie wurde es dort gebraucht?","Lässt sich die behauptete Wirkung durch eine genaue Untersuchung eines einzelnen Wassermoleküls vorhersagen, und wie genau müsste man dazu messen?"],"correctIndex":0,"explanation":"Das Wort „emergent“ beschreibt nur, dass auf höherer Ebene etwas Neues entsteht; es erklärt nichts. Seriöse Forschung fragt deshalb nach den Interaktionen, die eine emergente Eigenschaft erzeugen. Nässe ist ein Beispiel: Sie entsteht aus dem Zusammenspiel unzähliger Wassermoleküle und ihrer Wasserstoffbrückenbindungen und widerspricht der Chemie nicht. Ein Verkehrsforscher kann die Regeln nennen, aus denen ein Stau entsteht. Wer „Emergenz“ ruft, aber keinen Mechanismus nennen kann oder ein Phänomen behauptet, das bekannten Gesetzen widerspricht, benutzt das Wort als Diskussionsende statt als Forschungsfrage. Die Rückfrage nach Mechanismus und Vereinbarkeit mit den Gesetzen trennt beides. Die anderen Fragen sind in anderer Lage sinnvoll, klären hier aber nichts: Kundenzahl und Zufriedenheit sagen nichts über den Mechanismus. Dass andere das Wort benutzen, beweist nichts. Und weil emergente Eigenschaften gerade nicht aus einer einzelnen Komponente ablesbar sind, wäre die Untersuchung eines einzelnen Moleküls der falsche Test.","coreRule":"⚡ „Emergent“ ist eine Beschreibung, keine Erklärung: Verlange den Mechanismus und prüfe, ob er den bekannten Gesetzen widerspricht.","beleg":"Werkstück A.22 (Red Flags; Anti-Denkmuster, Aktivierungs-Frage 2)","status":"entwurf","scenario":"","kurz":"„Emergent“ benennt nur, dass auf höherer Ebene etwas Neues entsteht, und erklärt nichts. Prüfen lässt sich die Behauptung, indem man die Wechselwirkungen verlangt, die es erzeugen sollen, und fragt, ob sie zu bekannten Gesetzen passt.","prueffrage":"Was genau müsste im Wasser anders sein, damit sich ein Unterschied zu gewöhnlichem Wasser nachweisen ließe?","rueckmeldung":[{"option":1,"text":"Viele zufriedene Kunden wirken wie ein Beleg, zeigen aber nur, dass das Wasser gekauft und gelobt wird. Über den Wirkmechanismus sagt das nichts, und zufriedene Rückmeldungen lassen sich auch durch bloße Erwartung erklären."},{"option":2,"text":"Das Wort „emergent“ ist in der Wissenschaft tatsächlich gebräuchlich, und ein Blick darauf, wie andere es verwenden, kann nützlich sein. Ob der Anbieter einen Mechanismus nennen kann, klärt das aber nicht: Fachleute mit demselben Wort sind kein Beleg."},{"option":3,"text":"Der Test klingt streng, setzt aber falsch an. Emergente Eigenschaften zeigen sich gerade nicht an einer einzelnen Komponente, auch Nässe lässt sich an einem einzigen Molekül nicht ablesen. Ein negatives Ergebnis würde deshalb nichts widerlegen."}],"familie":"mechanismus-verlangen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Craver, C.; Tabery, J.; Illari, P.: Mechanisms in Science. Stanford Encyclopedia of Philosophy","oeffentlich":true,"url":"https://plato.stanford.edu/entries/science-mechanisms/","abruf":"2026-10-12"},{"typ":"url","kurz":"O'Connor, T.: Emergent Properties. Stanford Encyclopedia of Philosophy","oeffentlich":true,"url":"https://plato.stanford.edu/entries/properties-emergent/","abruf":"2026-10-12"},{"typ":"url","kurz":"USGS Water Science School: Adhesion and Cohesion Water","oeffentlich":true,"url":"https://www.usgs.gov/special-topics/water-science-school/science/adhesion-and-cohesion-water","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"309acd713a9d885f"}},{"id":"qx-a2-043","clusterId":"A","werkstueckRef":"A.23","stufe":1,"question":"Eine Analystin sagt über diese Aktie: „Der Kurs steigt seit Wochen gleichmäßig, jede Woche um etwa zwei Prozent. Das System ist stabil, also wird das noch lange so weitergehen.“ Welche Frage prüft am besten, ob dieses System kurz vor einem Umschlag stehen könnte?","options":["Wie stark schwankt der Kurs im Vergleich zu den Wochen davor, und wie schnell erholt er sich von kleinen Rückschlägen?","Wer treibt im Forum die Stimmung an, und verdient diese Person daran, wenn weitere Anleger die Aktie kaufen?","Wie wahrscheinlich ist es, dass ein so gleichmäßiger Anstieg allein durch Zufall entsteht, und wie sicher ist der Trend?","Welche Nachricht aus dem Unternehmen erklärt den Anstieg, und lässt sich diese Nachricht aus einer unabhängigen Quelle bestätigen?"],"correctIndex":0,"explanation":"Ein stetiger Anstieg beweist keine Stabilität: Systeme verändern sich oft lange gleichmäßig und kippen dann in einem Sprung, wie ein Glas, das zentimeterweise über den Tisch geschoben wird, bis die Kante erreicht ist. Die Schilderung zeigt typische Zutaten: Ein verstärkender Motor läuft (die Angst, etwas zu verpassen, treibt neue Käufer an), die Bremsen versagen (Gegenstimmen werden ausgegrenzt) und die Spannung wächst (Kredite machen das System anfällig). Wie nah die Kante ist, zeigt sich aber am besten am Verhalten des Systems selbst: Nahe an einem Umschlag erholt es sich oft langsamer von kleinen Störungen, und die Schwankungen nehmen zu. Schwankung und Erholung verraten allerdings nicht, wann das System kippt, und sie können Fehlalarm geben. Ein Blick auf die Interessen hinter der Stimmung ist ein guter Quellencheck, sagt aber nichts über die Nähe zum Umschlag. Ob ein so gleichmäßiger Anstieg Zufall sein könnte, ist hier nicht die Frage, denn es geht um die Stabilität eines Anstiegs, der schon wochenlang sichtbar ist. Und eine Nachricht, die den Anstieg erklärt, klärt seine Ursache, aber nicht, wie nah die Kante ist.","coreRule":"⚡ Stetig heißt nicht stabil: Frag nach Motoren, Bremsen und Spannung, und beobachte, wie schnell sich das System von kleinen Störungen erholt.","beleg":"Werkstück A.23 (Kontext & Tiefe: Indikatoren 1 bis 3)","status":"entwurf","scenario":"Im Chat eines Anlegerforums zu einer bestimmten Aktie wächst die Zahl der Beiträge, in denen Leute schreiben, sie wollten „auf keinen Fall den Zug verpassen“. Kritische Stimmen werden dort ausgelacht oder gesperrt. Viele Mitglieder haben Kredite aufgenommen, um zu kaufen.","quote":"","quoteLabel":"","kurz":"Ein gleichmäßiger Anstieg beweist keine Stabilität: Systeme driften oft lange stetig und kippen dann abrupt. Nahe an einem Umschlag erholt sich das System oft langsamer von kleinen Störungen, und die Schwankungen nehmen zu. Das zeigt sich am Kursverhalten selbst.","prueffrage":"Was weiß die Analystin über den Kursverlauf, außer dass er im Durchschnitt zwei Prozent pro Woche steigt?","rueckmeldung":[{"option":1,"text":"Wer die Stimmung antreibt und davon profitiert, ist ein guter Quellencheck für die Beiträge im Forum. Er sagt aber nichts darüber, wie nah das System an einem Umschlag ist, und die Stabilität des Anstiegs bleibt offen."},{"option":2,"text":"Ob ein so gleichmäßiger Anstieg Zufall sein könnte, ist hier nicht die Frage: Der Anstieg ist seit Wochen sichtbar. Gefragt ist, wie stabil er ist, und das sagt eine Zufallsabschätzung nicht."},{"option":3,"text":"Eine bestätigte Nachricht erklärt, warum der Kurs steigt, und das ist eine sinnvolle Prüfung. Sie sagt aber nicht, wie nah die Kante ist: Auch ein gut begründeter Anstieg kann kippen."}],"familie":"systemisch-denken","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Dakos, V. (2011): Expecting the Unexpected. Indicators of Resilience as Early-Warning Signals for Critical Transitions. Diss. Wageningen University (Kap. 2 = Scheffer u. a. 2009)","oeffentlich":true,"url":"https://edepot.wur.nl/168815","seite":"31","abruf":"2026-10-12"},{"typ":"url","kurz":"Scheffer, M. u. a. (2009): Early-warning signals for critical transitions. Nature 461, 53–59 (Abstract)","oeffentlich":true,"doi":"10.1038/nature08227","url":"https://pubmed.ncbi.nlm.nih.gov/19727193/","abruf":"2026-10-12"},{"typ":"url","kurz":"Meadows, D.: Leverage Points: Places to Intervene in a System. Donella Meadows Project","oeffentlich":true,"url":"https://donellameadows.org/archives/leverage-points-places-to-intervene-in-a-system/","abruf":"2026-10-12"}],"thema":"Geld und Zahlen","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"da449990f4076d66"}},{"id":"qx-a2-044","clusterId":"A","werkstueckRef":"A.23","stufe":2,"question":"Was übersieht die Nutzerin, wenn man den Wandel der Gruppe als instabiler werdendes System betrachtet?","scenario":"In einer Nachbarschaftsgruppe fielen früher Gerüchte schnell in sich zusammen, weil ein paar besonnene Leute sie einordneten. Die sind inzwischen ausgetreten. Seitdem schaukelt sich der Ton bei jedem Gerücht rasch hoch. Eine Nutzerin sagt: „Das Problem sind nur die Gerüchte selbst. Wenn die nicht wären, wäre alles ruhig.“","options":["Dass sich Gerüchte in großen Gruppen im Schnitt schneller verbreiten als in kleinen Gruppen.","Dass die besonnene Einordnung weggefallen ist, die solche Aufschaukelungen früher gedämpft hat.","Dass ein Gerücht umso glaubwürdiger wirkt, je häufiger man es liest (Wahrheitseffekt der Wiederholung).","Dass Gerüchte, die Ängste ansprechen, sich leichter verbreiten als Gerüchte ohne emotionalen Gehalt."],"correctIndex":1,"explanation":"Gerüchte gab es in der Gruppe schon vorher. Geändert hat sich vor allem, dass eine ausgleichende Schleife weggefallen ist: Die besonnene Einordnung wirkte als Bremse, die hitzige Reaktionen abgefangen hat. Systeme kippen oft dann, wenn solche Bremsen überlastet, ausgehebelt oder entfernt werden, etwa wenn Normen, Gesetze oder Peer Review wegfallen. Wer nur auf den Auslöser schaut, sieht nur den Funken und übersieht die fehlende Bremse; deshalb lohnt es sich, nicht nur nach den Antrieben zu fragen, sondern auch nach den Bremsen. Dass sich Gerüchte in großen Gruppen schneller verbreiten, stimmt im Schnitt, doch von einem Wachstum der Gruppe ist hier keine Rede. Dass Wiederholung ein Gerücht glaubwürdiger wirken lässt, ist ebenfalls richtig, erklärt aber nicht, warum der Ton erst nach dem Weggang der Besonnenen kippt. Und Gerüchte, die Ängste ansprechen, verbreiten sich leichter, doch Gerüchte gab es auch früher, ohne dass sich der Ton aufschaukelte.","coreRule":"⚡ Frag nicht nur, was antreibt, sondern auch, welche Bremse fehlt.","beleg":"Werkstück A.23 (Kontext & Tiefe: Indikator 2)","status":"entwurf","kurz":"Geändert hat sich nicht, dass es Gerüchte gibt, sondern dass die Bremse fehlt: Die besonnene Einordnung hat Aufschaukelungen früher abgefangen. Wer nur auf den Auslöser schaut, sieht den Funken und übersieht, was ihn nicht mehr löscht.","prueffrage":"Gab es in der Gruppe auch früher schon Gerüchte, und wie lange hielten sie sich damals?","rueckmeldung":[{"option":0,"text":"Im Schnitt verbreiten sich Gerüchte in großen Gruppen tatsächlich schneller. Von einer wachsenden Gruppe ist hier aber keine Rede, und der Ton kippt erst nach dem Weggang der Besonnenen."},{"option":2,"text":"Wiederholung kann ein Gerücht glaubwürdiger wirken lassen, das stimmt. Diesen Effekt gab es aber auch früher, als Gerüchte rasch in sich zusammenfielen. Er erklärt also nicht, was sich verändert hat."},{"option":3,"text":"Gerüchte, die Ängste ansprechen, verbreiten sich meist leichter. Doch Gerüchte gab es in der Gruppe schon immer, ohne dass sich der Ton aufschaukelte. Der Unterschied liegt woanders als im Inhalt der Gerüchte."}],"familie":"systemisch-denken","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Meadows, D.: Leverage Points: Places to Intervene in a System. Donella Meadows Project","oeffentlich":true,"url":"https://donellameadows.org/archives/leverage-points-places-to-intervene-in-a-system/","abruf":"2026-10-12"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"b7b315891104bf78"}},{"id":"qx-a2-045","clusterId":"A","werkstueckRef":"A.23","stufe":3,"question":"Eine Analystin hat gelernt, nach verstärkenden Rückkopplungen, versagenden Bremsen und aufgestauter Spannung zu suchen. Sie sieht inzwischen in jedem Kursausschlag, jedem Streit im Team und jedem Ausreißer in einer Statistik den Beginn eines Zusammenbruchs. Was ist an ihrem Vorgehen das Problem?","options":["Sie deutet gewöhnliche Schwankungen als Vorboten eines Zusammenbruchs und macht ihre Warnungen so durch keine Beobachtung mehr widerlegbar.","Sie verwechselt Korrelation und Ursache: Dass Spannung und Zusammenbruch gemeinsam auftreten, heißt nicht, dass die Spannung ihn verursacht.","Sie wendet das Raster auf Systeme an, die schon gekippt sind, und sucht damit rückblickend nach Ursachen statt nach künftigen Entwicklungen.","Sie lässt sich von auffälligen früheren Zusammenbrüchen leiten, die leichter in den Sinn kommen als unauffällige Fälle (Verfügbarkeitsheuristik)."],"correctIndex":0,"explanation":"Ein Denkwerkzeug wird unbrauchbar, wenn es überall anschlägt. Wer harmlose Schwankungen als Beweis für den nahenden Zusammenbruch liest, erkennt Muster im Rauschen (Apophenie). Ihr Satz „Das zeigt nur, wie knapp es war“ macht die Behauptung zusätzlich unwiderlegbar: Tritt der Kollaps ein, hatte sie recht, tritt er nicht ein, war es eben knapp. Eine Behauptung, die durch kein Ergebnis widerlegt werden kann, sagt nichts mehr aus. Dazu kommt: Auch seriöse Frühwarnsignale zeigen nur, dass ein System näher an die Kante rückt, nicht wann es kippt, und sie schlagen mitunter falschen Alarm. Brauchbar ist das Raster deshalb zur Beschreibung der Dynamik hinter einer Entwicklung (Motoren, Bremsen, Spannung, möglicher Auslöser), nicht als Prophezeiung. Eine Verwechslung von Korrelation und Ursache liegt nicht vor, denn sie behauptet keinen Kausalzusammenhang aus Beobachtungen, sondern warnt vor einem Verlauf. Rückblickend sucht sie ebenfalls nicht, denn bisher ist gar kein Zusammenbruch eingetreten. Und sie folgt einem festen Raster, nicht den Erinnerungen an spektakuläre Fälle.","coreRule":"⚡ Ein Prüfraster zeigt Architektur, keine Prophezeiung: Wer überall Kipppunkte sieht und jedes Ausbleiben als „knapp“ umdeutet, sieht Muster im Rauschen.","beleg":"Werkstück A.23 (Der Kipppunkt (Von der Nützlichkeit zur Gefahr); Red Flags: Langsameres Zurückfedern); Fn. ga-fruehwarnung (Scheffer u. a. 2009, Nature 461, S. 53–59) und Fn. ga-fruehsignale (Scheffer u. a. 2009, S. 54–58; Dakos 2011, S. 17–32)","status":"entwurf","scenario":"Eine Analystin nutzt ein Prüfraster für Kipppunkte. Sie fragt: Wo verstärkt sich etwas selbst? Welche Bremsen versagen? Wie viel Spannung hat sich aufgestaut? Seit sie damit arbeitet, warnt sie fast wöchentlich vor einem bevorstehenden Kollaps, ob bei Aktienkursen, Teamstimmung oder Kundenzahlen. Bisher ist keine ihrer Warnungen eingetreten, aber sie sagt: „Das zeigt nur, wie knapp es jedes Mal war.“","kurz":"Wer in jeder gewöhnlichen Schwankung einen nahenden Zusammenbruch sieht, liest Muster ins Rauschen. Mit „Es war nur knapp“ ist die Warnung zudem durch nichts mehr zu widerlegen und sagt damit nichts mehr aus.","prueffrage":"Wie viele ihrer Warnungen sind bisher eingetreten, und wie erklärt die Analystin die übrigen?","rueckmeldung":[{"option":1,"text":"Spannung und Zusammenbruch gemeinsam zu betrachten, ruft schnell diesen Einwand auf. Die Analystin schließt aber nichts aus beobachteten Zusammenhängen auf eine Ursache, sondern sagt einen Verlauf voraus, und der ist durch kein Ergebnis mehr zu widerlegen."},{"option":2,"text":"Rückblickendes Ursachensuchen ist ein bekannter Fehler, passt hier aber nicht: Bisher ist gar kein Zusammenbruch eingetreten, den sie erklären könnte. Ihre Warnungen blicken nach vorn, sind aber gegen jede Widerlegung abgedichtet."},{"option":3,"text":"Spektakuläre Fälle prägen sich tatsächlich leichter ein. Die Analystin geht aber nach einem festen Raster vor, nicht nach Erinnerungen. Ihr Problem ist, dass dieses Raster überall anschlägt und ihr Satz „Es war nur knapp“ jede Widerlegung ausschließt."}],"familie":"muster-im-zufall","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Dakos, V. (2011): Expecting the Unexpected. Indicators of Resilience as Early-Warning Signals for Critical Transitions. Diss. Wageningen University","oeffentlich":true,"url":"https://edepot.wur.nl/168815","seite":"31","abruf":"2026-10-12"},{"typ":"url","kurz":"Thornton, S.: Karl Popper. Stanford Encyclopedia of Philosophy","oeffentlich":true,"url":"https://plato.stanford.edu/entries/popper/","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"4f09c5eac393a3eb"}},{"id":"qx-a2-046","clusterId":"A","werkstueckRef":"A.23","stufe":4,"question":"Ein Team beobachtet über Monate ein Ökosystem. Die Messwerte zeigen: Nach kleinen Störungen erholt es sich immer langsamer, die Schwankungen werden größer, und jeder Zustand gleicht stärker dem vorigen. Eine Kollegin sagt: „Dann kippt das System in den nächsten Wochen, das ist jetzt sicher.“ Was ist die beste Einschätzung?","options":["Die Signale sprechen dafür, dass die Kante näher rückt, doch ob und wann das System kippt, sagen sie nicht verlässlich voraus.","Die Signale lassen für sich genommen keinen Schluss auf die Ursache zu, also darf man aus ihnen noch nichts über das System folgern.","Die Signale zeigen, dass das System schon gekippt ist, denn ein System, das sich nur noch langsam erholt, steckt bereits im neuen Zustand.","Die Signale sind bei Ökosystemen normal, denn jedes System schwankt nach Störungen mal stärker, mal schwächer; eine Warnung ergibt sich daraus nicht."],"correctIndex":0,"explanation":"Wenn sich ein System nahe einer Schwelle langsamer von kleinen Störungen erholt, stärker schwankt und jeder Zustand dem vorigen ähnlicher wird, rückt die Kante näher. Das ist ein allgemeines Muster, das in Modellen, in Klimadaten der Erdgeschichte, bei befischten Beständen und vor epileptischen Anfällen gefunden wurde. Es sagt aber nur etwas über die Nähe, nicht über den Zeitpunkt: Solche Signale schlagen mitunter falschen Alarm oder bleiben vor einem echten Umbruch stumm. Die Kollegin schließt also zu viel aus einem Warnsignal. Ein Anlass, genauer hinzusehen und Vorsorge zu treffen, ist es, aber keine Prognose mit Datum. Dass sich aus Messwerten allein keine Ursache ablesen lässt, stimmt, doch die Signale zeigen die Nähe zur Schwelle unabhängig davon, woher die Störungen kommen. Dass das System schon gekippt sei, widerspricht den Messwerten, denn es erholt sich ja noch, nur langsamer. Und Schwankungen an sich sind normal, doch drei gleichgerichtete Veränderungen über Monate sind mehr als bloßes Rauschen.","coreRule":"⚡ Frühwarnsignale zeigen die Nähe der Kante, nicht den Zeitpunkt des Sturzes.","beleg":"Werkstück A.23 (Red Flags: Langsameres Zurückfedern); Fn. ga-fruehsignale (Scheffer u. a. 2009, Nature 461(7260), S. 53–59, nach Dakos 2011, S. 21, 24, 27–29, 31)","status":"entwurf","scenario":"","kurz":"Langsamere Erholung, größere Schwankungen und wachsende Ähnlichkeit aufeinanderfolgender Zustände zeigen, dass die Schwelle näher rückt. Ein Datum folgt daraus nicht: Solche Signale können falschen Alarm geben oder vor einem Umbruch ausbleiben.","prueffrage":"Welche drei Veränderungen hat das Team gemessen, und wie würde sich ein stabiles System nach kleinen Störungen verhalten?","rueckmeldung":[{"option":1,"text":"Dass Messwerte allein keine Ursache verraten, stimmt. Die Signale sagen aber etwas anderes aus, nämlich wie nah das System der Schwelle ist, ganz gleich, woher die Störungen kommen. Deshalb darf man aus ihnen durchaus etwas folgern."},{"option":2,"text":"Eine langsame Erholung wirkt, als stecke das System schon im neuen Zustand fest. Die Messwerte zeigen aber, dass es sich noch erholt, nur langsamer. Das ist ein Hinweis auf eine nahende Schwelle, kein Beleg für einen vollzogenen Wechsel."},{"option":3,"text":"Dass Systeme nach Störungen schwanken, ist normal. Hier verändern sich aber drei Größen über Monate in dieselbe Richtung, und das geht über bloßes Rauschen hinaus. Es ist zwar keine Prognose mit Datum, wohl aber ein Anlass, genauer hinzusehen."}],"familie":"systemisch-denken","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Dakos, V. (2011): Expecting the Unexpected. Indicators of Resilience as Early-Warning Signals for Critical Transitions. Diss. Wageningen University (Kap. 2 = Scheffer u. a. 2009)","oeffentlich":true,"url":"https://edepot.wur.nl/168815","seite":"31","abruf":"2026-10-12"},{"typ":"doi","kurz":"Dakos, V. u. a. (2008): Slowing down as an early warning signal for abrupt climate change. PNAS 105(38), 14308–14312","oeffentlich":true,"doi":"10.1073/pnas.0802430105","abruf":"2026-10-12"},{"typ":"url","kurz":"Scheffer, M. u. a. (2009): Early-warning signals for critical transitions. Nature 461, 53–59 (Abstract)","oeffentlich":true,"doi":"10.1038/nature08227","url":"https://pubmed.ncbi.nlm.nih.gov/19727193/","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"72099a2c828cd83e"}},{"id":"qx-a2-047","clusterId":"A","werkstueckRef":"A.24","stufe":1,"question":"Eine Forscherin sieht sich ihre Messdaten erst an und stellt dann fest, dass sich in einer Untergruppe ein „signifikanter“ Effekt zeigt. In ihrer Veröffentlichung schreibt sie, genau diesen Effekt habe sie von Anfang an erwartet. Welche Maßnahme hätte dieses Vorgehen am wirksamsten verhindert?","options":["Hypothese, Stichprobengröße und Auswertungsplan vor der Datenerhebung mit Zeitstempel hinterlegen; spätere Funde als explorativ kennzeichnen.","Die Stichprobe deutlich vergrößern, damit die Studie genug Teststärke hat, um auch kleine echte Effekte sicher zu erkennen.","Die Auswertung verblindet durchführen, sodass die Auswertenden nicht wissen, welcher Teilnehmer zu welcher Gruppe gehört.","Nach dem Erscheinen der Studie zählen, wie viele vergleichbare Studien nie veröffentlicht wurden, und das im Bericht vermerken."],"correctIndex":0,"explanation":"Wer erst die Daten ansieht und dann die Hypothese formuliert (HARKing), findet bei genügend Variablen und Untergruppen fast immer etwas: Es ist, als würde man erst schießen und dann die Zielscheibe malen. Dagegen hilft nur, die Wette vorher zu versiegeln. Wenn Hypothese und Plan vor den Daten feststehen und belegbar sind, lässt sich nachprüfen, ob das Ergebnis erwartet oder nachträglich zurechtgelegt wurde. Alles, was später zusätzlich auftaucht, bleibt erlaubt, zählt aber als Idee für die nächste Studie und nicht als Beweis. Eine Auswertung großer US-Herz-Kreislauf-Studien stützt das: Vor 2000, ohne Pflicht zur vorherigen Festlegung der Zielgröße, meldeten 17 von 30 Studien (57 Prozent) einen Nutzen, danach 2 von 25 (8 Prozent). Die Autoren halten für möglich, dass die Registrierung dazu beitrug. Eine größere Stichprobe erhöht die Teststärke, nimmt dem Zufallsfund in einer Untergruppe aber nicht die Grundlage. Verblindung schützt vor Erwartungseffekten bei der Auswertung, legt aber nicht fest, was vorher behauptet wurde. Und das Zählen unveröffentlichter Studien betrifft den Publikationsbias, nicht die nachträglich zurechtgelegte Hypothese.","coreRule":"⚡ Erst die Wette versiegeln, dann die Karten aufdecken: Hypothese vor den Daten.","quote":"Alles, was danach zusätzlich gefunden wird, ist erlaubt -- aber als *explorativ* zu kennzeichnen, als Idee für die nächste Studie, nicht als Beweis in dieser.","quoteLabel":"Merksatz:","beleg":"Werkstück A.24 (Werkzeug 2: Präregistrierung); Fn. ga-praeregistrierung (Kaplan/Irvin 2015, PLOS ONE 10(8), e0132382; Kerr 1998)","status":"entwurf","scenario":"Eine Studie wertet viele Variablen und Untergruppen aus. Bei genügend Auswertungswegen liefert der Zufall fast immer irgendwo ein „signifikantes“ Muster. Im Bericht steht später, die Hypothese sei von Anfang an klar gewesen.","kurz":"Nur was vorher festgelegt und belegbar hinterlegt wurde, lässt sich später als echte Erwartung prüfen. Wer erst die Daten ansieht, findet bei vielen Untergruppen fast immer etwas, und nachträglich wirkt jeder Fund wie vorhergesagt.","prueffrage":"In wie vielen Untergruppen hat die Forscherin nach einem Effekt gesucht, und in wie vielen ist sie fündig geworden?","rueckmeldung":[{"option":1,"text":"Mehr Teilnehmende erhöhen die Teststärke, das stimmt. Der Zufallsfund in einer Untergruppe bleibt aber möglich, und im Bericht kann er trotzdem als von Anfang an erwartet dargestellt werden."},{"option":2,"text":"Eine verblindete Auswertung schützt vor Erwartungseffekten, das ist ein echter Gewinn. Sie legt aber nicht fest, was vor den Daten behauptet wurde, und die Hypothese lässt sich weiterhin nachträglich zurechtlegen."},{"option":3,"text":"Das Zählen unveröffentlichter Studien zeigt, wie verzerrt die Literatur insgesamt sein kann. Es sagt aber nichts darüber, ob in dieser einen Studie die Hypothese vor den Daten feststand, und setzt erst nach dem Erscheinen an."}],"familie":"muster-im-zufall","fertigkeit":"F4","quellen":[{"typ":"doi","kurz":"Nosek, B. A.; Ebersole, C. R.; DeHaven, A. C.; Mellor, D. T. (2018): The preregistration revolution. PNAS 115(11), 2600–2606","oeffentlich":true,"doi":"10.1073/pnas.1708274114","abruf":"2026-10-12"},{"typ":"doi","kurz":"Kaplan, R. M.; Irvin, V. L. (2015): Likelihood of Null Effects of Large NHLBI Clinical Trials Has Increased over Time. PLOS ONE 10(8), e0132382","oeffentlich":true,"doi":"10.1371/journal.pone.0132382","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Kerr, N. L. (1998): HARKing: Hypothesizing After the Results are Known. Personality and Social Psychology Review 2(3), 196–217","oeffentlich":false}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"c381f0cbef7b7130"}},{"id":"qx-a2-048","clusterId":"A","werkstueckRef":"A.24","stufe":2,"question":"Eine Zeitung titelt: „Mittel wirkt nicht: Ergebnis nicht signifikant (p = 0,06).“ Welche Überlegung ist hier am sinnvollsten?","options":["Bei vielen Auswertungen steigt die Chance auf Zufallsfunde, deshalb müsste zuerst geklärt werden, wie viele Tests durchgeführt wurden.","Aussagekräftig ist ein p-Wert nur bei vorab festgelegter Hypothese, deshalb müsste zuerst geklärt werden, ob die Studie vorab registriert war.","Die Schwelle von 0,05 ist eine Konvention, und eine Wirkung bleibt mit den Daten vereinbar, solange das Konfidenzintervall sie nicht ausschließt.","Ob das Ergebnis auf andere Menschen übertragbar ist, hängt von den Teilnehmenden ab, deshalb müsste zuerst deren Auswahl geklärt werden."],"correctIndex":2,"explanation":"„Nicht signifikant“ heißt nicht „kein Effekt“. Es heißt nur, dass die Daten die Annahme „gar keine Wirkung“ nicht deutlich genug widerlegen. Die Schwelle von 5 Prozent ist eine Konvention, kein Naturgesetz: Ein Ergebnis mit p = 0,06 und eines mit p = 0,04 unterscheiden sich kaum, werden aber als „wirkt nicht“ und „wirkt“ verkauft. Auch ein signifikantes Ergebnis schließt den Zufall nicht aus, und ein nicht signifikantes beweist keine Wirkungslosigkeit. Die American Statistical Association warnte 2016 vor genau diesem Gebrauch des p-Werts, und 2019 forderten über 800 Forschende in Nature, „statistisch signifikant“ nicht länger als Ja-Nein-Urteil zu verwenden. Sinnvoll ist es, das Konfidenzintervall zu lesen: Es zeigt, welche Effektgrößen mit den Daten vereinbar sind, und damit auch, ob eine bedeutsame Wirkung noch möglich ist. Wie viele Tests gemacht wurden, ist für Zufallsfunde wichtig, betrifft aber kaum ein Ergebnis, das gar nicht signifikant wurde. Ob die Studie vorab registriert war, hilft bei der Frage nach nachträglich zurechtgelegten Hypothesen, nicht bei der Deutung des p-Werts. Und wer die Teilnehmenden waren, bestimmt die Übertragbarkeit, ändert aber nichts daran, dass „nicht signifikant“ nicht „wirkungslos“ heißt.","coreRule":"⚡ Lies das Intervall, nicht nur das Etikett „signifikant“ oder „nicht signifikant“.","beleg":"Werkstück A.24 (Werkzeug 3: Konfidenzintervall); Fn. ga-signifikanz (Wasserstein/Lazar 2016, The American Statistician 70(2), S. 131–132; Amrhein u. a. 2019, Nature 567, S. 305–307)","status":"entwurf","scenario":"In der Meldung steht nur der p-Wert. Zur Größe des Effekts oder zu einem Konfidenzintervall wird nichts gesagt.","kurz":"„Nicht signifikant“ heißt nicht „wirkungslos“: Die Daten widerlegen „keine Wirkung“ nur nicht deutlich genug, und die Schwelle von 0,05 ist bloß eine Konvention. Erst das Konfidenzintervall zeigt, welche Effekte noch möglich sind.","prueffrage":"Würde die Schlagzeile umgekehrt lauten, wenn p = 0,04 herausgekommen wäre, und wie groß wäre dieser Unterschied in den Daten?","rueckmeldung":[{"option":0,"text":"Viele Auswertungen erzeugen tatsächlich leicht Zufallsfunde. Das Problem sind aber zufällige Treffer, und hier wurde gerade kein Treffer gemeldet. Für die Frage, ob „nicht signifikant“ „wirkungslos“ heißt, bringt die Zahl der Tests kaum etwas."},{"option":1,"text":"Eine Vorab-Registrierung schützt davor, dass Hypothesen nachträglich zurechtgelegt werden, und ist ein gutes Qualitätsmerkmal. Sie sagt aber nichts darüber, was ein p-Wert von 0,06 bedeutet, und löst deshalb das eigentliche Problem der Schlagzeile nicht."},{"option":3,"text":"Wer teilgenommen hat, bestimmt, auf wen sich ein Befund übertragen lässt. Das ist eine andere Frage als die der Schlagzeile: Auch bei bester Auswahl bliebe „nicht signifikant“ nicht gleichbedeutend mit „wirkungslos“."}],"familie":"studie-genau-lesen","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"American Statistical Association (2016): ASA releases statement on statistical significance and p-values (Pressemitteilung, 7. März 2016)","oeffentlich":true,"url":"https://www.amstat.org/asa/files/pdfs/p-valuestatement.pdf","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Wasserstein, R. L.; Lazar, N. A. (2016): The ASA Statement on p-Values: Context, Process, and Purpose. The American Statistician 70(2), 129–133","oeffentlich":false,"doi":"10.1080/00031305.2016.1154108"},{"typ":"literatur","kurz":"Amrhein, V.; Greenland, S.; McShane, B. (2019): Scientists rise up against statistical significance. Nature 567, 305–307","oeffentlich":false,"doi":"10.1038/d41586-019-00857-9"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"cf4ecb130a6f1326"}},{"id":"qx-a2-049","clusterId":"A","werkstueckRef":"A.24","stufe":3,"question":"Was folgt aus diesen Angaben?","options":["Der Effekt ist nicht ursächlich belegt, weil eine Korrelation allein nie beweist, dass das eine das andere hervorruft.","Der Effekt ist wahrscheinlich ein Zufallsfund, weil bei vielen Auswertungen irgendein Ergebnis zufällig signifikant wird.","Der Effekt ist statistisch nachweisbar, aber praktisch winzig, weil Signifikanz nichts über die Größe eines Effekts aussagt.","Der Effekt gilt nur für diese Teilnehmer, weil Nutzer eines einzelnen Netzwerks nicht alle Menschen vertreten."],"correctIndex":2,"explanation":"Mit einer hinreichend großen Stichprobe wird jeder noch so winzige Unterschied signifikant. Signifikanz sagt nur, dass die Daten schlecht zur Annahme „gar kein Effekt“ passen, nicht, wie groß der Effekt ist. Die gemeldeten Werte (d = 0,001 bis 0,02) liegen deutlich unter der Konvention für einen kleinen Effekt (ab d = 0,2) und sind im Alltag eines einzelnen Nutzers unsichtbar. Die Schlagzeile verwechselt „nachweisbar“ mit „bedeutend“. Die prüfende Frage lautet: Wie groß ist der Effekt in einer Einheit, die ich mir vorstellen kann? Dass Korrelation keine Ursache beweist, stimmt, aber hier wurden die Feeds gezielt manipuliert, es liegt also ein Eingriff vor und nicht bloß eine Beobachtung. Zufallsfunde bei vielen Tests sind ein bekanntes Problem, doch der p-Wert ist hier extrem klein, und gefragt ist nach der Größe, nicht nach dem Zufall. Und wie weit sich ein Befund übertragen lässt, ist eine andere Frage als die nach seiner Größe.","coreRule":"⚡ Signifikanz beantwortet „Gibt es etwas?“, die Effektstärke „Wie viel?“.","beleg":"Werkstück A.24 (Werkzeug 4: Effektstärke); Fn. ga-effektstaerke (Kramer u. a. 2014, PNAS 111(24), S. 8788–8790; Cohen 1988)","status":"entwurf","scenario":"Eine Schlagzeile lautet: „Studie beweist: Gefühle stecken über soziale Netzwerke an.“ Im Studienbericht steht: Bei 689.003 Teilnehmern „steckte“ die Stimmung durch manipulierte Nachrichtenfeeds messbar an; das Ergebnis ist hochsignifikant (p-Wert extrem klein), die Effektstärke d liegt zwischen 0,001 und 0,02. Als Faustregel gilt: Ab d = 0,2 spricht man von einem kleinen, ab 0,5 von einem mittleren und ab 0,8 von einem großen Effekt.","kurz":"Bei fast 700.000 Teilnehmern wird schon ein winziger Unterschied hochsignifikant. Der p-Wert zeigt nur, dass „gar kein Effekt“ schlecht passt, nicht wie groß er ist: d zwischen 0,001 und 0,02 liegt weit unter dem Wert für einen kleinen Effekt.","prueffrage":"Wie viel Stimmungsänderung steckt in diesem Wert, wenn du ihn in etwas Greifbares umrechnest?","rueckmeldung":[{"option":0,"text":"Als Grundsatz stimmt das: Aus bloßer Korrelation folgt keine Ursache. Hier wurden die Feeds aber gezielt verändert, es liegt also ein Eingriff vor und keine reine Beobachtung. Offen ist nicht die Ursache, sondern wie groß der Effekt ausfällt."},{"option":1,"text":"Zufallsfunde bei vielen Auswertungen sind tatsächlich ein bekanntes Problem. Hier ist der p-Wert aber extrem klein, der Effekt also nachweisbar. Fraglich ist nicht, ob er zufällig auftritt, sondern ob er mit d unter 0,02 überhaupt eine Bedeutung hat."},{"option":3,"text":"Wie weit sich ein Befund übertragen lässt, ist eine berechtigte Frage, aber eine andere als die gestellte. Selbst wenn er für alle Menschen gälte, bliebe er mit d unter 0,02 winzig. Die Größe des Effekts ist damit nicht beantwortet."}],"familie":"studie-genau-lesen","fertigkeit":"F4","quellen":[{"typ":"doi","kurz":"Kramer, A. D. I.; Guillory, J. E.; Hancock, J. T. (2014): Experimental evidence of massive-scale emotional contagion through social networks. PNAS 111(24), 8788–8790","oeffentlich":true,"doi":"10.1073/pnas.1320040111","abruf":"2026-10-12"},{"typ":"url","kurz":"American Statistical Association (2016): ASA releases statement on statistical significance and p-values (Pressemitteilung)","oeffentlich":true,"url":"https://www.amstat.org/asa/files/pdfs/p-valuestatement.pdf","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Cohen, J. (1988): Statistical Power Analysis for the Behavioral Sciences. 2. Aufl. Hillsdale: Erlbaum","oeffentlich":false}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"90c00dbb1f82ff36"}},{"id":"qx-a2-050","clusterId":"A","werkstueckRef":"A.24","stufe":4,"question":"Welche Frage prüft diesen Schluss am besten?","options":["Wie sieht das Verhältnis aus, wenn man Geimpfte und Ungeimpfte innerhalb derselben Altersgruppe vergleicht?","Wie zuverlässig wurde in den Krankenhäusern der Impfstatus der Schwerkranken erfasst, und wie vollständig sind die Meldungen?","Wie viele Schwerkranke wurden insgesamt gezählt, und reicht diese Zahl aus, um verlässliche Aussagen zu treffen?","Wer hat die Zahlen erhoben und veröffentlicht, und hat diese Stelle ein erkennbares Interesse an einem bestimmten Ergebnis?"],"correctIndex":0,"explanation":"Die Gesamtzahl vermischt Gruppen, die sich im Risiko stark unterscheiden. Sind die Gefährdetsten zugleich fast alle geimpft, stellen Geimpfte einen großen Teil der Schwerkranken, selbst wenn die Impfung das Risiko in jeder Altersgruppe deutlich senkt. Ein solcher Zusammenhang, der in der Gesamtheit anders aussieht als in den Teilgruppen, heißt Simpson-Paradox. Ein berühmtes Beispiel: Berkeley 1973 ließ 44 Prozent der männlichen, aber nur 35 Prozent der weiblichen Bewerber zu. Nach Fachbereichen aufgeschlüsselt zeigte sich kein Nachteil für Frauen, weil sie sich häufiger in Fächern mit niedrigen Zulassungsquoten beworben hatten. Der Vergleich innerhalb gleicher Gruppen entscheidet also, was die Zahlen aussagen. Vorsicht in der Gegenrichtung: Nicht jede Aufteilung ist die richtige, und welche gilt, verraten die Zahlen allein nicht. Die Erfassung des Impfstatus zu prüfen ist ein sinnvoller Datencheck, ändert aber nichts daran, dass die Gesamtzahl Gruppen mischt. Die Fallzahl schützt vor Zufallsschwankungen, nicht vor der Vermischung unterschiedlicher Risikogruppen. Und die Frage nach dem Interesse hinter den Zahlen betrifft die Quelle, nicht die Rechnung.","coreRule":"⚡ Teile die Gruppen auf, aber frag, welche Aufteilung der Zusammenhang wirklich verlangt.","beleg":"Werkstück A.24 (Werkzeug 5: Das Simpson-Paradox); Fn. ga-simpson (Bickel/Hammel/O'Connell 1975, Science 187(4175), S. 398–404; Morris 2021; Pearl 2014, The American Statistician 68(1), S. 8–13)","status":"entwurf","scenario":"In einem Land mit hoher Impfquote meldet eine Zeitung: „Mehr als die Hälfte der Schwerkranken im Krankenhaus ist geimpft. Die Impfung schützt also kaum.“ Bekannt ist außerdem: Die Ältesten sind fast vollständig geimpft und zugleich am stärksten gefährdet, schwer zu erkranken.","kurz":"Die Gesamtzahl mischt Gruppen mit sehr verschiedenem Risiko: Sind die am stärksten Gefährdeten fast alle geimpft, stellen Geimpfte viele Schwerkranke, auch wenn die Impfung in jeder Altersgruppe schützt. Erst der Vergleich innerhalb gleicher Gruppen zeigt, was die Zahlen aussagen.","prueffrage":"Unterscheiden sich die Geimpften und die Ungeimpften im Land außer durch die Impfung noch in etwas, das ihr Risiko für eine schwere Erkrankung beeinflusst?","rueckmeldung":[{"option":1,"text":"Zu prüfen, wie sauber der Impfstatus erfasst wurde, ist ein sinnvoller Datencheck. Selbst lückenlose Daten ließen die Gesamtzahl aber Gruppen mit sehr unterschiedlichem Risiko vermengen, und genau dort liegt der Schwachpunkt des Schlusses."},{"option":2,"text":"Eine ausreichende Fallzahl schützt vor Zufallsschwankungen, und danach zu fragen ist berechtigt. Hier liegt das Problem aber nicht im Zufall: Auch eine sehr große Zahl bliebe irreführend, wenn sie Gruppen mit unterschiedlichem Risiko zusammenwirft."},{"option":3,"text":"Nach der Quelle und ihrem Interesse zu fragen, ist grundsätzlich klug, betrifft aber die Herkunft der Zahlen, nicht die Rechnung. Auch bei einer völlig neutralen Stelle bliebe der Schluss aus der Gesamtzahl fragwürdig."}],"familie":"studie-genau-lesen","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Morris, J. (2021): Israeli data: How can efficacy vs. severe disease be strong when 60% of hospitalized are vaccinated? Covid Data Science","oeffentlich":true,"url":"https://www.covid-datascience.com/post/israeli-data-how-can-efficacy-vs-severe-disease-be-strong-when-60-of-hospitalized-are-vaccinated","abruf":"2026-10-12"},{"typ":"url","kurz":"Pearl, J. (2013): Understanding Simpson's Paradox. UCLA Technical Report R-414 (Vorfassung zu The American Statistician 68(1), 2014)","oeffentlich":true,"url":"https://ftp.cs.ucla.edu/pub/stat_ser/r414.pdf","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Bickel, P. J.; Hammel, E. A.; O'Connell, J. W. (1975): Sex Bias in Graduate Admissions: Data from Berkeley. Science 187(4175), 398–404","oeffentlich":false}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"27f036beee45cab8"}}]`);export{t as n,n as t};